/* ============================================================================
   AI Dotsquares — custom.js

   Combined site JavaScript. Major sections (search labels to jump):
   - DS_ASSET_BASE     — relative asset path for subfolder pages
   - Page loader       — blur overlay + progress bar
   - Shared site UI    — header, nav, chatbot, contact forms
   - Homepage labs     — CV showcase, ML playground, geospatial, CRM
   - Service pages     — per-service labs (agp, awp, azp, ggp, cvp, …)
   - Product demos     — NST, Face Filter, Deep Fake, IDA, Traffic
   - Offices globe     — iframe bridge for #offices map
   - Blogs             — listing filters, insights carousel, detail TOC
   ============================================================================ */
(function () {
  /* Pages in subfolders need ../asset/ — root pages use asset/ */
  var path = (location.pathname || '').replace(/\\/g, '/');
  window.DS_ASSET_BASE = /\/(playgrounds|services|products|blog|case-study)\//.test(path) ? '../asset/' : 'asset/';
})();

/* ==========================================================================
   Global page loader — blur overlay, centered line, logo, percent
   ========================================================================== */
(function () {
  if (document.getElementById('dsPageLoader')) return;

  var logoSrc = (window.DS_ASSET_BASE || 'asset/') + 'logo.svg';
  var root = document.createElement('div');
  root.id = 'dsPageLoader';
  root.className = 'ds-page-loader';
  root.setAttribute('role', 'progressbar');
  root.setAttribute('aria-label', 'WebRanker loading');
  root.setAttribute('aria-valuemin', '0');
  root.setAttribute('aria-valuemax', '100');
  root.setAttribute('aria-valuenow', '0');
  root.innerHTML =
    '<div class="ds-page-loader__panel">' +
      '<div class="ds-page-loader__logo-wrap" style="display:inline-flex;align-items:center;gap:12px;margin-bottom:0.25rem;">' +
        '<svg class="ds-page-loader__logo-icon" viewBox="0 0 54 54" width="38" height="38" fill="none" xmlns="http://www.w3.org/2000/svg" style="display:block;flex-shrink:0;">' +
          '<path d="M8 10 V40 C8 44.4 11.6 48 16 48 H48" stroke="#ffffff" stroke-width="4.8" stroke-linecap="round" stroke-linejoin="round"/>' +
          '<path d="M14 37 L24 24 L33 32 L46 12" stroke="#ff3b30" stroke-width="4.8" stroke-linecap="round" stroke-linejoin="round"/>' +
        '</svg>' +
        '<span style="font-family:\'Urbanist\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif;font-size:2rem;font-weight:900;letter-spacing:-0.03em;line-height:1;">' +
          '<span style="color:#ff3b30;">Web</span><span style="color:#ffffff;">Ranker</span>' +
        '</span>' +
      '</div>' +
      '<div class="ds-page-loader__row">' +
        '<div class="ds-page-loader__track"><div class="ds-page-loader__bar" id="dsPageLoaderBar"></div></div>' +
        '<span class="ds-page-loader__pct" id="dsPageLoaderPct">0%</span>' +
      '</div>' +
    '</div>';

  var bar = root.querySelector('.ds-page-loader__bar');
  var pct = root.querySelector('.ds-page-loader__pct');
  var progress = 6;
  var done = false;
  var tickTimer;

  function lockPage() {
    document.documentElement.classList.add('is-page-loading');
  }

  function unlockPage() {
    document.documentElement.classList.remove('is-page-loading');
  }

  function mount() {
    if (!document.body) {
      document.addEventListener('DOMContentLoaded', mount, { once: true });
      return;
    }
    lockPage();
    document.body.appendChild(root);
    setProgress(progress);
    tickTimer = setInterval(function () {
      if (done || progress >= 96) return;
      setProgress(progress + (96 - progress) * 0.14);
    }, 90);
    boot();
  }

  function setProgress(value) {
    progress = Math.min(100, Math.max(progress, value));
    var rounded = Math.round(progress);
    if (bar) bar.style.width = progress + '%';
    if (pct) pct.textContent = rounded + '%';
    root.setAttribute('aria-valuenow', String(rounded));
  }

  function finish() {
    if (done) return;
    done = true;
    clearInterval(tickTimer);
    setProgress(100);
    root.classList.add('is-complete');
    window.setTimeout(function () {
      root.classList.add('is-hidden');
      unlockPage();
      document.documentElement.classList.add('is-page-loaded');
      window.setTimeout(function () {
        if (root.parentNode) root.parentNode.removeChild(root);
      }, 480);
    }, 280);
  }

  function boot() {
    window.setTimeout(finish, 2000);
  }

  mount();
})();

/* ==========================================================================
   Hero heading — video clipped inside text letters only
   ========================================================================== */
(function () {
  function initHeroHeadingVideoMask() {
    var wrap = document.querySelector('.hero-lab-heading-video');
    if (!wrap) return;
    var label = wrap.querySelector('.hero-lab-heading-video__label');
    var video = wrap.querySelector('.hero-lab-heading-video__media');
    if (!label || !video) return;

    var canvas = document.createElement('canvas');
    var ctx = canvas.getContext('2d');
    if (!ctx) return;
    var resizeTimer;
    var maskJob = 0;

    function layoutVideo(padX, padY) {
      video.style.top = -padY + 'px';
      video.style.left = -padX + 'px';
      video.style.width = 'calc(100% + ' + (padX * 2) + 'px)';
      video.style.height = 'calc(100% + ' + (padY * 2) + 'px)';
    }

    function applyMask() {
      var job = ++maskJob;
      var style = window.getComputedStyle(label);
      var fontSize = parseFloat(style.fontSize) || 48;
      var padX = Math.ceil(fontSize * 0.28);
      var padY = Math.ceil(fontSize * 0.16);
      layoutVideo(padX, padY);

      var rect = label.getBoundingClientRect();
      var textW = Math.max(1, Math.ceil(rect.width));
      var textH = Math.max(1, Math.ceil(rect.height));
      var cw = textW + padX * 2;
      var ch = textH + padY * 2;
      var dpr = Math.min(window.devicePixelRatio || 1, 2);

      var divStyle = [
        'margin:0',
        'padding:0',
        'width:' + textW + 'px',
        'font:' + style.font,
        'font-weight:' + style.fontWeight,
        'letter-spacing:' + style.letterSpacing,
        'line-height:' + style.lineHeight,
        'text-align:center',
        'color:#ffffff',
        'background:#000000',
        'white-space:normal',
        'word-break:normal'
      ].join(';');

      var svg =
        '<svg xmlns="http://www.w3.org/2000/svg" width="' + cw + '" height="' + ch + '">' +
        '<foreignObject x="' + padX + '" y="' + padY + '" width="' + textW + '" height="' + textH + '">' +
        '<div xmlns="http://www.w3.org/1999/xhtml" style="' + divStyle + '">' + label.innerHTML + '</div>' +
        '</foreignObject></svg>';

      var img = new Image();
      img.onload = function () {
        if (job !== maskJob) return;
        canvas.width = Math.round(cw * dpr);
        canvas.height = Math.round(ch * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.clearRect(0, 0, cw, ch);
        ctx.drawImage(img, 0, 0, cw, ch);
        var maskUrl = canvas.toDataURL('image/png');
        video.style.webkitMaskImage = 'url("' + maskUrl + '")';
        video.style.maskImage = 'url("' + maskUrl + '")';
      };
      img.onerror = function () {
        if (job !== maskJob) return;
        canvas.width = Math.round(cw * dpr);
        canvas.height = Math.round(ch * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, cw, ch);
        ctx.fillStyle = '#fff';
        ctx.font = style.font;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        var lines = (label.innerText || '').split('\n');
        var lineHeight = parseFloat(style.lineHeight);
        if (!lineHeight || isNaN(lineHeight)) lineHeight = fontSize * 1.12;
        var startY = padY + lineHeight / 2;
        lines.forEach(function (line, i) {
          ctx.fillText(line.trim(), cw / 2, startY + i * lineHeight);
        });
        var maskUrl = canvas.toDataURL('image/png');
        video.style.webkitMaskImage = 'url("' + maskUrl + '")';
        video.style.maskImage = 'url("' + maskUrl + '")';
      };
      img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    }

    function schedule() {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(applyMask, 80);
    }

    function boot() {
      applyMask();
      window.addEventListener('resize', schedule);
      if (typeof ResizeObserver !== 'undefined') {
        new ResizeObserver(schedule).observe(label);
      }
      video.addEventListener('loadeddata', applyMask);
    }

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(boot).catch(boot);
    } else {
      boot();
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initHeroHeadingVideoMask);
  } else {
    initHeroHeadingVideoMask();
  }
})();


/* ==========================================================================
   Hero 3D lab — homepage #home (Three.js stage)
   Auto-plays in the background. Heading + console stay on top.
   ========================================================================== */
/* AI Dotsquares hero — 3D stage auto-plays in the background.
   Heading stays visible. Camera is not driven by page scroll. */
(function () {
  const holder = document.getElementById('heroLabCanvas');
  const section = document.querySelector('.hero-lab-section');
  if (!holder || !section || typeof THREE === 'undefined') {
    if (section) section.classList.add('is-ready');
    return;
  }

  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduceMotion) {
    section.classList.add('is-ready');
    return;
  }

  const ORANGE = 0xf58220;
  const isMobile = window.innerWidth < 900;

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'high-performance' });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, isMobile ? 1.25 : 2));
  renderer.setSize(holder.clientWidth, holder.clientHeight);
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.12;
  renderer.shadowMap.enabled = !isMobile;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  holder.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x0f152f);
  scene.fog = new THREE.FogExp2(0x0f152f, 0.018);

  const camera = new THREE.PerspectiveCamera(46, holder.clientWidth / holder.clientHeight, 0.1, 200);
  camera.position.set(0, 2.25, 16.2);

  scene.add(new THREE.HemisphereLight(0x2a2c34, 0x050506, 0.32));
  const key = new THREE.DirectionalLight(0xe8e4dc, 0.85);
  key.position.set(6, 9, 6);
  key.castShadow = !isMobile;
  if (!isMobile) {
    key.shadow.mapSize.set(1024, 1024);
    key.shadow.camera.near = 1;
    key.shadow.camera.far = 40;
    key.shadow.camera.left = -12;
    key.shadow.camera.right = 12;
    key.shadow.camera.top = 12;
    key.shadow.camera.bottom = -12;
    key.shadow.bias = -0.0015;
  }
  scene.add(key);
  const rim = new THREE.DirectionalLight(0x3a3d4a, 0.28);
  rim.position.set(-8, 4, -6);
  scene.add(rim);
  const coreLight = new THREE.PointLight(ORANGE, 2.4, 12, 2);
  coreLight.position.set(0, 1.15, 0);
  scene.add(coreLight);

  function buildEnvMap() {
    const size = 256;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const grad = ctx.createLinearGradient(0, 0, 0, size);
    grad.addColorStop(0, '#3a3d4a');
    grad.addColorStop(0.45, '#14151c');
    grad.addColorStop(0.55, '#0f152f');
    grad.addColorStop(1, '#050506');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, size, size);
    ctx.fillStyle = 'rgba(245,130,32,0.04)';
    ctx.beginPath();
    ctx.ellipse(size * 0.5, size * 0.52, size * 0.5, size * 0.06, 0, 0, Math.PI * 2);
    ctx.fill();
    const tex = new THREE.CanvasTexture(canvas);
    tex.mapping = THREE.EquirectangularReflectionMapping;
    tex.encoding = THREE.sRGBEncoding;
    return tex;
  }
  const envMap = buildEnvMap();
  scene.environment = envMap;

  const matGlass = new THREE.MeshPhysicalMaterial({
    color: 0x9aa0a8, metalness: 0, roughness: 0.06,
    transmission: 0.9, transparent: true, opacity: 1,
    envMap, envMapIntensity: 1.35, clearcoat: 1, clearcoatRoughness: 0.06
  });
  const matMetal = new THREE.MeshStandardMaterial({
    color: 0x9b9d9f, metalness: 0.9, roughness: 0.28, envMap, envMapIntensity: 1.15
  });
  const matMetalDark = new THREE.MeshStandardMaterial({
    color: 0x2b2c2f, metalness: 0.85, roughness: 0.35, envMap, envMapIntensity: 0.9
  });
  const matOrange = new THREE.MeshStandardMaterial({
    color: 0x1a1410, emissive: ORANGE, emissiveIntensity: 1.55, metalness: 0.15, roughness: 0.4
  });
  const matPolymer = new THREE.MeshPhysicalMaterial({
    color: 0x6d7580, metalness: 0, roughness: 0.16, transmission: 0.72,
    transparent: true, envMap, envMapIntensity: 1
  });

  const stage = new THREE.Group();
  scene.add(stage);

  const floor = new THREE.Mesh(
    new THREE.CircleGeometry(28, 64),
    new THREE.MeshStandardMaterial({ color: 0x08080a, metalness: 0.12, roughness: 0.82, envMap, envMapIntensity: 0.08 })
  );
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -2.55;
  floor.receiveShadow = true;
  stage.add(floor);

  for (let i = 1; i <= 5; i++) {
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(i * 2.1, i * 2.1 + 0.012, 80),
      new THREE.MeshBasicMaterial({ color: 0x1a1c22, side: THREE.DoubleSide, transparent: true, opacity: 0.18 })
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = -2.54;
    stage.add(ring);
  }

  function buildDust() {
    const count = isMobile ? 360 : 780;
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 36;
      pos[i * 3 + 1] = Math.random() * 12 - 2.4;
      pos[i * 3 + 2] = (Math.random() - 0.5) * 36;
    }
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    return new THREE.Points(geo, new THREE.PointsMaterial({
      color: 0x9aa0b0, size: 0.018, transparent: true, opacity: 0.3, depthWrite: false
    }));
  }
  const dust = buildDust();
  stage.add(dust);

  function makeCircuitTex() {
    const c = document.createElement('canvas');
    c.width = 1024;
    c.height = 1024;
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#0f152f';
    ctx.fillRect(0, 0, 1024, 1024);
    ctx.strokeStyle = 'rgba(170,176,190,0.14)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 16; i++) {
      ctx.beginPath();
      ctx.moveTo(i * 64, 0);
      ctx.lineTo(i * 64, 1024);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * 64);
      ctx.lineTo(1024, i * 64);
      ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(245,130,32,0.18)';
    ctx.lineWidth = 1.5;
    const traces = [
      [80, 180, 320, 180, 320, 420, 540, 420],
      [700, 120, 700, 360, 860, 360, 860, 620],
      [140, 760, 420, 760, 420, 540, 640, 540],
      [200, 300, 200, 640, 80, 640]
    ];
    traces.forEach((pts) => {
      ctx.beginPath();
      ctx.moveTo(pts[0], pts[1]);
      for (let i = 2; i < pts.length; i += 2) ctx.lineTo(pts[i], pts[i + 1]);
      ctx.stroke();
    });
    ctx.fillStyle = 'rgba(245,130,32,0.32)';
    [[80, 180], [320, 420], [700, 120], [860, 620], [420, 760], [640, 540], [200, 300]].forEach(([x, y]) => {
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });
    const tex = new THREE.CanvasTexture(c);
    tex.encoding = THREE.sRGBEncoding;
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(1.4, 1.4);
    return tex;
  }

  const circuitWall = new THREE.Mesh(
    new THREE.PlaneGeometry(42, 24),
    new THREE.MeshBasicMaterial({
      map: makeCircuitTex(),
      transparent: true,
      opacity: 0.38,
      depthWrite: false
    })
  );
  circuitWall.position.set(0, 3.2, -14);
  stage.add(circuitWall);

  const cagePos = [];
  const cageR = 17;
  const cageN = 20;
  for (let i = 0; i < cageN; i++) {
    const a = (i / cageN) * Math.PI * 2;
    const x = Math.cos(a) * cageR;
    const z = Math.sin(a) * cageR;
    cagePos.push(x, -2.5, z, x, 7.5, z);
  }
  [1.6, 4.8].forEach((y) => {
    for (let i = 0; i < cageN; i++) {
      const a0 = (i / cageN) * Math.PI * 2;
      const a1 = ((i + 1) / cageN) * Math.PI * 2;
      cagePos.push(
        Math.cos(a0) * cageR, y, Math.sin(a0) * cageR,
        Math.cos(a1) * cageR, y, Math.sin(a1) * cageR
      );
    }
  });
  const cage = new THREE.LineSegments(
    new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(cagePos, 3)),
    new THREE.LineBasicMaterial({ color: 0x3a3e48, transparent: true, opacity: 0.2 })
  );
  stage.add(cage);

  const tracePos = [];
  for (let i = 0; i < 28; i++) {
    const x = (Math.random() - 0.5) * 28;
    const y = Math.random() * 8 - 0.8;
    const z = (Math.random() - 0.5) * 28;
    const len = 0.8 + Math.random() * 2.2;
    const axis = Math.floor(Math.random() * 3);
    tracePos.push(x, y, z);
    tracePos.push(
      x + (axis === 0 ? len : 0),
      y + (axis === 1 ? len : 0),
      z + (axis === 2 ? len : 0)
    );
  }
  const traces = new THREE.LineSegments(
    new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(tracePos, 3)),
    new THREE.LineBasicMaterial({ color: 0x5a5f6c, transparent: true, opacity: 0.28 })
  );
  stage.add(traces);

  const matWhite = new THREE.MeshStandardMaterial({
    color: 0xe8e4dc, metalness: 0.25, roughness: 0.35, envMap, envMapIntensity: 0.8
  });
  const matTile = new THREE.MeshPhysicalMaterial({
    color: 0x1c1e24, metalness: 0.15, roughness: 0.25, transmission: 0.12,
    transparent: true, opacity: 0.92, envMap, envMapIntensity: 0.7
  });

  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function makePanelTex(title, sub) {
    const c = document.createElement('canvas');
    c.width = 768;
    c.height = 420;
    const ctx = c.getContext('2d');
    roundRect(ctx, 18, 18, 732, 384, 48);
    ctx.fillStyle = 'rgba(18,19,24,0.82)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(232,228,220,0.18)';
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.fillStyle = '#f4f1ea';
    ctx.font = '700 52px Urbanist, sans-serif';
    ctx.textAlign = 'left';
    const parts = title.split('AI');
    let x = 56;
    ctx.fillText(parts[0], x, 130);
    x += ctx.measureText(parts[0]).width;
    ctx.fillStyle = '#F58220';
    ctx.fillText('AI', x, 130);
    x += ctx.measureText('AI').width;
    ctx.fillStyle = '#f4f1ea';
    ctx.fillText(parts[1] || '', x, 130);
    ctx.fillStyle = 'rgba(244,241,234,0.62)';
    ctx.font = '400 26px Urbanist, sans-serif';
    ctx.fillText(sub, 56, 188);
    const tex = new THREE.CanvasTexture(c);
    tex.encoding = THREE.sRGBEncoding;
    return tex;
  }

  function makeIconTex(draw) {
    const c = document.createElement('canvas');
    c.width = 128;
    c.height = 128;
    const ctx = c.getContext('2d');
    roundRect(ctx, 8, 8, 112, 112, 28);
    ctx.fillStyle = 'rgba(28,30,36,0.92)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(245,130,32,0.35)';
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.strokeStyle = '#f4f1ea';
    ctx.fillStyle = '#f4f1ea';
    ctx.lineWidth = 5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    draw(ctx);
    const tex = new THREE.CanvasTexture(c);
    tex.encoding = THREE.sRGBEncoding;
    return tex;
  }

  function iconTile(draw, x, y, z) {
    const g = new THREE.Group();
    const tile = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.42, 0.08), matTile);
    g.add(tile);
    const face = new THREE.Mesh(
      new THREE.PlaneGeometry(0.38, 0.38),
      new THREE.MeshBasicMaterial({ map: makeIconTex(draw), transparent: true })
    );
    face.position.z = 0.05;
    g.add(face);
    g.position.set(x, y, z);
    g.userData.base = new THREE.Vector3(x, y, z);
    g.userData.phase = x + y;
    return g;
  }

  const draws = {
    bolt: (ctx) => { ctx.beginPath(); ctx.moveTo(72, 28); ctx.lineTo(52, 64); ctx.lineTo(68, 64); ctx.lineTo(48, 100); ctx.lineTo(84, 58); ctx.lineTo(66, 58); ctx.closePath(); ctx.fill(); },
    brain: (ctx) => { ctx.beginPath(); ctx.arc(64, 58, 28, 0.2, Math.PI - 0.2); ctx.stroke(); ctx.beginPath(); ctx.arc(52, 52, 12, 0, Math.PI * 2); ctx.stroke(); ctx.beginPath(); ctx.arc(76, 52, 12, 0, Math.PI * 2); ctx.stroke(); },
    chart: (ctx) => { ctx.beginPath(); ctx.moveTo(36, 92); ctx.lineTo(36, 40); ctx.moveTo(36, 92); ctx.lineTo(96, 92); ctx.stroke(); ctx.fillRect(44, 62, 12, 30); ctx.fillRect(62, 48, 12, 44); ctx.fillRect(80, 36, 12, 56); },
    gear: (ctx) => { ctx.beginPath(); ctx.arc(64, 64, 16, 0, Math.PI * 2); ctx.stroke(); ctx.beginPath(); ctx.arc(64, 64, 7, 0, Math.PI * 2); ctx.stroke(); for (let i = 0; i < 6; i++) { const a = i * Math.PI / 3; ctx.beginPath(); ctx.moveTo(64 + Math.cos(a) * 16, 64 + Math.sin(a) * 16); ctx.lineTo(64 + Math.cos(a) * 26, 64 + Math.sin(a) * 26); ctx.stroke(); } },
    chip: (ctx) => { ctx.strokeRect(44, 44, 40, 40); for (let i = 0; i < 4; i++) { ctx.fillRect(38, 50 + i * 8, 6, 4); ctx.fillRect(84, 50 + i * 8, 6, 4); } },
    chat: (ctx) => { roundRect(ctx, 34, 36, 60, 42, 10); ctx.stroke(); ctx.beginPath(); ctx.moveTo(48, 78); ctx.lineTo(42, 96); ctx.lineTo(62, 78); ctx.stroke(); ctx.beginPath(); ctx.arc(50, 56, 3, 0, Math.PI * 2); ctx.arc(64, 56, 3, 0, Math.PI * 2); ctx.arc(78, 56, 3, 0, Math.PI * 2); ctx.fill(); },
    image: (ctx) => { ctx.strokeRect(36, 40, 56, 48); ctx.beginPath(); ctx.moveTo(36, 78); ctx.lineTo(54, 58); ctx.lineTo(70, 72); ctx.lineTo(82, 62); ctx.lineTo(92, 78); ctx.stroke(); ctx.beginPath(); ctx.arc(50, 52, 5, 0, Math.PI * 2); ctx.fill(); },
    db: (ctx) => { ctx.beginPath(); ctx.ellipse(64, 42, 24, 10, 0, 0, Math.PI * 2); ctx.stroke(); ctx.beginPath(); ctx.ellipse(64, 64, 24, 10, 0, 0, Math.PI * 2); ctx.stroke(); ctx.beginPath(); ctx.ellipse(64, 86, 24, 10, 0, 0, Math.PI * 2); ctx.stroke(); ctx.beginPath(); ctx.moveTo(40, 42); ctx.lineTo(40, 86); ctx.moveTo(88, 42); ctx.lineTo(88, 86); ctx.stroke(); },
    code: (ctx) => { ctx.font = '700 36px JetBrains Mono, monospace'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText('</>', 64, 68); },
    cloud: (ctx) => { ctx.beginPath(); ctx.arc(50, 68, 16, 0, Math.PI * 2); ctx.arc(70, 62, 20, 0, Math.PI * 2); ctx.arc(88, 70, 14, 0, Math.PI * 2); ctx.fill(); },
    flow: (ctx) => { ctx.strokeRect(36, 36, 22, 18); ctx.strokeRect(70, 36, 22, 18); ctx.strokeRect(52, 74, 24, 18); ctx.beginPath(); ctx.moveTo(47, 54); ctx.lineTo(47, 66); ctx.lineTo(64, 66); ctx.lineTo(64, 74); ctx.moveTo(81, 54); ctx.lineTo(81, 66); ctx.stroke(); }
  };

  function glassPanel(title, sub, w, h) {
    return new THREE.Mesh(
      new THREE.PlaneGeometry(w, h),
      new THREE.MeshBasicMaterial({ map: makePanelTex(title, sub), transparent: true, depthWrite: false, side: THREE.DoubleSide })
    );
  }

  function makeAiMark() {
    const c = document.createElement('canvas');
    c.width = 256;
    c.height = 256;
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#f4f1ea';
    ctx.font = '700 110px Urbanist, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('AI', 128, 136);
    const tex = new THREE.CanvasTexture(c);
    tex.encoding = THREE.sRGBEncoding;
    return tex;
  }

  function makeScreenTex() {
    const c = document.createElement('canvas');
    c.width = 512;
    c.height = 320;
    const ctx = c.getContext('2d');
    ctx.fillStyle = '#14161c';
    ctx.fillRect(0, 0, 512, 320);
    ctx.strokeStyle = 'rgba(245,130,32,0.45)';
    ctx.lineWidth = 2;
    const nodes = [[256, 160], [140, 90], [380, 90], [120, 230], [390, 230], [256, 60], [256, 260]];
    nodes.forEach((a, i) => {
      nodes.forEach((b, j) => {
        if (j <= i) return;
        ctx.beginPath();
        ctx.moveTo(a[0], a[1]);
        ctx.lineTo(b[0], b[1]);
        ctx.stroke();
      });
    });
    ctx.fillStyle = '#f4f1ea';
    nodes.forEach((n, i) => {
      ctx.beginPath();
      ctx.arc(n[0], n[1], i === 0 ? 8 : 4, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.fillStyle = '#F58220';
    ctx.font = '700 48px Urbanist, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('AI', 256, 176);
    const tex = new THREE.CanvasTexture(c);
    tex.encoding = THREE.sRGBEncoding;
    return tex;
  }

  function pedestal() {
    const g = new THREE.Group();
    g.add(new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.7, 0.12, 32), matMetalDark));
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.48, 0.018, 8, 40), matOrange);
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.08;
    g.add(ring);
    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.08, 0.22, 0.7, 16, 1, true),
      new THREE.MeshBasicMaterial({ color: 0xf58220, transparent: true, opacity: 0.12, side: THREE.DoubleSide })
    );
    beam.position.y = 0.45;
    g.add(beam);
    return g;
  }

  const core = new THREE.Group();
  core.position.set(0, 0.85, 0);
  stage.add(core);
  const capPanel = glassPanel('Core AI Capabilities', 'Intelligence at the core. Built for the future.', 2.6, 1.42);
  capPanel.position.set(-2.85, 0.95, 0.25);
  core.add(capPanel);
  const ped = pedestal();
  ped.position.set(1.15, -0.55, 0);
  core.add(ped);
  const innerNode = new THREE.Mesh(new THREE.SphereGeometry(0.42, 28, 20), matWhite);
  innerNode.position.set(1.15, 0.55, 0);
  innerNode.scale.set(1, 0.82, 0.9);
  innerNode.userData.baseScale = innerNode.scale.clone();
  core.add(innerNode);
  const brainRing = new THREE.Mesh(new THREE.TorusGeometry(0.52, 0.01, 8, 40), matOrange);
  brainRing.position.copy(innerNode.position);
  brainRing.rotation.x = 0.9;
  core.add(brainRing);
  const brainRing2 = brainRing.clone();
  brainRing2.rotation.x = 1.4;
  brainRing2.rotation.z = 0.6;
  core.add(brainRing2);
  const brainGlow = new THREE.Mesh(
    new THREE.SphereGeometry(0.46, 20, 16),
    new THREE.MeshBasicMaterial({ color: 0xf58220, transparent: true, opacity: 0.12 })
  );
  brainGlow.position.copy(innerNode.position);
  brainGlow.scale.copy(innerNode.scale);
  core.add(brainGlow);
  const capTiles = [
    iconTile(draws.chip, -0.25, 1.65, 0.95),
    iconTile(draws.chat, 2.35, 1.7, 0.65),
    iconTile(draws.image, -0.35, -0.2, 1.05),
    iconTile(draws.db, 2.45, -0.15, 0.85)
  ];
  capTiles.forEach((t) => core.add(t));

  const visionGroup = new THREE.Group();
  visionGroup.position.set(-7.35, 0.5, 1.35);
  stage.add(visionGroup);
  const featPanel = glassPanel('Powerful AI Features', 'Smarter tools. Faster results.', 2.55, 1.42);
  featPanel.position.set(-2.25, 0.9, 0.2);
  visionGroup.add(featPanel);
  const robot = new THREE.Group();
  robot.position.set(1.55, -0.1, 0);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.28, 20, 16), matWhite);
  head.position.y = 0.95;
  robot.add(head);
  const eye = new THREE.Mesh(new THREE.TorusGeometry(0.1, 0.018, 8, 20, Math.PI), matOrange);
  eye.position.set(0, 0.95, 0.24);
  eye.rotation.z = Math.PI;
  robot.add(eye);
  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.28, 0.7, 16), matWhite);
  body.position.y = 0.38;
  robot.add(body);
  const armL = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.05, 0.42, 8), matWhite);
  armL.position.set(-0.26, 0.48, 0.1);
  armL.rotation.z = 0.55;
  armL.rotation.x = 0.35;
  robot.add(armL);
  const armR = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.05, 0.42, 8), matWhite);
  armR.position.set(0.28, 0.5, 0.16);
  armR.rotation.z = -0.7;
  armR.rotation.x = 0.45;
  robot.add(armR);
  const cube = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.28, 0.28), matTile);
  cube.position.set(0.42, 0.55, 0.22);
  robot.add(cube);
  const cubeFace = new THREE.Mesh(
    new THREE.PlaneGeometry(0.22, 0.22),
    new THREE.MeshBasicMaterial({ map: makeAiMark(), transparent: true })
  );
  cubeFace.position.z = 0.145;
  cube.add(cubeFace);
  const cubeRing = new THREE.Mesh(new THREE.TorusGeometry(0.26, 0.012, 8, 32), matOrange);
  cube.add(cubeRing);
  visionGroup.add(robot);
  const featureCards = [
    iconTile(draws.bolt, -0.55, 0.2, 0.85),
    iconTile(draws.brain, 0.65, -0.55, 1.05),
    iconTile(draws.chart, 1.85, -0.6, 0.9),
    iconTile(draws.gear, 2.75, 0.15, 0.7)
  ];
  featureCards.forEach((t) => visionGroup.add(t));

  const langGroup = new THREE.Group();
  langGroup.position.set(7.35, 0.4, -0.75);
  stage.add(langGroup);
  const solPanel = glassPanel('AI Solutions', 'Solve complex challenges with smart AI.', 2.55, 1.42);
  solPanel.position.set(2.35, 1.0, 0.15);
  langGroup.add(solPanel);
  const laptop = new THREE.Group();
  laptop.position.set(-1.25, -0.15, 0);
  laptop.rotation.y = 0.35;
  const base = new THREE.Mesh(new THREE.BoxGeometry(1.35, 0.06, 0.9), matMetalDark);
  laptop.add(base);
  const screen = new THREE.Mesh(new THREE.BoxGeometry(1.28, 0.82, 0.05), matMetalDark);
  screen.position.set(0, 0.44, -0.38);
  screen.rotation.x = -0.18;
  laptop.add(screen);
  const screenFace = new THREE.Mesh(
    new THREE.PlaneGeometry(1.16, 0.7),
    new THREE.MeshBasicMaterial({ map: makeScreenTex() })
  );
  screenFace.position.set(0, 0.44, -0.35);
  screenFace.rotation.x = -0.18;
  laptop.add(screenFace);
  const aiOrb = new THREE.Mesh(new THREE.IcosahedronGeometry(0.16, 0), matOrange);
  aiOrb.position.set(0, 0.48, -0.28);
  laptop.add(aiOrb);
  langGroup.add(laptop);
  const solutionMods = [
    iconTile(draws.chat, -2.35, 1.25, 0.65),
    iconTile(draws.chart, -2.65, -0.05, 0.9),
    iconTile(draws.image, 0.35, 1.55, 0.55),
    iconTile(draws.code, 0.75, 0.05, 0.8)
  ];
  solutionMods.forEach((t) => langGroup.add(t));

  const agentsGroup = new THREE.Group();
  agentsGroup.position.set(0, 0, 7.35);
  stage.add(agentsGroup);
  const fwPanel = glassPanel('Pre-built Frameworks', 'Build faster. Scale easier.', 2.55, 1.42);
  fwPanel.position.set(2.45, 1.0, 0.2);
  agentsGroup.add(fwPanel);
  const crate = new THREE.Mesh(new THREE.BoxGeometry(1.05, 0.85, 1.05), matMetalDark);
  crate.position.set(-1.25, 0.05, 0);
  agentsGroup.add(crate);
  const crateFace = new THREE.Mesh(
    new THREE.PlaneGeometry(0.72, 0.72),
    new THREE.MeshBasicMaterial({ map: makeAiMark(), transparent: true })
  );
  crateFace.position.set(-1.25, 0.05, 0.54);
  agentsGroup.add(crateFace);
  const crateRing = new THREE.Mesh(new THREE.TorusGeometry(0.72, 0.02, 8, 40), matOrange);
  crateRing.rotation.x = Math.PI / 2;
  crateRing.position.set(-1.25, -0.28, 0);
  agentsGroup.add(crateRing);
  const crateRing2 = crateRing.clone();
  crateRing2.position.y = 0.38;
  agentsGroup.add(crateRing2);
  const hexTiles = [
    iconTile(draws.db, -2.45, 1.25, 0.7),
    iconTile(draws.gear, 0.15, 1.65, 0.5),
    iconTile(draws.flow, -2.65, -0.1, 0.9),
    iconTile(draws.code, 0.45, 0.25, 0.85),
    iconTile(draws.cloud, -1.25, 1.95, 0.35)
  ];
  hexTiles.forEach((t) => agentsGroup.add(t));
  const packet = new THREE.Mesh(new THREE.SphereGeometry(0.04, 10, 10), matOrange);
  agentsGroup.add(packet);
  const hexPaths = hexTiles.map((t) => new THREE.LineCurve3(new THREE.Vector3(-1.25, 0.5, 0), t.userData.base.clone()));
  const glassPanels = [capPanel, featPanel, solPanel, fwPanel];

  const bgIconDraws = [draws.chip, draws.chat, draws.gear, draws.code, draws.cloud, draws.db, draws.bolt, draws.flow, draws.image, draws.brain];
  const bgIconSpots = [
    [-12.4, 3.6, -6.4], [12.6, 3.3, -5.5], [-11.2, 0.15, 8.2], [11.6, 4.5, 3.4],
    [-8.6, 5.0, 10.4], [9.4, 0.1, 10.8], [0.4, 5.6, -9.2], [-14.0, 1.9, 0.8],
    [14.0, 2.3, 1.8], [-6.2, 5.8, -3.0]
  ];
  const bgIcons = bgIconSpots.map((p, i) => {
    const tile = iconTile(bgIconDraws[i % bgIconDraws.length], p[0], p[1], p[2]);
    tile.scale.setScalar(0.72);
    tile.children.forEach((ch) => {
      if (ch.material) {
        ch.material = ch.material.clone();
        ch.material.transparent = true;
        ch.material.opacity = 0.32;
        ch.material.depthWrite = false;
      }
    });
    stage.add(tile);
    return tile;
  });
  const bgLinkPos = [];
  for (let i = 0; i < bgIconSpots.length - 1; i++) {
    if (i % 2) continue;
    const a = bgIconSpots[i];
    const b = bgIconSpots[i + 1];
    bgLinkPos.push(a[0], a[1], a[2], b[0], b[1], b[2]);
  }
  stage.add(new THREE.LineSegments(
    new THREE.BufferGeometry().setAttribute('position', new THREE.Float32BufferAttribute(bgLinkPos, 3)),
    new THREE.LineBasicMaterial({ color: 0xf58220, transparent: true, opacity: 0.12 })
  ));

  function buildPath(from, to, lift) {
    const mid = from.clone().add(to).multiplyScalar(0.5);
    mid.y += lift;
    const curve = new THREE.QuadraticBezierCurve3(from, mid, to);
    const tube = new THREE.Mesh(
      new THREE.TubeGeometry(curve, 36, 0.008, 6, false),
      new THREE.MeshBasicMaterial({ color: 0x3a3d46, transparent: true, opacity: 0.35 })
    );
    stage.add(tube);
    return { tube, curve };
  }
  const pathVision = buildPath(new THREE.Vector3(-7.35, 0.85, 1.35), new THREE.Vector3(0, 1.15, 0), 1.15);
  const pathLang = buildPath(new THREE.Vector3(7.35, 0.75, -0.75), new THREE.Vector3(0, 1.15, 0), 1.15);
  const pathAgents = buildPath(new THREE.Vector3(0, 1.15, 0), new THREE.Vector3(0, 0.2, 7.35), 0.85);

  function pulse() {
    const m = new THREE.Mesh(
      new THREE.SphereGeometry(0.034, 10, 10),
      new THREE.MeshBasicMaterial({ color: ORANGE, transparent: true, opacity: 0.15 })
    );
    stage.add(m);
    return m;
  }
  const pulseV = pulse();
  const pulseL = pulse();
  const pulseA = pulse();

  const keyframes = [
    { t: 0.00, pos: [0, 2.25, 16.2], look: [0, 0.95, 0.6] },
    { t: 0.16, pos: [-3.4, 1.5, 10.4], look: [-6.0, 0.7, 1.3] },
    { t: 0.30, pos: [-5.0, 1.25, 7.4], look: [-7.2, 0.65, 1.35] },
    { t: 0.46, pos: [0.15, 1.65, 8.2], look: [0, 1.05, 0] },
    { t: 0.64, pos: [4.8, 1.25, 7.2], look: [7.2, 0.55, -0.7] },
    { t: 0.80, pos: [0.25, 0.85, 12.2], look: [0, 0.25, 7.2] },
    { t: 1.00, pos: [0, 2.25, 16.2], look: [0, 0.95, 0.6] }
  ];

  function lerp(a, b, t) { return a + (b - a) * t; }
  function lerpVec(a, b, t) { return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)]; }
  function smoothstep(t) { return t * t * (3 - 2 * t); }

  function evalCamera(t) {
    let i = 0;
    for (i = 0; i < keyframes.length - 1; i++) {
      if (t >= keyframes[i].t && t <= keyframes[i + 1].t) break;
    }
    i = Math.min(i, keyframes.length - 2);
    const a = keyframes[i];
    const b = keyframes[i + 1];
    const local = smoothstep(Math.min(Math.max((t - a.t) / (b.t - a.t || 1), 0), 1));
    return { pos: lerpVec(a.pos, b.pos, local), look: lerpVec(a.look, b.look, local) };
  }

  let tourT = 0;
  let pauseUntil = 0;
  const TOUR_SPEED = 0.028;
  const STAGE_STOPS = [0, 0.24, 0.44, 0.62, 0.78];

  const mouse = { x: 0, y: 0 };
  let mouseSX = 0;
  let mouseSY = 0;
  section.addEventListener('mousemove', (e) => {
    const rect = section.getBoundingClientRect();
    mouse.x = ((e.clientX - rect.left) / rect.width - 0.5) * 2;
    mouse.y = ((e.clientY - Math.max(rect.top, 0)) / window.innerHeight - 0.5) * 2;
  });

  const railNodes = section.querySelectorAll('.rail-node');

  railNodes.forEach((node) => {
    node.addEventListener('click', () => {
      const i = Number(node.dataset.stage);
      if (Number.isNaN(i)) return;
      tourT = STAGE_STOPS[i];
      pauseUntil = clock.elapsedTime + 2.8;
    });
  });

  function stageIndex(t) {
    if (t < 0.12) return 0;
    if (t < 0.36) return 1;
    if (t < 0.54) return 2;
    if (t < 0.72) return 3;
    return 4;
  }

  function updateUI(t) {
    const active = stageIndex(t);
    railNodes.forEach((n) => n.classList.toggle('active', Number(n.dataset.stage) === active));
    section.classList.remove('is-touring');
    section.classList.remove('is-ending');
  }

  let visible = true;
  const io = new IntersectionObserver((entries) => {
    visible = entries[0] && entries[0].isIntersecting;
  }, { threshold: 0.02 });
  io.observe(section);

  window.addEventListener('resize', () => {
    camera.aspect = holder.clientWidth / holder.clientHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(holder.clientWidth, holder.clientHeight);
  });

  const clock = new THREE.Clock();
  const lookTarget = new THREE.Vector3(0, 1.05, 0);

  function drivePulse(mesh, path, on) {
    const cycle = (clock.elapsedTime * 0.32) % 1;
    mesh.position.copy(path.curve.getPointAt(cycle));
    mesh.material.opacity = on ? 0.9 : 0.12;
  }

  let running = true;
  window.addEventListener('ds-free-webgl', () => {
    if (visible) return;
    running = false;
    try {
      renderer.dispose();
      if (typeof renderer.forceContextLoss === 'function') renderer.forceContextLoss();
      if (renderer.domElement && renderer.domElement.parentNode) {
        renderer.domElement.parentNode.removeChild(renderer.domElement);
      }
    } catch (_) { /* ignore */ }
  });

  function animate() {
    if (!running) return;
    requestAnimationFrame(animate);
    const dt = Math.min(clock.getDelta(), 0.05);
    if (!visible) return;

    const elapsed = clock.elapsedTime;
    if (elapsed > pauseUntil) {
      tourT += dt * TOUR_SPEED;
      if (tourT >= 1) tourT -= 1;
    }

    const cp = evalCamera(tourT);
    mouseSX += (mouse.x - mouseSX) * 0.04;
    mouseSY += (mouse.y - mouseSY) * 0.04;
    camera.position.set(cp.pos[0] + mouseSX * 0.28, cp.pos[1] - mouseSY * 0.16, cp.pos[2]);
    lookTarget.set(cp.look[0] + mouseSX * 0.12, cp.look[1] - mouseSY * 0.08, cp.look[2]);
    camera.lookAt(lookTarget);

    const nearVision = tourT > 0.16 && tourT < 0.40 ? 1 - Math.abs(tourT - 0.28) / 0.12 : 0;
    const nearCore = tourT < 0.58 ? Math.max(0.25, 1 - Math.abs(tourT - 0.46) / 0.2) : 0.15;
    const nearLang = tourT > 0.52 && tourT < 0.76 ? 1 - Math.abs(tourT - 0.64) / 0.12 : 0;
    const nearAgents = tourT > 0.70 ? Math.min(1, (tourT - 0.70) / 0.12) : 0;

    core.rotation.y = Math.sin(elapsed * 0.12) * 0.04;
    const pulseAmt = 1 + Math.sin(elapsed * 1.4) * 0.04 + nearCore * 0.06;
    const bs = innerNode.userData.baseScale;
    innerNode.scale.set(bs.x * pulseAmt, bs.y * pulseAmt, bs.z * pulseAmt);
    brainGlow.scale.copy(innerNode.scale).multiplyScalar(1.08);
    brainGlow.material.opacity = 0.1 + Math.sin(elapsed * 1.4) * 0.04 + nearCore * 0.08;
    brainRing.rotation.z = elapsed * 0.35;
    brainRing2.rotation.y = elapsed * 0.28;
    coreLight.intensity = 2.2 + Math.sin(elapsed * 1.4) * 0.35 + nearCore * 0.6;

    function floatTiles(tiles, mix) {
      tiles.forEach((tile, i) => {
        const b = tile.userData.base;
        tile.position.y = b.y + Math.sin(elapsed * 1.15 + i) * 0.08 * (0.45 + mix);
        tile.rotation.y = Math.sin(elapsed * 0.45 + i) * 0.12;
      });
    }
    floatTiles(capTiles, Math.min(Math.max(nearCore, 0), 1));
    floatTiles(featureCards, Math.min(Math.max(nearVision, 0), 1));
    floatTiles(solutionMods, Math.min(Math.max(nearLang, 0), 1));
    floatTiles(hexTiles, Math.min(Math.max(nearAgents, 0), 1));
    bgIcons.forEach((tile, i) => {
      const b = tile.userData.base;
      tile.position.y = b.y + Math.sin(elapsed * 0.55 + i) * 0.18;
      tile.quaternion.copy(camera.quaternion);
    });
    traces.rotation.y = elapsed * 0.012;
    cage.rotation.y = elapsed * 0.008;

    cube.rotation.y = elapsed * 0.55;
    cube.rotation.x = elapsed * 0.22;
    cubeRing.rotation.x = elapsed * 0.8;
    cubeRing.rotation.y = elapsed * 0.45;
    aiOrb.rotation.y = elapsed * 0.7;
    crateRing.rotation.z = elapsed * 0.4;
    crateRing2.rotation.z = -elapsed * 0.32;

    glassPanels.forEach((p) => p.quaternion.copy(camera.quaternion));

    if (hexPaths.length) {
      const hop = (elapsed * 0.32) % hexPaths.length;
      packet.position.copy(hexPaths[Math.floor(hop)].getPointAt(hop % 1));
    }

    drivePulse(pulseV, pathVision, tourT > 0.12 && tourT < 0.42);
    drivePulse(pulseL, pathLang, tourT > 0.48 && tourT < 0.76);
    drivePulse(pulseA, pathAgents, tourT > 0.68);
    pathVision.tube.material.opacity = tourT > 0.12 && tourT < 0.42 ? 0.55 : 0.14;
    pathLang.tube.material.opacity = tourT > 0.48 && tourT < 0.76 ? 0.55 : 0.14;
    pathAgents.tube.material.opacity = tourT > 0.68 ? 0.55 : 0.14;

    const dp = dust.geometry.attributes.position;
    for (let i = 0; i < dp.count; i++) {
      dp.array[i * 3 + 1] += 0.0013;
      if (dp.array[i * 3 + 1] > 10) dp.array[i * 3 + 1] = -2.4;
    }
    dp.needsUpdate = true;

    updateUI(tourT);
    renderer.render(scene, camera);
  }

  section.classList.add('is-ready');
  animate();
})();


