/* Click-to-place query point: KNN and Naive Bayes */
function wireClickQuery(canvasId, xDomainFn, yDomainFn, onSet){
  const canvas = document.getElementById(canvasId);
  if(!canvas) return;
  canvas.addEventListener('click', (e)=>{
    const rect = canvas.getBoundingClientRect();
    const px = e.clientX - rect.left, py = e.clientY - rect.top;
    const xDomain = xDomainFn(), yDomain = yDomainFn();
    const dataX = xDomain[0] + (px-PAD.l)/(rect.width-PAD.l-PAD.r)*(xDomain[1]-xDomain[0]);
    const dataY = yDomain[1] - (py-PAD.t)/(rect.height-PAD.t-PAD.b)*(yDomain[1]-yDomain[0]);
    onSet(dataX, dataY);
  });
}
wireClickQuery('chart-knn', ()=>[-knn.view.RCur,knn.view.RCur], ()=>[-knn.view.RCur,knn.view.RCur], (x,y)=>{ knn.query = {x,y}; knnUpdatePrediction(); });
