let playgroundVisible = true;
if ('IntersectionObserver' in window) {
  const io = new IntersectionObserver((entries) => {
    playgroundVisible = entries.some((entry) => entry.isIntersecting);
    if (playgroundVisible) requestAnimationFrame(resizeActiveCanvases);
  }, { threshold: 0.08 });
  io.observe(root);
}

function loop(now){
  if (playgroundVisible) {
    linearStep();
    logisticStep();
    kmeansPlaybackTick(now);
    kmeansStep();
    knnStep();
    treeStep();
    gdPlaybackTick(now);
    svmStep();
    pcaStep();
    dbscanStep();
    forestStep();
    nnPlaybackTick(now);
    nbStep();

    if(activeTab==='linear') linearDraw();
    else if(activeTab==='logistic') logisticDraw();
    else if(activeTab==='kmeans') kmeansDraw();
    else if(activeTab==='knn') knnDraw();
    else if(activeTab==='tree') treeDraw();
    else if(activeTab==='gd') gdDraw();
    else if(activeTab==='svm') svmDraw();
    else if(activeTab==='pca') pcaDraw();
    else if(activeTab==='dbscan') dbscanDraw();
    else if(activeTab==='forest') forestDraw();
    else if(activeTab==='nn') nnDraw();
    else if(activeTab==='nb') nbDraw();
  }

  requestAnimationFrame(loop);
}

