/* ==========================================================================
   Geospatial Lab — demo data (homepage #geo-lab + playgrounds/geospatial-intelligence.html)
   ========================================================================== */
/* ============================================================================
   demoData.js
   ----------------------------------------------------------------------------
   Central demo dataset. Everything the UI reads comes from DEMO_DATA / the
   helper functions below. Nothing in mapCore.js, layers.js, analysis.js etc.
   hard-codes a metric or metadata value — they all call into this module.

   >>> REAL DATA INTEGRATION POINT <<<
   Replace the bodies of loadRaster(), loadVector(), loadTimeSeries() and the
   DEMO_DATA.* metadata blocks with real fetch() calls, e.g.:
     GET /api/geospatial/layers
     GET /api/geospatial/imagery
     GET /api/geospatial/ndvi
     GET /api/geospatial/timeseries
   The rest of the application does not need to change — it only depends on
   the shape of the objects returned here (see JSDoc typedefs below).
   ========================================================================== */

/** @typedef {{lat:number, lng:number}} LatLng */

const AOI_DEMO = {
  // Predefined "Explore Demo Area" polygon — a mixed forest / agriculture
  // region. Coordinates are illustrative, centered near Chittagong Hill
  // Tracts style forest-agriculture mosaic (used only as a realistic demo
  // AOI shape, not tied to real satellite acquisitions).
  type: "Feature",
  properties: { name: "Demo AOI — Forest Margin Sector 7" },
  geometry: {
    type: "Polygon",
    coordinates: [[
      [90.335, 23.705], [90.372, 23.708], [90.386, 23.690],
      [90.378, 23.665], [90.348, 23.658], [90.322, 23.672],
      [90.318, 23.692], [90.335, 23.705]
    ]]
  }
};

const MAP_DEFAULT = { center: [23.685, 90.356], zoom: 12 };

const YEARS = [2019, 2020, 2021, 2022, 2023, 2024, 2025];

/* ---------------------------------------------------------------------- */
/* DATASET METADATA — D02 / D04 / D08                                     */
/* In production this comes from GET /api/geospatial/layers               */
/* ---------------------------------------------------------------------- */
const DATASETS = {
  D02: {
    id: "D02", label: "D02 Dataset", resolution: "30m", bands: 4,
    crs: "EPSG:4326", acquisition: "2025-04-11",
    coverage: "112 km²", sensor: "Multispectral (demo)",
    description: "Coarse-resolution regional composite for wide-area screening."
  },
  D04: {
    id: "D04", label: "D04 Dataset", resolution: "10m", bands: 4,
    crs: "EPSG:4326", acquisition: "2025-05-03",
    coverage: "112 km²", sensor: "Multispectral (demo)",
    description: "Mid-resolution tile used for standard vegetation monitoring."
  },
  D08: {
    id: "D08", label: "D08 Dataset", resolution: "3m", bands: 4,
    crs: "EPSG:4326", acquisition: "2025-05-20",
    coverage: "112 km²", sensor: "High-res multispectral (demo)",
    description: "High-resolution tile used for AOI-level change detection."
  }
};

/* ---------------------------------------------------------------------- */
/* LAYER REGISTRY — drives the Data Layer Panel                           */
/* ---------------------------------------------------------------------- */
const LAYER_REGISTRY = [
  { id: "basemap", name: "Base Map", group: "base", color: "#56667e",
    desc: "Dark cartographic reference basemap.", resolution: "—", defaultOn: true, opacity: 1 },
  { id: "d02", name: "D02 Dataset", group: "dataset", color: "#F58220",
    desc: "Wide-area regional composite.", resolution: "30m", defaultOn: false, opacity: 0.85 },
  { id: "d04", name: "D04 Dataset", group: "dataset", color: "#F58220",
    desc: "Standard-resolution monitoring tile.", resolution: "10m", defaultOn: false, opacity: 0.85 },
  { id: "d08", name: "D08 Dataset", group: "dataset", color: "#F58220",
    desc: "High-resolution AOI change-detection tile.", resolution: "3m", defaultOn: false, opacity: 0.85 },
  { id: "rgb", name: "RGB Imagery", group: "imagery", color: "#faf7f2",
    desc: "True color composite.", resolution: "3m", defaultOn: true, opacity: 1 },
  { id: "ndvi", name: "NDVI", group: "analytic", color: "#cfa86e",
    desc: "Normalized Difference Vegetation Index.", resolution: "3m", defaultOn: false, opacity: 0.8 },
  { id: "deforestation", name: "Deforestation", group: "analytic", color: "#e0554f",
    desc: "Forest-loss / forest-gain change layer.", resolution: "3m", defaultOn: false, opacity: 0.8 },
  { id: "elevation", name: "Elevation", group: "analytic", color: "#37c98a",
    desc: "Relative terrain elevation shading.", resolution: "10m", defaultOn: false, opacity: 0.6 }
];

/* ---------------------------------------------------------------------- */
/* Deterministic pseudo-random helpers                                    */
/* Keeps demo stats stable for a given geometry instead of re-randomizing */
/* on every render, which would feel broken to a user.                    */
/* ---------------------------------------------------------------------- */
function seedFromString(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0);
}
function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function seededRandom(key) {
  return mulberry32(seedFromString(String(key)));
}

/* ---------------------------------------------------------------------- */
/* NDVI temporal curve per geometry — declining trend for the demo story  */
/* (a realistic "vegetation decline / possible deforestation" narrative)  */
/* ---------------------------------------------------------------------- */
function getNDVITimeSeries(geomKey) {
  const rnd = seededRandom(geomKey + "|ndvi");
  const base = 0.78 - rnd() * 0.08;      // starting NDVI ~0.70-0.78
  const declinePerYear = 0.028 + rnd() * 0.02;
  return YEARS.map((year, i) => {
    const noise = (rnd() - 0.5) * 0.02;
    const value = Math.max(0.15, base - declinePerYear * i + noise);
    return { year, ndvi: Number(value.toFixed(3)) };
  });
}

function getForestSeries(geomKey) {
  const rnd = seededRandom(geomKey + "|forest");
  const base = 58 + rnd() * 10; // % forest cover in 2019
  const lossPerYear = 2.1 + rnd() * 1.4;
  return YEARS.map((year, i) => ({
    year,
    forestPct: Number(Math.max(20, base - lossPerYear * i).toFixed(1))
  }));
}

/* ---------------------------------------------------------------------- */
/* Public dataset object                                                  */
/* ---------------------------------------------------------------------- */
const DEMO_DATA = {
  datasets: DATASETS,
  layers: LAYER_REGISTRY,
  years: YEARS,
  defaultAOI: AOI_DEMO,
  mapDefault: MAP_DEFAULT,

  ndviLegend: [
    { v: "1.0", color: "#0d7d3a" }, { v: "0.8", color: "#3fa93f" },
    { v: "0.6", color: "#8fbf3a" }, { v: "0.4", color: "#d6c93d" },
    { v: "0.2", color: "#d99a3d" }, { v: "0.0", color: "#c96b4a" },
    { v: "-1.0", color: "#8a4a4a" }
  ],
  changeLegend: [
    { label: "Stable", color: "#3a4a5c" },
    { label: "Vegetation Gain", color: "#37c98a" },
    { label: "Vegetation Loss", color: "#d9c14a" },
    { label: "Major Change", color: "#e0554f" }
  ],
  deforestationLegend: [
    { label: "Forest", color: "#1f7a4d" },
    { label: "Forest Loss", color: "#e0554f" },
    { label: "Forest Gain", color: "#37c98a" },
    { label: "Change Zone", color: "#d9c14a" }
  ],

  getNDVITimeSeries,
  getForestSeries,
  seededRandom
};

// Expose globally — this file is loaded as a plain <script>, not a module,
// so app.js and friends can reach DEMO_DATA directly.
window.DEMO_DATA = DEMO_DATA;

/* ==========================================================================
   Geospatial Lab — procedural raster
   ========================================================================== */
/* ============================================================================
   proceduralRaster.js
   ----------------------------------------------------------------------------
   Generates realistic-looking satellite-style raster imagery (RGB, NDVI,
   deforestation, elevation) entirely on the client using canvas + value
   noise. This exists ONLY because the demo ships without real GeoTIFF
   assets. It is NOT satellite data.

   >>> REAL DATA INTEGRATION POINT <<<
   When real files exist under /data/rgb, /data/ndvi, /data/deforestation
   (see loadRaster() in geoLoader.js), this generator is bypassed entirely
   and georaster / georaster-layer-for-leaflet renders the actual GeoTIFF
   pixels instead. Search this file for "REPLACE WITH REAL RASTER" to see
   exactly where that swap happens.
   ========================================================================== */

const ProceduralRaster = (function () {

  const SIZE = 512; // canvas px per tile

  /* ---- deterministic value-noise (no external noise library needed) ---- */
  function makeNoise2D(seed) {
    const rnd = DEMO_DATA.seededRandom(seed);
    const gridSize = 64;
    const grid = new Float32Array(gridSize * gridSize);
    for (let i = 0; i < grid.length; i++) grid[i] = rnd();

    function sample(gx, gy) {
      const x = ((gx % gridSize) + gridSize) % gridSize;
      const y = ((gy % gridSize) + gridSize) % gridSize;
      return grid[y * gridSize + x];
    }
    function smooth(t) { return t * t * (3 - 2 * t); }

    return function noise(x, y) {
      // x,y in [0,1) mapped onto the grid
      const fx = x * gridSize, fy = y * gridSize;
      const x0 = Math.floor(fx), y0 = Math.floor(fy);
      const tx = smooth(fx - x0), ty = smooth(fy - y0);
      const a = sample(x0, y0), b = sample(x0 + 1, y0);
      const c = sample(x0, y0 + 1), d = sample(x0 + 1, y0 + 1);
      const top = a + (b - a) * tx;
      const bot = c + (d - c) * tx;
      return top + (bot - top) * ty;
    };
  }

  function fbm(noiseFns, x, y) {
    // fractal sum across several octave noise functions -> natural terrain look
    let sum = 0, amp = 0.55, freq = 1;
    for (let i = 0; i < noiseFns.length; i++) {
      sum += noiseFns[i]((x * freq) % 1, (y * freq) % 1) * amp;
      amp *= 0.5; freq *= 2.3;
    }
    return sum;
  }

  /* ---- terrain field: combines forest mask, water body, roads, fields --- */
  function buildTerrainField(seed) {
    const n1 = makeNoise2D(seed + "-a");
    const n2 = makeNoise2D(seed + "-b");
    const n3 = makeNoise2D(seed + "-c");
    const rnd = DEMO_DATA.seededRandom(seed + "-river");
    // a wandering "river" as a sine-perturbed diagonal band
    const riverPhase = rnd() * Math.PI * 2;
    const riverAmp = 0.06 + rnd() * 0.04;

    return function fieldAt(x, y) {
      // x,y normalized [0,1]
      const terrain = fbm([n1, n2, n3], x, y); // 0..1 base terrain roughness
      const river = Math.sin((x * 5) + riverPhase) * riverAmp + 0.5;
      const distToRiver = Math.abs(y - river);
      const isWater = distToRiver < 0.018;
      const isRiverBank = distToRiver < 0.05;
      // roads: a couple of near-straight thin bands
      const roadA = Math.abs((x + y * 0.15) % 0.5 - 0.25);
      const isRoad = roadA < 0.0035 && !isWater;
      return { terrain, isWater, isRiverBank, isRoad };
    };
  }

  /* ---- deforestation zone: a soft blob that "grows" between 2021-2025 --- */
  function deforestationMask(seed, year) {
    const rnd = DEMO_DATA.seededRandom(seed + "-defo");
    const cx = 0.35 + rnd() * 0.3, cy = 0.35 + rnd() * 0.3;
    const growth = Math.max(0, (year - 2020) / 5); // 0 in 2020 -> ~1 by 2025
    const radius = 0.05 + growth * 0.22;
    return function (x, y) {
      const dx = x - cx, dy = y - cy;
      const d = Math.sqrt(dx * dx + dy * dy * 1.4);
      const edge = radius - d;
      return { inside: edge > 0, intensity: Math.max(0, Math.min(1, edge / 0.05)) };
    };
  }

  function lerpColor(c1, c2, t) {
    return [
      Math.round(c1[0] + (c2[0] - c1[0]) * t),
      Math.round(c1[1] + (c2[1] - c1[1]) * t),
      Math.round(c1[2] + (c2[2] - c1[2]) * t)
    ];
  }

  /* ------------------------------------------------------------ RGB tile */
  function renderRGB(seed, year) {
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = SIZE;
    const ctx = canvas.getContext("2d");
    const img = ctx.createImageData(SIZE, SIZE);
    const field = buildTerrainField(seed);
    const defo = deforestationMask(seed, year);

    const FOREST = [26, 61, 34], FOREST_LIGHT = [40, 92, 48];
    const FIELD = [111, 108, 55], FIELD_LIGHT = [140, 133, 74];
    const WATER = [24, 46, 74], BANK = [58, 70, 56];
    const CLEARED = [107, 92, 66], ROAD = [58, 55, 50];

    for (let py = 0; py < SIZE; py++) {
      for (let px = 0; px < SIZE; px++) {
        const x = px / SIZE, y = py / SIZE;
        const f = field(x, y);
        const d = defo(x, y);
        let color;
        if (f.isWater) color = WATER;
        else if (f.isRoad) color = ROAD;
        else if (f.isRiverBank) color = lerpColor(BANK, FIELD, f.terrain);
        else if (f.terrain > 0.52) color = lerpColor(FOREST, FOREST_LIGHT, (f.terrain - 0.52) * 2);
        else color = lerpColor(FIELD, FIELD_LIGHT, f.terrain * 1.6);

        if (d.inside && f.terrain > 0.4 && !f.isWater) {
          color = lerpColor(color, CLEARED, d.intensity * 0.92);
        }
        const idx = (py * SIZE + px) * 4;
        const speck = (Math.random() * 10 - 5);
        img.data[idx] = clamp8(color[0] + speck);
        img.data[idx + 1] = clamp8(color[1] + speck);
        img.data[idx + 2] = clamp8(color[2] + speck);
        img.data[idx + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    return canvas;
  }

  /* ----------------------------------------------------------- NDVI tile */
  function ndviColor(v) {
    // v in [-1,1] -> map along DEMO_DATA.ndviLegend stops
    const stops = [
      { v: -1.0, c: [138, 74, 74] }, { v: 0.0, c: [201, 107, 74] },
      { v: 0.2, c: [217, 154, 61] }, { v: 0.4, c: [214, 201, 61] },
      { v: 0.6, c: [143, 191, 58] }, { v: 0.8, c: [63, 169, 63] },
      { v: 1.0, c: [13, 125, 58] }
    ];
    for (let i = 0; i < stops.length - 1; i++) {
      if (v >= stops[i].v && v <= stops[i + 1].v) {
        const t = (v - stops[i].v) / (stops[i + 1].v - stops[i].v);
        return lerpColor(stops[i].c, stops[i + 1].c, t);
      }
    }
    return v < -1 ? stops[0].c : stops[stops.length - 1].c;
  }

  function renderNDVI(seed, year) {
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = SIZE;
    const ctx = canvas.getContext("2d");
    const img = ctx.createImageData(SIZE, SIZE);
    const field = buildTerrainField(seed);
    const defo = deforestationMask(seed, year);
    const declineFactor = Math.max(0, (year - 2021)) * 0.09; // global slight decline story

    for (let py = 0; py < SIZE; py++) {
      for (let px = 0; px < SIZE; px++) {
        const x = px / SIZE, y = py / SIZE;
        const f = field(x, y);
        const d = defo(x, y);
        let ndvi;
        if (f.isWater) ndvi = -0.35 + (Math.random() * 0.05);
        else if (f.isRoad) ndvi = -0.05 + Math.random() * 0.05;
        else ndvi = -0.1 + f.terrain * 1.05; // terrain roughness -> vegetation vigor

        ndvi -= declineFactor * (f.terrain > 0.4 ? 0.35 : 0.08);
        if (d.inside && !f.isWater) ndvi -= d.intensity * 0.85;
        ndvi = Math.max(-1, Math.min(1, ndvi));

        const color = ndviColor(ndvi);
        const idx = (py * SIZE + px) * 4;
        img.data[idx] = color[0]; img.data[idx + 1] = color[1]; img.data[idx + 2] = color[2];
        img.data[idx + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    return canvas;
  }

  /* ---------------------------------------------------- Deforestation tile */
  function renderChange(seed, year) {
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = SIZE;
    const ctx = canvas.getContext("2d");
    const img = ctx.createImageData(SIZE, SIZE);
    const field = buildTerrainField(seed);
    const defo = deforestationMask(seed, year);
    const STABLE = [30, 42, 56], LOSS = [224, 85, 79];
    const GAIN = [55, 201, 138], MAJOR = [235, 60, 50];

    for (let py = 0; py < SIZE; py++) {
      for (let px = 0; px < SIZE; px++) {
        const x = px / SIZE, y = py / SIZE;
        const f = field(x, y);
        const d = defo(x, y);
        let color = STABLE;
        if (f.isWater) color = [18, 34, 54];
        else if (d.inside && f.terrain > 0.4) {
          color = d.intensity > 0.7 ? MAJOR : LOSS;
        } else if (f.terrain > 0.62 && Math.random() < 0.02) {
          color = GAIN; // scattered small regrowth specks
        }
        const idx = (py * SIZE + px) * 4;
        img.data[idx] = color[0]; img.data[idx + 1] = color[1]; img.data[idx + 2] = color[2];
        img.data[idx + 3] = f.isWater ? 255 : 220;
      }
    }
    ctx.putImageData(img, 0, 0);
    return canvas;
  }

  /* ------------------------------------------------------- Elevation tile */
  function renderElevation(seed) {
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = SIZE;
    const ctx = canvas.getContext("2d");
    const img = ctx.createImageData(SIZE, SIZE);
    const n1 = makeNoise2D(seed + "-ea");
    const n2 = makeNoise2D(seed + "-eb");
    for (let py = 0; py < SIZE; py++) {
      for (let px = 0; px < SIZE; px++) {
        const x = px / SIZE, y = py / SIZE;
        const h = fbm([n1, n2], x, y);
        const g = Math.round(40 + h * 170);
        const idx = (py * SIZE + px) * 4;
        img.data[idx] = clamp8(g * 0.55);
        img.data[idx + 1] = clamp8(g * 0.75 + 20);
        img.data[idx + 2] = clamp8(g * 0.6);
        img.data[idx + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
    return canvas;
  }

  function clamp8(v) { return Math.max(0, Math.min(255, Math.round(v))); }

  /**
   * Sample a single "pixel" of demo data at a lat/lng for the inspector /
   * point-analysis tool, without rendering a whole canvas.
   * >>> REAL DATA INTEGRATION POINT: replace with a raster pixel lookup
   * against the actual loaded GeoTIFF (georaster.getValues / bilinear read).
   */
  function samplePoint(seed, lat, lng, year, bounds) {
    const x = (lng - bounds.west) / (bounds.east - bounds.west);
    const y = 1 - (lat - bounds.south) / (bounds.north - bounds.south);
    const field = buildTerrainField(seed);
    const defo = deforestationMask(seed, year);
    const f = field(clampUnit(x), clampUnit(y));
    const d = defo(clampUnit(x), clampUnit(y));
    let ndvi = f.isWater ? -0.3 : -0.1 + f.terrain * 1.05;
    if (d.inside && !f.isWater) ndvi -= d.intensity * 0.85;
    ndvi = Math.max(-1, Math.min(1, ndvi));
    const rgbColor = f.isWater ? [24, 46, 74] : lerpColor([111, 108, 55], [26, 61, 34], f.terrain);
    const elevation = Math.round(20 + f.terrain * 260);
    return {
      ndvi: Number(ndvi.toFixed(2)),
      rgb: { r: rgbColor[0], g: rgbColor[1], b: rgbColor[2] },
      elevation,
      isWater: f.isWater,
      changeZone: d.inside
    };
  }
  function clampUnit(v) { return Math.max(0, Math.min(0.999, v)); }

  return { renderRGB, renderNDVI, renderChange, renderElevation, samplePoint, SIZE };
})();

window.ProceduralRaster = ProceduralRaster;

/* ==========================================================================
   Geospatial Lab — geo loader
   ========================================================================== */
/* ============================================================================
   geoLoader.js
   ----------------------------------------------------------------------------
   DEMO DATA NOW -> REAL LOCAL GEO DATA LATER -> REAL BACKEND/API EVENTUALLY

   This module is the single seam between "where imagery comes from" and
   "how it gets drawn on the map". Every raster/vector layer in the app is
   requested through loadRaster()/loadVector(); nothing else in the codebase
   decides whether a layer is real or procedural.

   Resolution order for a layer request:
     1. Try to fetch the real file from /data/<layer>/... (see DATA_PATHS).
     2. If present, parse it with georaster (raster) or fetch+JSON (vector)
        and hand back a real Leaflet layer bound to real geographic bounds.
     3. If missing/unreachable (expected in the demo), fall back to the
        procedural canvas generator in proceduralRaster.js, clearly logged
        to the console as DEMO/SYNTHETIC so it's never confused with #2.

   >>> REAL DATA INTEGRATION POINT <<<
   To go live with real imagery, just drop matching files into /data/... —
   no code changes required. To go fully server-backed later, replace the
   fetch(DATA_PATHS...) calls below with calls to:
     GET /api/geospatial/imagery?layer=rgb&year=2025
     GET /api/geospatial/ndvi?year=2025
   returning either a GeoTIFF blob or a tile URL template.
   ========================================================================== */

const GeoLoader = (function () {

  const DATA_PATHS = {
    d02: () => `data/d02/d02_sample.tif`,
    d04: () => `data/d04/d04_sample.tif`,
    d08: () => `data/d08/d08_sample.tif`,
    rgb: (year) => `data/rgb/rgb_${year}.tif`,
    ndvi: (year) => `data/ndvi/ndvi_${year}.tif`,
    deforestation: () => `data/deforestation/change_2021_2025.tif`,
    vectorForest: () => `data/vector/forest.geojson`,
    vectorRegions: () => `data/vector/regions.geojson`
  };

  // The bounding box the procedural raster canvases are stretched over.
  // In production this comes from the GeoTIFF's own georeferencing instead.
  const DEMO_BOUNDS = { west: 90.30, south: 23.64, east: 90.41, north: 23.72 };

  async function fileExists(url) {
    try {
      const res = await fetch(url, { method: "GET", cache: "no-store" });
      return res.ok ? res : null;
    } catch (e) {
      return null;
    }
  }

  /**
   * loadRaster(kind, opts) -> { source: 'real'|'demo', bounds, canvas? , georaster? }
   * kind: 'd02'|'d04'|'d08'|'rgb'|'ndvi'|'deforestation'|'elevation'
   */
  async function loadRaster(kind, opts = {}) {
    const year = opts.year || 2025;
    const seed = opts.seed || "demo-aoi";

    // elevation has no real-file slot in this spec's /data layout — always demo
    if (kind === "elevation") {
      return { source: "demo", bounds: DEMO_BOUNDS, canvas: ProceduralRaster.renderElevation(seed) };
    }

    const pathFn = DATA_PATHS[kind];
    if (pathFn && window.GeoTIFF && window.parseGeoraster) {
      const url = pathFn(year);
      const res = await fileExists(url);
      if (res) {
        try {
          const arrayBuffer = await res.arrayBuffer();
          const georaster = await window.parseGeoraster(arrayBuffer);
          console.info(`[GeoLoader] Loaded REAL raster for "${kind}" from ${url}`);
          return { source: "real", georaster, bounds: null };
        } catch (err) {
          console.warn(`[GeoLoader] Found ${url} but could not parse it as GeoTIFF. Falling back to demo raster.`, err);
        }
      }
    }

    // --- REPLACE WITH REAL RASTER: georaster-layer-for-leaflet consumes
    // the `georaster` object above directly; nothing below runs once a
    // real file is found and parsed successfully.
    if (typeof console.debug === 'function') {
      console.debug(`[GeoLoader] Using SYNTHETIC/DEMO raster for "${kind}" (${year}) — no file at data/${kind}/`);
    }
    let canvas;
    switch (kind) {
      case "d02": case "d04": case "d08":
        canvas = ProceduralRaster.renderRGB(seed + kind, year);
        break;
      case "rgb": canvas = ProceduralRaster.renderRGB(seed, year); break;
      case "ndvi": canvas = ProceduralRaster.renderNDVI(seed, year); break;
      case "deforestation": canvas = ProceduralRaster.renderChange(seed, year); break;
      default: canvas = ProceduralRaster.renderRGB(seed, year);
    }
    return { source: "demo", bounds: DEMO_BOUNDS, canvas };
  }

  /**
   * loadVector(kind) -> GeoJSON object (real file if present, else demo AOI)
   */
  async function loadVector(kind) {
    const pathFn = kind === "forest" ? DATA_PATHS.vectorForest : DATA_PATHS.vectorRegions;
    const url = pathFn();
    const res = await fileExists(url);
    if (res) {
      try {
        const geojson = await res.json();
        console.info(`[GeoLoader] Loaded REAL vector "${kind}" from ${url}`);
        return geojson;
      } catch (err) {
        console.warn(`[GeoLoader] Found ${url} but it isn't valid GeoJSON. Falling back to demo vector.`, err);
      }
    }
    console.info(`[GeoLoader] Using SYNTHETIC/DEMO vector for "${kind}" — no file at data/vector/`);
    return DEMO_DATA.defaultAOI;
  }

  /**
   * addRasterLayer(map, kind, opts) -> Leaflet layer, already added to map
   * Handles both the georaster path and the plain ImageOverlay/canvas path.
   */
  async function addRasterLayer(map, kind, opts = {}) {
    const result = await loadRaster(kind, opts);
    let layer;
    if (result.source === "real" && window.GeoRasterLayer) {
      // REAL GEOTIFF PATH — georaster-layer-for-leaflet renders it tile-by-tile
      layer = new GeoRasterLayer({
        georaster: result.georaster,
        opacity: opts.opacity ?? 0.85,
        resolution: 256
      });
    } else {
      const bounds = [[result.bounds.south, result.bounds.west], [result.bounds.north, result.bounds.east]];
      layer = L.imageOverlay(result.canvas.toDataURL(), bounds, {
        opacity: opts.opacity ?? 0.85,
        interactive: false
      });
    }
    layer.addTo(map);
    layer._geoKind = kind;
    return layer;
  }

  function addVectorLayer(map, geojson, styleOpts = {}) {
    const layer = L.geoJSON(geojson, {
      style: () => ({
        color: styleOpts.color || "#F58220",
        weight: styleOpts.weight ?? 2,
        fillColor: styleOpts.fillColor || styleOpts.color || "#F58220",
        fillOpacity: styleOpts.fillOpacity ?? 0.08,
        dashArray: styleOpts.dashArray || null
      }),
      pointToLayer: (feature, latlng) => L.circleMarker(latlng, {
        radius: 6, color: styleOpts.color || "#F58220", weight: 2, fillOpacity: 0.6
      })
    });
    layer.addTo(map);
    return layer;
  }

  return { loadRaster, loadVector, addRasterLayer, addVectorLayer, DEMO_BOUNDS };
})();

window.GeoLoader = GeoLoader;

/* ==========================================================================
   Geospatial Lab — analysis
   ========================================================================== */
/* ============================================================================
   analysis.js
   ----------------------------------------------------------------------------
   All spatial math lives here: area, perimeter, centroid (via Turf.js when
   available, with a manual fallback if the CDN didn't load), NDVI/forest
   statistics for a drawn AOI, and the simulated AI narrative.

   >>> REAL DATA INTEGRATION POINT <<<
   calculateNDVIStats() / calculateChange() currently derive numbers from
   DEMO_DATA's seeded time series. Replace their bodies with a real call to:
     POST /api/geospatial/aoi        (zonal statistics over real rasters)
   analyzeAOI() should call:
     POST /api/geospatial/analyze
   keeping the same return shape so the UI does not need to change.
   ========================================================================== */

const Analysis = (function () {

  function hasTurf() { return typeof turf !== "undefined"; }

  function geometryKey(geojsonGeom) {
    // Stable string key so the same drawn shape always yields the same
    // demo stats (rounded coords keeps near-duplicate draws consistent).
    return JSON.stringify(geojsonGeom.coordinates.map(ring =>
      (Array.isArray(ring[0]) ? ring : [ring]).map(pt =>
        Array.isArray(pt[0]) ? pt.map(p => p.map(n => Math.round(n * 500) / 500))
                              : pt.map(n => Math.round(n * 500) / 500))
    ));
  }

  /** calculateArea(feature) -> { km2, ha } */
  function calculateArea(feature) {
    let m2;
    if (hasTurf()) {
      m2 = turf.area(feature);
    } else {
      m2 = shoelaceAreaM2(feature.geometry);
    }
    return { km2: m2 / 1e6, ha: m2 / 1e4 };
  }

  /** Fallback planar-ish area estimate (equirectangular approx) if Turf missing */
  function shoelaceAreaM2(geom) {
    const R = 6371000;
    function ringArea(ring) {
      let sum = 0;
      for (let i = 0; i < ring.length - 1; i++) {
        const [lng1, lat1] = ring[i], [lng2, lat2] = ring[i + 1];
        const x1 = (lng1 * Math.PI / 180) * R * Math.cos(lat1 * Math.PI / 180);
        const y1 = (lat1 * Math.PI / 180) * R;
        const x2 = (lng2 * Math.PI / 180) * R * Math.cos(lat2 * Math.PI / 180);
        const y2 = (lat2 * Math.PI / 180) * R;
        sum += x1 * y2 - x2 * y1;
      }
      return Math.abs(sum / 2);
    }
    if (geom.type === "Polygon") return ringArea(geom.coordinates[0]);
    if (geom.type === "MultiPolygon") return geom.coordinates.reduce((a, poly) => a + ringArea(poly[0]), 0);
    return 0;
  }

  /** calculatePerimeter(feature) -> meters */
  function calculatePerimeter(feature) {
    if (hasTurf()) {
      try { return turf.length(turf.polygonToLine(feature), { units: "kilometers" }); } catch (e) { /* fallthrough */ }
    }
    const ring = feature.geometry.type === "Polygon" ? feature.geometry.coordinates[0] : feature.geometry.coordinates[0][0];
    let d = 0;
    for (let i = 0; i < ring.length - 1; i++) d += haversine(ring[i], ring[i + 1]);
    return d / 1000;
  }
  function haversine([lng1, lat1], [lng2, lat2]) {
    const R = 6371000, toRad = Math.PI / 180;
    const dLat = (lat2 - lat1) * toRad, dLng = (lng2 - lng1) * toRad;
    const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * toRad) * Math.cos(lat2 * toRad) * Math.sin(dLng / 2) ** 2;
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  }

  /** calculateCentroid(feature) -> [lat, lng] */
  function calculateCentroid(feature) {
    if (hasTurf()) {
      const c = turf.centroid(feature).geometry.coordinates;
      return [c[1], c[0]];
    }
    const ring = feature.geometry.type === "Polygon" ? feature.geometry.coordinates[0] : feature.geometry.coordinates[0][0];
    let lat = 0, lng = 0;
    ring.forEach(([lo, la]) => { lat += la; lng += lo; });
    return [lat / ring.length, lng / ring.length];
  }

  /**
   * calculateNDVIStats(feature, year)
   * Returns mean/min/max NDVI, vegetation %, for the given AOI + year using
   * the deterministic demo time series so numbers stay internally consistent
   * as the user scrubs the timeline.
   */
  function calculateNDVIStats(feature, year) {
    const key = geometryKey(feature.geometry);
    const series = DEMO_DATA.getNDVITimeSeries(key);
    const entry = series.find(s => s.year === year) || series[series.length - 1];
    const rnd = DEMO_DATA.seededRandom(key + "|spread|" + year);
    const spread = 0.18 + rnd() * 0.08;
    return {
      mean: entry.ndvi,
      min: Number(Math.max(-1, entry.ndvi - spread).toFixed(2)),
      max: Number(Math.min(1, entry.ndvi + spread * 0.6).toFixed(2)),
      vegetationPct: Number(Math.min(97, Math.max(4, (entry.ndvi + 0.15) * 100 * 0.92)).toFixed(0)),
      series
    };
  }

  /** calculateChange(feature) -> forest cover series + overall % change 2021->2025 */
  function calculateChange(feature) {
    const key = geometryKey(feature.geometry);
    const series = DEMO_DATA.getForestSeries(key);
    const first = series.find(s => s.year === 2021) || series[0];
    const last = series.find(s => s.year === 2025) || series[series.length - 1];
    const changePct = Number((((last.forestPct - first.forestPct) / first.forestPct) * 100).toFixed(1));
    return { series, forestPctNow: last.forestPct, changePct };
  }

  /** calculateAOI(feature, year) -> the full stat bundle used by the AOI panel */
  function calculateAOI(feature, year) {
    const area = calculateArea(feature);
    const perimeterKm = calculatePerimeter(feature);
    const centroid = calculateCentroid(feature);
    const ndvi = calculateNDVIStats(feature, year);
    const change = calculateChange(feature);
    const forestLossHa = Number((area.ha * (Math.max(0, -change.changePct) / 100)).toFixed(1));
    return {
      area, perimeterKm, centroid, ndvi, change, forestLossHa,
      forestRemainingKm2: Number((area.km2 * change.forestPctNow / 100).toFixed(1))
    };
  }

  /**
   * analyzeAOI(feature, stats) -> simulated AI narrative + findings.
   * SIMULATED OUTPUT — see disclaimer rendered alongside it in the UI.
   * >>> REAL DATA INTEGRATION POINT: POST /api/geospatial/analyze
   */
  function analyzeAOI(feature, stats) {
    const changePct = stats.change.changePct;
    const direction = changePct < 0 ? "decline" : "increase";
    const severity = Math.abs(changePct) > 20 ? "significant" : Math.abs(changePct) > 8 ? "moderate" : "minor";
    const key = geometryKey(feature.geometry);
    const rnd = DEMO_DATA.seededRandom(key + "|narrative");
    const sectors = ["eastern", "western", "northern", "southern", "central"];
    const hot = sectors[Math.floor(rnd() * sectors.length)];
    const calm = sectors.filter(s => s !== hot)[Math.floor(rnd() * (sectors.length - 1))];

    const narrative =
      `The selected region shows a ${Math.abs(changePct)}% ${direction} in vegetation activity between 2021 and 2025. ` +
      `The ${hot} section shows the highest concentration of change, while the ${calm} region remains relatively stable. ` +
      `Overall change magnitude is assessed as ${severity} based on NDVI and forest-cover trends within the AOI.`;

    const findings = [];
    if (changePct < -5) findings.push("Vegetation decline");
    if (stats.ndvi.mean < 0.5) findings.push("NDVI reduction");
    if (Math.abs(changePct) > 10) findings.push("Surface change");
    if (changePct < -12) findings.push("Potential deforestation zone");
    if (findings.length === 0) findings.push("No significant change detected");

    return { narrative, findings, generatedAt: new Date().toISOString(), simulated: true };
  }

  /** Point-level analysis for the drawing toolbar's POINT mode */
  function analyzePoint(lat, lng, year) {
    const sample = ProceduralRaster.samplePoint("demo-aoi", lat, lng, year, GeoLoader.DEMO_BOUNDS);
    return {
      lat: Number(lat.toFixed(4)), lng: Number(lng.toFixed(4)),
      ndvi: sample.ndvi, elevation: sample.elevation,
      vegetationPct: Math.max(2, Math.min(96, Math.round((sample.ndvi + 0.2) * 80))),
      rgb: sample.rgb, changeZone: sample.changeZone
    };
  }

  return {
    calculateArea, calculatePerimeter, calculateCentroid,
    calculateNDVIStats, calculateChange, calculateAOI,
    analyzeAOI, analyzePoint, geometryKey
  };
})();

window.Analysis = Analysis;

/* ==========================================================================
   Geospatial Lab — chart helpers
   ========================================================================== */
/* ============================================================================
   chart.js — tiny dependency-free canvas line chart for the NDVI time series.
   Deliberately not pulling in a full charting library for one sparkline-style
   chart; swap for Chart.js/Recharts if the panel grows more series later.
   ========================================================================== */

const MiniChart = (function () {

  function drawNDVILine(canvas, series, currentYear) {
    const ctx = canvas.getContext("2d");
    const dpr = window.devicePixelRatio || 1;
    const w = canvas.clientWidth, h = canvas.clientHeight;
    canvas.width = w * dpr; canvas.height = h * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);

    const pad = { l: 28, r: 10, t: 10, b: 18 };
    const plotW = w - pad.l - pad.r, plotH = h - pad.t - pad.b;
    const values = series.map(s => s.ndvi);
    const minV = 0, maxV = 1;

    // gridlines
    ctx.strokeStyle = "rgba(255,255,255,0.06)";
    ctx.lineWidth = 1;
    [0, 0.25, 0.5, 0.75, 1].forEach(v => {
      const y = pad.t + plotH - (v - minV) / (maxV - minV) * plotH;
      ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(w - pad.r, y); ctx.stroke();
      ctx.fillStyle = "#56667e"; ctx.font = "9px 'IBM Plex Mono', monospace";
      ctx.fillText(v.toFixed(2), 2, y + 3);
    });

    function xAt(i) { return pad.l + (i / (series.length - 1)) * plotW; }
    function yAt(v) { return pad.t + plotH - (v - minV) / (maxV - minV) * plotH; }

    // gradient area under line
    const grad = ctx.createLinearGradient(0, pad.t, 0, pad.t + plotH);
    grad.addColorStop(0, "rgba(217,193,74,0.30)");
    grad.addColorStop(1, "rgba(217,193,74,0.00)");
    ctx.beginPath();
    ctx.moveTo(xAt(0), yAt(values[0]));
    values.forEach((v, i) => ctx.lineTo(xAt(i), yAt(v)));
    ctx.lineTo(xAt(values.length - 1), pad.t + plotH);
    ctx.lineTo(xAt(0), pad.t + plotH);
    ctx.closePath();
    ctx.fillStyle = grad;
    ctx.fill();

    // line
    ctx.beginPath();
    values.forEach((v, i) => { const x = xAt(i), y = yAt(v); i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
    ctx.strokeStyle = "#cfa86e";
    ctx.lineWidth = 2;
    ctx.stroke();

    // points + year labels
    series.forEach((s, i) => {
      const x = xAt(i), y = yAt(s.ndvi);
      const isCurrent = s.year === currentYear;
      ctx.beginPath();
      ctx.arc(x, y, isCurrent ? 4 : 2.5, 0, Math.PI * 2);
      ctx.fillStyle = isCurrent ? "#F58220" : "#cfa86e";
      ctx.fill();
      if (isCurrent) {
        ctx.strokeStyle = "rgba(245,130,32,0.4)"; ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(x, y, 7, 0, Math.PI * 2); ctx.stroke();
      }
      ctx.fillStyle = isCurrent ? "#faf7f2" : "#6e675f";
      ctx.font = "9px 'IBM Plex Mono', monospace";
      ctx.textAlign = "center";
      ctx.fillText(String(s.year).slice(2), x, h - 4);
    });
    ctx.textAlign = "left";
  }

  return { drawNDVILine };
})();

window.MiniChart = MiniChart;

/* ==========================================================================
   Geospatial Lab — UI
   ========================================================================== */
/* ============================================================================
   ui.js — small shared UI utilities used across modules: toast notifications
   and the mobile drawer open/close behavior for the left/right panels.
   ========================================================================== */

const UI = (function () {

  function toast(message, kind = "") {
    const stack = document.getElementById("toast-stack");
    if (!stack) return;
    const el = document.createElement("div");
    el.className = "toast" + (kind ? " " + kind : "");
    el.textContent = message;
    stack.appendChild(el);
    setTimeout(() => {
      el.style.transition = "opacity .25s ease";
      el.style.opacity = "0";
      setTimeout(() => el.remove(), 260);
    }, 3200);
  }

  function initMobileDrawers() {
    const left = document.getElementById("left-panel");
    const right = document.getElementById("right-panel");
    const openLeft = document.getElementById("open-left");
    const openRight = document.getElementById("open-right");
    const openLeftDesktop = document.getElementById("open-left-desktop");

    openLeft?.addEventListener("click", () => {
      right.classList.remove("open");
      left.classList.toggle("open");
    });
    openRight?.addEventListener("click", () => {
      left.classList.remove("open");
      right.classList.toggle("open");
    });
    // desktop icon toggles the left panel's visibility on narrow desktop windows too
    openLeftDesktop?.addEventListener("click", () => {
      if (window.innerWidth <= 880) left.classList.toggle("open");
      else left.style.display = (left.style.display === "none") ? "" : "none";
    });
    // tapping the map area closes drawers on mobile
    document.getElementById("map-wrap")?.addEventListener("click", (e) => {
      if (window.innerWidth <= 880 && !e.target.closest(".drawer-tab")) {
        left.classList.remove("open");
        right.classList.remove("open");
      }
    });
  }

  return { toast, initMobileDrawers };
})();

window.UI = UI;

/* ==========================================================================
   Geospatial Lab — map core
   ========================================================================== */
/* ============================================================================
   mapCore.js
   ----------------------------------------------------------------------------
   Sets up the Leaflet map instance, the free no-key dark basemap, location
   search, reset view, status-bar coordinate readout, and the click-to-inspect
   pixel popup.

   >>> REAL DATA INTEGRATION POINT <<<
   Swap TILE_URL for a licensed provider (Mapbox/Google/Planet/Maxar) when
   real tokens are available — everything else in the app is agnostic to
   which basemap is underneath.
   ========================================================================== */

const MapCore = (function () {

  // CARTO's free "dark matter" basemap — no API key required, fine for
  // demo/dev traffic. This is the "convincing local/demo satellite-style
  // background" fallback described in the brief; swap for a real satellite
  // tile provider + key in production.
  const TILE_URL = "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png";
  const TILE_ATTR = '&copy; <a href="https://carto.com/attributions">CARTO</a> &copy; OpenStreetMap contributors';

  let map, baseLayer, inspectMarkerLayer;

  function init() {
    const mapMount = document.getElementById("map");
    if (!mapMount) return null;
    if (typeof L === "undefined") {
      // Graceful degradation: Leaflet CDN failed to load entirely.
      mapMount.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:center;height:100%;color:#93a3b8;font-family:monospace;padding:20px;text-align:center;">' +
        'Map engine (Leaflet) could not be loaded from the CDN.<br>Check your network connection and reload.</div>';
      return null;
    }

    map = L.map("map", {
      zoomControl: false,
      attributionControl: true,
      center: DEMO_DATA.mapDefault.center,
      zoom: DEMO_DATA.mapDefault.zoom,
      minZoom: 3,
      maxZoom: 18
    });

    baseLayer = L.tileLayer(TILE_URL, { attribution: TILE_ATTR, maxZoom: 18 });
    baseLayer.on("tileerror", () => {
      // Fallback if even the free CARTO tiles are unreachable (fully offline):
      // paint a plain dark background so the app still functions.
      document.getElementById("map").style.background = "#0f152f";
    });
    baseLayer.addTo(map);

    L.control.zoom({ position: "bottomright" }).addTo(map);

    inspectMarkerLayer = L.layerGroup().addTo(map);

    map.on("mousemove", (e) => {
      const el = document.getElementById("status-left");
      if (el) el.textContent = `ZOOM ${map.getZoom()} · ${e.latlng.lat.toFixed(4)}, ${e.latlng.lng.toFixed(4)}`;
    });

    return map;
  }

  function resetView() {
    map.setView(DEMO_DATA.mapDefault.center, DEMO_DATA.mapDefault.zoom);
    UI.toast("View reset to default extent");
  }

  /** Basic search: "lat,lng" direct jump, else free Nominatim geocoding (no key). */
  async function searchLocation(query) {
    const latlngMatch = query.match(/^\s*(-?\d+(\.\d+)?)\s*,\s*(-?\d+(\.\d+)?)\s*$/);
    if (latlngMatch) {
      const lat = parseFloat(latlngMatch[1]), lng = parseFloat(latlngMatch[3]);
      map.setView([lat, lng], 13);
      UI.toast(`Jumped to ${lat.toFixed(4)}, ${lng.toFixed(4)}`);
      return;
    }
    try {
      const res = await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(query)}`);
      const data = await res.json();
      if (data && data[0]) {
        map.setView([parseFloat(data[0].lat), parseFloat(data[0].lon)], 12);
        UI.toast(`Located: ${data[0].display_name.split(",")[0]}`);
      } else {
        UI.toast("No matching location found", "alert");
      }
    } catch (e) {
      UI.toast("Search unavailable offline — try lat,lng format", "alert");
    }
  }

  /** Click-to-inspect: shows a popup with demo RGB/NDVI/elevation for the pixel. */
  function enableInspection(getCurrentYearFn) {
    map.on("click", (e) => {
      if (window.DrawingTool && DrawingTool.isDrawing()) return; // don't fight the draw tool
      const year = getCurrentYearFn ? getCurrentYearFn() : 2025;
      const sample = Analysis.analyzePoint(e.latlng.lat, e.latlng.lng, year);
      const html = `
        <div class="pixel-popup">
          <div class="pp-title">Pixel / Location Info</div>
          <div class="pp-row"><span>Latitude</span><b>${sample.lat}</b></div>
          <div class="pp-row"><span>Longitude</span><b>${sample.lng}</b></div>
          <div class="pp-row"><span>RGB</span><b>${sample.rgb.r}, ${sample.rgb.g}, ${sample.rgb.b}</b></div>
          <div class="pp-row"><span>NDVI</span><b>${sample.ndvi}</b></div>
          <div class="pp-row"><span>Elevation</span><b>${sample.elevation}m</b></div>
          <div class="pp-row"><span>Acquisition</span><b>${DEMO_DATA.datasets.D08.acquisition}</b></div>
        </div>`;
      L.popup({ closeButton: true }).setLatLng(e.latlng).setContent(html).openOn(map);
    });
  }

  function getMap() { return map; }

  return { init, resetView, searchLocation, enableInspection, getMap, TILE_URL };
})();

window.MapCore = MapCore;

/* ==========================================================================
   Geospatial Lab — layers
   ========================================================================== */
/* ============================================================================
   layers.js
   ----------------------------------------------------------------------------
   Renders the Data Layer Panel from DEMO_DATA.layers and owns the live
   Leaflet layer objects. This is the only module that mutates what's drawn
   on the map for base/dataset/imagery/analytic layers (drawing.js owns the
   user-drawn AOI geometry separately).
   ========================================================================== */

const Layers = (function () {

  const active = {};      // id -> Leaflet layer instance currently on the map
  const state = {};        // id -> { on:boolean, opacity:number }
  let currentDataset = "D08";
  let currentYear = 2025;

  function init() {
    DEMO_DATA.layers.forEach(l => { state[l.id] = { on: l.defaultOn, opacity: l.opacity }; });
    renderLayerList();
    renderDatasetMeta();
    bindDatasetChips();
    updateLayers();
  }

  function renderLayerList() {
    const container = document.getElementById("layer-list");
    container.innerHTML = "";
    DEMO_DATA.layers.forEach(l => {
      if (l.id === "d02" || l.id === "d04" || l.id === "d08") return; // handled via chips, not individual toggles
      const row = document.createElement("div");
      row.className = "layer-row" + (state[l.id].on ? " active" : "");
      row.dataset.layerId = l.id;
      row.innerHTML = `
        <div class="layer-row-head" data-toggle="${l.id}">
          <div class="layer-name"><span class="layer-swatch" style="background:${l.color}"></span>${l.name}</div>
          <div class="switch ${state[l.id].on ? "on" : ""}" data-switch="${l.id}"></div>
        </div>
        <div class="layer-desc">${l.desc}</div>
        <div class="layer-meta">Resolution: ${l.resolution}</div>
        <div class="opacity-row">
          <input type="range" min="0" max="1" step="0.05" value="${state[l.id].opacity}" data-opacity="${l.id}">
          <span>${Math.round(state[l.id].opacity * 100)}%</span>
        </div>`;
      container.appendChild(row);
    });

    container.querySelectorAll("[data-toggle]").forEach(el => {
      el.addEventListener("click", (e) => {
        if (e.target.matches("input[type=range]")) return;
        toggleLayer(el.dataset.toggle);
      });
    });
    container.querySelectorAll("[data-opacity]").forEach(el => {
      el.addEventListener("input", (e) => {
        const id = el.dataset.opacity;
        state[id].opacity = parseFloat(e.target.value);
        el.nextElementSibling.textContent = Math.round(state[id].opacity * 100) + "%";
        if (active[id]) active[id].setOpacity ? active[id].setOpacity(state[id].opacity) : null;
      });
    });
  }

  function renderDatasetMeta() {
    const meta = DEMO_DATA.datasets[currentDataset];
    document.getElementById("dataset-meta").innerHTML = `
      <div class="k">Resolution</div><div class="v">${meta.resolution}</div>
      <div class="k">Bands</div><div class="v">${meta.bands}</div>
      <div class="k">CRS</div><div class="v">${meta.crs}</div>
      <div class="k">Acquisition</div><div class="v">${meta.acquisition}</div>
      <div class="k">Coverage</div><div class="v">${meta.coverage}</div>
      <div class="k">Sensor</div><div class="v">${meta.sensor}</div>`;
    document.getElementById("crs-readout").textContent = `${meta.crs} · Demo Dataset ${currentDataset}`;
  }

  function bindDatasetChips() {
    document.querySelectorAll("#dataset-chips .chip").forEach(chip => {
      chip.addEventListener("click", () => {
        document.querySelectorAll("#dataset-chips .chip").forEach(c => c.classList.remove("active"));
        chip.classList.add("active");
        currentDataset = chip.dataset.dataset;
        renderDatasetMeta();
        // turn on the corresponding dataset raster layer, replacing any other dataset layer
        ["d02", "d04", "d08"].forEach(id => { if (active[id]) { getMapSafe().removeLayer(active[id]); delete active[id]; } });
        state[currentDataset.toLowerCase()] = { on: true, opacity: 0.85 };
        addDatasetLayer(currentDataset.toLowerCase());
        UI.toast(`Switched to ${currentDataset} dataset`);
      });
    });
  }

  function getMapSafe() { return MapCore.getMap(); }

  async function addDatasetLayer(id) {
    const map = getMapSafe();
    if (!map) return;
    const layer = await GeoLoader.addRasterLayer(map, id, { year: currentYear, opacity: state[id]?.opacity ?? 0.85, seed: "demo-aoi" });
    active[id] = layer;
  }

  function toggleLayer(id) {
    state[id].on = !state[id].on;
    const row = document.querySelector(`.layer-row[data-layer-id="${id}"]`);
    const sw = document.querySelector(`[data-switch="${id}"]`);
    row?.classList.toggle("active", state[id].on);
    sw?.classList.toggle("on", state[id].on);
    updateLayers();
    if (id === "ndvi" || id === "deforestation") renderLegend();
    UI.toast(`${state[id].on ? "Enabled" : "Disabled"} ${DEMO_DATA.layers.find(l => l.id === id).name}`);
  }

  /** updateLayers() — reconciles `state` with what's actually on the map. */
  async function updateLayers() {
    const map = getMapSafe();
    if (!map) return;
    for (const l of DEMO_DATA.layers) {
      if (l.group === "dataset") continue; // handled by dataset chips
      const shouldShow = state[l.id].on;
      const isShown = !!active[l.id];
      if (l.id === "basemap") continue; // base tile layer is permanent
      if (shouldShow && !isShown) {
        const layer = await GeoLoader.addRasterLayer(map, l.id, { year: currentYear, opacity: state[l.id].opacity, seed: "demo-aoi" });
        active[l.id] = layer;
      } else if (!shouldShow && isShown) {
        map.removeLayer(active[l.id]);
        delete active[l.id];
      } else if (shouldShow && isShown && active[l.id].setOpacity) {
        active[l.id].setOpacity(state[l.id].opacity);
      }
    }
    // make sure current dataset chip's raster is present
    const dsId = currentDataset.toLowerCase();
    if (!active[dsId]) await addDatasetLayer(dsId);
  }

  /** Called by timeseries.js when the year changes — re-renders year-sensitive rasters. */
  async function refreshForYear(year) {
    currentYear = year;
    const map = getMapSafe();
    for (const id of ["rgb", "ndvi", "deforestation"]) {
      if (active[id]) {
        map.removeLayer(active[id]);
        delete active[id];
        if (state[id].on) {
          active[id] = await GeoLoader.addRasterLayer(map, id, { year, opacity: state[id].opacity, seed: "demo-aoi" });
        }
      }
    }
  }

  function renderLegend() {
    const box = document.getElementById("legend-box");
    if (state.ndvi.on) {
      const stops = DEMO_DATA.ndviLegend;
      box.innerHTML = `
        <div class="legend-gradient" style="background:linear-gradient(90deg, ${stops.slice().reverse().map(s => s.color).join(",")})"></div>
        <div class="legend" style="display:flex;flex-direction:row;justify-content:space-between;">
          ${stops.map(s => `<span style="font-family:var(--mono);font-size:9.5px;color:var(--text-low);">${s.v}</span>`).join("")}
        </div>`;
    } else if (state.deforestation.on) {
      box.innerHTML = `<div class="legend">${DEMO_DATA.deforestationLegend.map(l =>
        `<div class="legend-row"><span class="legend-swatch" style="background:${l.color}"></span>${l.label}</div>`).join("")}</div>`;
    } else {
      box.innerHTML = `<div class="empty-state">Enable NDVI or Deforestation to see its legend here.</div>`;
    }
  }

  /** Re-syncs the DOM switches/row highlighting after a programmatic state change
      (e.g. Demo Mode toggling layers on directly via getState()). */
  function syncLayerUI() {
    DEMO_DATA.layers.forEach(l => {
      if (l.group === "dataset") return;
      const row = document.querySelector(`.layer-row[data-layer-id="${l.id}"]`);
      const sw = document.querySelector(`[data-switch="${l.id}"]`);
      row?.classList.toggle("active", !!state[l.id]?.on);
      sw?.classList.toggle("on", !!state[l.id]?.on);
    });
  }

  function isOn(id) { return !!state[id]?.on; }
  function getState() { return state; }
  function getCurrentDataset() { return currentDataset; }
  function getCurrentYear() { return currentYear; }
  function setCurrentYear(y) { currentYear = y; }

  return {
    init, toggleLayer, updateLayers, refreshForYear, renderLegend, syncLayerUI,
    isOn, getState, getCurrentDataset, getCurrentYear, setCurrentYear
  };
})();

window.Layers = Layers;

/* ==========================================================================
   Geospatial Lab — drawing
   ========================================================================== */
/* ============================================================================
   drawing.js
   ----------------------------------------------------------------------------
   Owns the POINT / POLYGON / MULTIPOLYGON / CLEAR toolbar and the resulting
   drawn-geometry layer group. Emits DOM CustomEvents so app.js (and any other
   listener) can react without this module knowing about the right-hand panel:

     "aoi:point"        detail = { latlng, analysis }
     "aoi:polygon"      detail = { feature, stats }
     "aoi:multipolygon" detail = { feature, stats, count }
     "aoi:cleared"      detail = {}

   Falls back to a plain click-to-place-marker/polygon flow if the
   Leaflet.draw CDN failed to load (checked via `typeof L.Draw`).
   ========================================================================== */

const DrawingTool = (function () {

  let map, drawnItems, activeHandler = null, activeTool = null;
  let multiPolyLayers = []; // accumulated polygons while in MULTIPOLYGON mode

  function init(leafletMap) {
    map = leafletMap;
    if (!map || typeof L === "undefined") return;
    drawnItems = new L.FeatureGroup().addTo(map);

    document.getElementById("tool-point").addEventListener("click", () => selectTool("point"));
    document.getElementById("tool-polygon").addEventListener("click", () => selectTool("polygon"));
    document.getElementById("tool-multipolygon").addEventListener("click", () => selectTool("multipolygon"));
    document.getElementById("tool-clear").addEventListener("click", clearAll);

    if (typeof L.Draw !== "undefined") {
      map.on(L.Draw.Event.CREATED, onShapeCreated);
    } else {
      console.warn("[DrawingTool] Leaflet.draw not available — CDN may be blocked. Drawing tools disabled.");
      UI.toast("Drawing library unavailable offline — spatial drawing disabled", "alert");
    }
  }

  function setActiveButton(tool) {
    document.querySelectorAll(".tool-btn").forEach(b => b.classList.remove("active"));
    if (tool) document.getElementById(`tool-${tool}`)?.classList.add("active");
  }

  function selectTool(tool) {
    if (typeof L === "undefined" || typeof L.Draw === "undefined") return;
    // toggle off if re-clicking the active tool
    if (activeTool === tool) { cancelActive(); return; }
    cancelActive();
    activeTool = tool;
    setActiveButton(tool);

    if (tool === "point") {
      activeHandler = new L.Draw.Marker(map, {}); // default Leaflet.draw marker icon
      activeHandler.enable();
    } else if (tool === "polygon") {
      multiPolyLayers = [];
      activeHandler = new L.Draw.Polygon(map, { shapeOptions: { color: "#F58220", weight: 2, fillOpacity: 0.12 } });
      activeHandler.enable();
    } else if (tool === "multipolygon") {
      activeHandler = new L.Draw.Polygon(map, { shapeOptions: { color: "#464f79", weight: 2, fillOpacity: 0.12 } });
      activeHandler.enable();
    }
  }

  function cancelActive() {
    if (activeHandler && activeHandler.disable) activeHandler.disable();
    activeHandler = null; activeTool = null;
    setActiveButton(null);
  }

  function isDrawing() { return !!activeTool; }

  function onShapeCreated(e) {
    const layer = e.layer;

    if (e.layerType === "marker") {
      layer.addTo(drawnItems);
      const latlng = layer.getLatLng();
      const analysisResult = Analysis.analyzePoint(latlng.lat, latlng.lng, Layers.getCurrentYear());
      document.dispatchEvent(new CustomEvent("aoi:point", { detail: { latlng, analysis: analysisResult } }));
      cancelActive();
      return;
    }

    if (e.layerType === "polygon") {
      if (activeTool === "multipolygon") {
        layer.addTo(drawnItems);
        multiPolyLayers.push(layer);
        const feature = buildMultiPolygonFeature(multiPolyLayers);
        const stats = Analysis.calculateAOI(feature, Layers.getCurrentYear());
        document.dispatchEvent(new CustomEvent("aoi:multipolygon", { detail: { feature, stats, count: multiPolyLayers.length } }));
        // stay in multipolygon mode so the user can keep adding shapes
        activeHandler = new L.Draw.Polygon(map, { shapeOptions: { color: "#464f79", weight: 2, fillOpacity: 0.12 } });
        activeHandler.enable();
      } else {
        drawnItems.clearLayers();
        multiPolyLayers = [];
        layer.addTo(drawnItems);
        const feature = { type: "Feature", properties: {}, geometry: layer.toGeoJSON().geometry };
        const stats = Analysis.calculateAOI(feature, Layers.getCurrentYear());
        document.dispatchEvent(new CustomEvent("aoi:polygon", { detail: { feature, stats } }));
        cancelActive();
      }
    }
  }

  function buildMultiPolygonFeature(layers) {
    const coordinates = layers.map(l => l.toGeoJSON().geometry.coordinates);
    return { type: "Feature", properties: {}, geometry: { type: "MultiPolygon", coordinates } };
  }

  function clearAll() {
    cancelActive();
    if (drawnItems) drawnItems.clearLayers();
    multiPolyLayers = [];
    document.dispatchEvent(new CustomEvent("aoi:cleared"));
    UI.toast("Cleared drawn geometry");
  }

  /** Used by "Explore Demo Area" to programmatically load the predefined AOI. */
  function loadDemoAOI() {
    cancelActive();
    drawnItems.clearLayers();
    multiPolyLayers = [];
    const feature = DEMO_DATA.defaultAOI;
    const layer = L.geoJSON(feature, { style: { color: "#F58220", weight: 2, fillOpacity: 0.12 } });
    layer.eachLayer(l => l.addTo(drawnItems));
    map.fitBounds(layer.getBounds(), { padding: [60, 60] });
    const stats = Analysis.calculateAOI(feature, Layers.getCurrentYear());
    document.dispatchEvent(new CustomEvent("aoi:polygon", { detail: { feature, stats } }));
  }

  function getDrawnItems() { return drawnItems; }

  return { init, isDrawing, clearAll, loadDemoAOI, getDrawnItems };
})();

window.DrawingTool = DrawingTool;

/* ==========================================================================
   Geospatial Lab — timeseries
   ========================================================================== */
/* ============================================================================
   timeseries.js
   ----------------------------------------------------------------------------
   Renders the year timeline, drives play/pause/speed, and re-renders
   year-sensitive rasters (RGB, NDVI, deforestation) through Layers.refreshForYear.
   Dispatches "timeline:year" so app.js can refresh the AOI panel/chart/AI copy
   for whatever geometry is currently selected.

   >>> REAL DATA INTEGRATION POINT <<<
   GET /api/geospatial/timeseries would replace DEMO_DATA.years / the demo
   NDVI-per-year series consumed here; updateYear() itself needs no change.
   ========================================================================== */

const Timeseries = (function () {

  let currentIndex = DEMO_DATA.years.length - 1; // start on latest year (2025)
  let playing = false, timer = null;

  function init() {
    renderTicks();
    document.getElementById("play-btn").addEventListener("click", togglePlay);
    document.getElementById("speed-select").addEventListener("change", () => {
      if (playing) { stop(); play(); }
    });
    setYearIndex(currentIndex, { silent: true });
  }

  function renderTicks() {
    const track = document.getElementById("timeline-track");
    track.querySelectorAll(".year-tick, .year-label").forEach(el => el.remove());
    DEMO_DATA.years.forEach((year, i) => {
      const pct = (i / (DEMO_DATA.years.length - 1)) * 100;
      const tick = document.createElement("div");
      tick.className = "year-tick"; tick.style.left = pct + "%";
      tick.dataset.index = i;
      tick.addEventListener("click", () => setYearIndex(i));
      track.appendChild(tick);

      const label = document.createElement("div");
      label.className = "year-label"; label.style.left = pct + "%";
      label.textContent = year;
      track.appendChild(label);
    });
  }

  async function setYearIndex(i, opts = {}) {
    currentIndex = i;
    const year = DEMO_DATA.years[i];
    Layers.setCurrentYear(year);
    document.getElementById("year-indicator").textContent = year;
    document.getElementById("timeline-fill").style.width = (i / (DEMO_DATA.years.length - 1)) * 100 + "%";
    document.querySelectorAll(".year-tick").forEach((t, idx) => {
      t.classList.toggle("current", idx === i);
      t.classList.toggle("past", idx < i);
    });
    document.querySelectorAll(".year-label").forEach((l, idx) => l.classList.toggle("current", idx === i));

    await Layers.refreshForYear(year);
    if (!opts.silent) document.dispatchEvent(new CustomEvent("timeline:year", { detail: { year } }));
  }

  function togglePlay() {
    playing ? stop() : play();
  }
  function play() {
    playing = true;
    document.getElementById("play-btn").textContent = "❚❚";
    const speed = parseInt(document.getElementById("speed-select").value, 10);
    timer = setInterval(async () => {
      let next = currentIndex + 1;
      if (next >= DEMO_DATA.years.length) next = 0;
      await setYearIndex(next);
    }, speed);
  }
  function stop() {
    playing = false;
    document.getElementById("play-btn").textContent = "▶";
    clearInterval(timer);
  }

  function getCurrentYear() { return DEMO_DATA.years[currentIndex]; }

  return { init, setYearIndex, getCurrentYear };
})();

window.Timeseries = Timeseries;

/* ==========================================================================
   Geospatial Lab — compare
   ========================================================================== */
/* ============================================================================
   compare.js
   ----------------------------------------------------------------------------
   Full-screen draggable before/after comparison over the map, supporting
   RGB / NDVI / Deforestation modes and independent left/right year pickers.
   Uses the same procedural raster generator as the live map layers so the
   comparison stays visually consistent with what's plotted elsewhere.
   ========================================================================== */

const Compare = (function () {

  let active = false, mode = "rgb", dragging = false;
  let leftYear = 2021, rightYear = 2025;

  function init() {
    const wrap = document.getElementById("compare-wrap");
    const handle = document.getElementById("compare-handle");
    const afterPane = document.getElementById("compare-after");
    const toggleBtn = document.getElementById("btn-toggle-compare");
    const pill = document.getElementById("viewmode-pill");
    const leftSelect = document.getElementById("compare-year-left");
    const rightSelect = document.getElementById("compare-year-right");

    DEMO_DATA.years.forEach(y => {
      leftSelect.innerHTML += `<option value="${y}" ${y === leftYear ? "selected" : ""}>${y}</option>`;
      rightSelect.innerHTML += `<option value="${y}" ${y === rightYear ? "selected" : ""}>${y}</option>`;
    });

    toggleBtn.addEventListener("click", () => { active ? deactivate() : activate(); });

    leftSelect.addEventListener("change", (e) => { leftYear = parseInt(e.target.value, 10); render(); });
    rightSelect.addEventListener("change", (e) => { rightYear = parseInt(e.target.value, 10); render(); });

    pill.querySelectorAll("button").forEach(btn => {
      btn.addEventListener("click", () => {
        pill.querySelectorAll("button").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        mode = btn.dataset.mode;
        render();
      });
    });

    handle.addEventListener("mousedown", () => dragging = true);
    handle.addEventListener("touchstart", () => dragging = true, { passive: true });
    window.addEventListener("mouseup", () => dragging = false);
    window.addEventListener("touchend", () => dragging = false);
    window.addEventListener("mousemove", (e) => { if (dragging) moveHandle(e.clientX); });
    window.addEventListener("touchmove", (e) => { if (dragging) moveHandle(e.touches[0].clientX); }, { passive: true });
  }

  function moveHandle(clientX) {
    const wrap = document.getElementById("compare-wrap");
    const rect = wrap.getBoundingClientRect();
    let pct = ((clientX - rect.left) / rect.width) * 100;
    pct = Math.max(2, Math.min(98, pct));
    document.getElementById("compare-handle").style.left = pct + "%";
    document.getElementById("compare-after").style.width = pct + "%";
  }

  function activate() {
    active = true;
    document.getElementById("compare-wrap").classList.add("show");
    document.getElementById("viewmode-pill").style.display = "flex";
    document.getElementById("btn-toggle-compare").classList.add("btn-ai");
    render();
    UI.toast("Before / after comparison active — drag the divider");
  }
  function deactivate() {
    active = false;
    document.getElementById("compare-wrap").classList.remove("show");
    document.getElementById("viewmode-pill").style.display = "none";
  }

  function renderInto(canvas, year) {
    const raster = mode === "rgb" ? ProceduralRaster.renderRGB("demo-aoi", year)
                 : mode === "ndvi" ? ProceduralRaster.renderNDVI("demo-aoi", year)
                 : ProceduralRaster.renderChange("demo-aoi", year);
    canvas.width = raster.width; canvas.height = raster.height;
    canvas.getContext("2d").drawImage(raster, 0, 0);
    // Both panes render at the SAME width (the full compare-wrap width) so the
    // "after" pane lines up pixel-for-pixel with the "before" pane; only its
    // *container* is clipped narrower by the drag handle, not the image itself.
    const wrapWidth = document.getElementById("compare-wrap").clientWidth;
    canvas.style.width = wrapWidth + "px";
    canvas.style.height = "100%";
  }

  function render() {
    if (!active) return;
    renderInto(document.querySelector("#compare-before canvas"), leftYear);
    renderInto(document.querySelector("#compare-after canvas"), rightYear);
    document.querySelector(".compare-label.left").style.background = "rgba(5,7,10,.75)";
  }

  return { init, activate, deactivate, isActive: () => active };
})();

window.Compare = Compare;

/* ==========================================================================
   Geospatial Lab — upload
   ========================================================================== */
/* ============================================================================
   upload.js
   ----------------------------------------------------------------------------
   "Bring Your Own Data" — drag & drop / file picker.

   Honesty rule (per the brief): never claim a file parsed successfully if it
   didn't. GeoJSON and CSV are genuinely parsed and added to the map. GeoTIFF
   is genuinely parsed IF the georaster CDN loaded; otherwise we say so.
   Shapefile ZIP is genuinely parsed IF shpjs loaded; otherwise we say so.
   KML gets a minimal real parser for Point/LineString/Polygon Placemarks.
   ========================================================================== */

const Upload = (function () {

  function init(map) {
    const zone = document.getElementById("upload-zone");
    const input = document.getElementById("file-input");

    zone.addEventListener("click", () => input.click());
    zone.addEventListener("dragover", (e) => { e.preventDefault(); zone.classList.add("drag"); });
    zone.addEventListener("dragleave", () => zone.classList.remove("drag"));
    zone.addEventListener("drop", (e) => {
      e.preventDefault(); zone.classList.remove("drag");
      handleFiles(e.dataTransfer.files, map);
    });
    input.addEventListener("change", (e) => handleFiles(e.target.files, map));
  }

  function handleFiles(fileList, map) {
    Array.from(fileList).forEach(file => processFile(file, map));
  }

  function addResultRow(name, statusText, ok) {
    const list = document.getElementById("upload-list");
    const row = document.createElement("div");
    row.className = "upload-item " + (ok ? "ok" : "warn");
    row.innerHTML = `<span>${ok ? "✓" : "!"} ${name}</span><span class="uf-status">${statusText}</span>`;
    list.prepend(row);
  }

  async function processFile(file, map) {
    const ext = file.name.split(".").pop().toLowerCase();
    try {
      if (ext === "geojson" || ext === "json") return await handleGeoJSON(file, map);
      if (ext === "kml") return await handleKML(file, map);
      if (ext === "csv") return await handleCSV(file, map);
      if (ext === "tif" || ext === "tiff") return await handleGeoTIFF(file, map);
      if (ext === "zip") return await handleShapefile(file, map);
      addResultRow(file.name, "Unsupported format", false);
      UI.toast(`${file.name}: unsupported format for browser preview`, "alert");
    } catch (err) {
      console.error("[Upload] failed to process", file.name, err);
      addResultRow(file.name, "Parse error", false);
      UI.toast(`Couldn't parse ${file.name}`, "alert");
    }
  }

  async function handleGeoJSON(file, map) {
    const text = await file.text();
    const geojson = JSON.parse(text);
    const layer = GeoLoader.addVectorLayer(map, geojson, { color: "#37c98a" });
    if (layer.getBounds().isValid()) map.fitBounds(layer.getBounds(), { padding: [50, 50] });
    addResultRow(file.name, "Vector detected", true);
    UI.toast(`${file.name} added as a vector layer`, "veg");
  }

  async function handleCSV(file, map) {
    const text = await file.text();
    const rows = text.trim().split(/\r?\n/).map(r => r.split(","));
    const header = rows[0].map(h => h.trim().toLowerCase());
    const latIdx = header.findIndex(h => h.includes("lat"));
    const lngIdx = header.findIndex(h => h.includes("lon") || h.includes("lng"));
    if (latIdx === -1 || lngIdx === -1) {
      addResultRow(file.name, "No lat/lng columns found", false);
      UI.toast(`${file.name}: couldn't find latitude/longitude columns`, "alert");
      return;
    }
    const group = L.layerGroup();
    let count = 0;
    rows.slice(1).forEach(r => {
      const lat = parseFloat(r[latIdx]), lng = parseFloat(r[lngIdx]);
      if (isFinite(lat) && isFinite(lng)) {
        L.circleMarker([lat, lng], { radius: 5, color: "#F58220", fillOpacity: 0.7 }).addTo(group);
        count++;
      }
    });
    group.addTo(map);
    if (count) map.fitBounds(group.getBounds(), { padding: [50, 50] });
    addResultRow(file.name, `${count} points plotted`, count > 0);
    UI.toast(`${file.name}: plotted ${count} points from CSV`);
  }

  async function handleGeoTIFF(file, map) {
    if (!window.GeoTIFF || !window.parseGeoraster || !window.GeoRasterLayer) {
      addResultRow(file.name, "Raster detected (preview needs georaster CDN)", false);
      UI.toast(`${file.name}: GeoTIFF detected, but the georaster library isn't loaded — can't render it in this session`, "alert");
      return;
    }
    const buffer = await file.arrayBuffer();
    const georaster = await window.parseGeoraster(buffer);
    const layer = new GeoRasterLayer({ georaster, opacity: 0.85, resolution: 256 });
    layer.addTo(map);
    map.fitBounds(layer.getBounds());
    addResultRow(file.name, "Raster detected", true);
    UI.toast(`${file.name} added as a raster layer`, "veg");
  }

  async function handleShapefile(file, map) {
    if (!window.shp) {
      addResultRow(file.name, "Shapefile detected (needs shpjs CDN)", false);
      UI.toast(`${file.name}: Shapefile ZIP detected, but the shpjs library isn't loaded — can't render it in this session`, "alert");
      return;
    }
    const buffer = await file.arrayBuffer();
    const geojson = await window.shp(buffer);
    const layer = GeoLoader.addVectorLayer(map, geojson, { color: "#464f79" });
    if (layer.getBounds().isValid()) map.fitBounds(layer.getBounds(), { padding: [50, 50] });
    addResultRow(file.name, "Vector detected", true);
    UI.toast(`${file.name} added as a vector layer`, "veg");
  }

  /** Minimal real KML parser: extracts Point/LineString/Polygon Placemarks. */
  async function handleKML(file, map) {
    const text = await file.text();
    const xml = new DOMParser().parseFromString(text, "text/xml");
    if (xml.querySelector("parsererror")) throw new Error("Invalid KML/XML");

    const features = [];
    xml.querySelectorAll("Placemark").forEach(pm => {
      const name = pm.querySelector("name")?.textContent || "Placemark";
      const point = pm.querySelector("Point > coordinates")?.textContent;
      const line = pm.querySelector("LineString > coordinates")?.textContent;
      const poly = pm.querySelector("Polygon coordinates")?.textContent;
      const parseCoords = (str) => str.trim().split(/\s+/).map(pair => {
        const [lng, lat] = pair.split(",").map(Number);
        return [lng, lat];
      });
      if (point) {
        const [lng, lat] = parseCoords(point)[0];
        features.push({ type: "Feature", properties: { name }, geometry: { type: "Point", coordinates: [lng, lat] } });
      } else if (line) {
        features.push({ type: "Feature", properties: { name }, geometry: { type: "LineString", coordinates: parseCoords(line) } });
      } else if (poly) {
        features.push({ type: "Feature", properties: { name }, geometry: { type: "Polygon", coordinates: [parseCoords(poly)] } });
      }
    });

    if (!features.length) {
      addResultRow(file.name, "No supported geometry found", false);
      UI.toast(`${file.name}: parsed, but no Point/LineString/Polygon placemarks found`, "alert");
      return;
    }
    const fc = { type: "FeatureCollection", features };
    const layer = GeoLoader.addVectorLayer(map, fc, { color: "#d9c14a" });
    if (layer.getBounds().isValid()) map.fitBounds(layer.getBounds(), { padding: [50, 50] });
    addResultRow(file.name, `Vector detected (${features.length} features)`, true);
    UI.toast(`${file.name} added as a vector layer`, "veg");
  }

  return { init };
})();

window.Upload = Upload;

/* ==========================================================================
   Geospatial Lab — app boot
   ========================================================================== */
/* ============================================================================
   app.js
   ----------------------------------------------------------------------------
   Wires all modules together: boots the map, layer panel, drawing tools,
   timeline, comparison view and uploader, then owns the right-hand AOI / AI
   / deforestation / temporal panels that react to geometry + year changes.
   ========================================================================== */

(function () {

  let currentFeature = null;
  let currentStats = null;
  let currentType = null; // 'point' | 'polygon' | 'multipolygon'
  let currentCount = 0;   // number of shapes, for multipolygon labeling

  function fmt(n, digits = 1) { return Number(n).toFixed(digits); }

  /* ---------------------------------------------------------- AOI panel */
  function showAOIEmpty() {
    document.getElementById("aoi-empty").style.display = "";
    document.getElementById("aoi-content").style.display = "none";
    document.getElementById("ai-section").style.display = "none";
    document.getElementById("defo-section").style.display = "none";
    document.getElementById("temporal-section").style.display = "none";
    currentFeature = null; currentStats = null; currentType = null; currentCount = 0;
  }

  function renderPointPanel(detail) {
    currentType = "point"; currentFeature = null; currentStats = null;
    document.getElementById("aoi-empty").style.display = "none";
    document.getElementById("aoi-content").style.display = "";
    document.getElementById("ai-section").style.display = "none";
    document.getElementById("temporal-section").style.display = "none";
    document.getElementById("defo-section").style.display = "none";

    const a = detail.analysis;
    document.getElementById("aoi-meta").innerHTML = `
      <div class="k">Geometry</div><div class="v">Point</div>
      <div class="k">Latitude</div><div class="v">${a.lat}</div>
      <div class="k">Longitude</div><div class="v">${a.lng}</div>
      <div class="k">Zone</div><div class="v">${a.changeZone ? "Change zone" : "Stable"}</div>`;
    document.getElementById("aoi-stats").innerHTML = `
      <div class="stat-card"><div class="label">NDVI</div><div class="value ndvi">${a.ndvi}</div></div>
      <div class="stat-card"><div class="label">Elevation</div><div class="value">${a.elevation}m</div></div>
      <div class="stat-card"><div class="label">Vegetation</div><div class="value veg">${a.vegetationPct}%</div></div>
      <div class="stat-card"><div class="label">RGB</div><div class="value" style="font-size:12px;">${a.rgb.r},${a.rgb.g},${a.rgb.b}</div></div>`;
    document.getElementById("btn-analyze").style.display = "none";
  }

  function renderPolygonPanel(detail, isMulti) {
    currentType = isMulti ? "multipolygon" : "polygon";
    currentFeature = detail.feature; currentStats = detail.stats;
    if (isMulti && typeof detail.count === "number") currentCount = detail.count;
    document.getElementById("aoi-empty").style.display = "none";
    document.getElementById("aoi-content").style.display = "";
    document.getElementById("btn-analyze").style.display = "";
    document.getElementById("ai-section").style.display = "none";

    const s = detail.stats;
    document.getElementById("aoi-meta").innerHTML = `
      <div class="k">Geometry</div><div class="v">${isMulti ? `MultiPolygon (${currentCount})` : "Polygon"}</div>
      <div class="k">Centroid</div><div class="v">${fmt(s.centroid[0], 4)}, ${fmt(s.centroid[1], 4)}</div>
      <div class="k">Perimeter</div><div class="v">${fmt(s.perimeterKm, 2)} km</div>
      <div class="k">Year</div><div class="v">${Layers.getCurrentYear()}</div>`;
    document.getElementById("aoi-stats").innerHTML = `
      <div class="stat-card"><div class="label">${isMulti ? "Total Area" : "Area"}</div><div class="value">${fmt(s.area.km2, 1)} km²</div></div>
      <div class="stat-card"><div class="label">${isMulti ? "Average NDVI" : "Mean NDVI"}</div><div class="value ndvi">${s.ndvi.mean}</div></div>
      <div class="stat-card"><div class="label">${isMulti ? "Combined Vegetation" : "Vegetation Cover"}</div><div class="value veg">${s.ndvi.vegetationPct}%</div></div>
      <div class="stat-card"><div class="label">Forest Cover</div><div class="value veg">${s.change.forestPctNow}%</div></div>
      <div class="stat-card"><div class="label">${isMulti ? "Total Forest Loss" : "Change"}</div><div class="value alert">${s.change.changePct}%</div></div>
      <div class="stat-card"><div class="label">Min / Max NDVI</div><div class="value" style="font-size:14px;">${s.ndvi.min} / ${s.ndvi.max}</div></div>`;

    renderDeforestationPanel(s);
    renderTemporalPanel(s);
  }

  function renderDeforestationPanel(s) {
    document.getElementById("defo-section").style.display = "";
    document.getElementById("defo-stats").innerHTML = `
      <div class="stat-card"><div class="label">Forest Loss</div><div class="value alert">${fmt(s.forestLossHa, 1)} ha</div></div>
      <div class="stat-card"><div class="label">Forest Remaining</div><div class="value veg">${fmt(s.forestRemainingKm2, 1)} km²</div></div>
      <div class="stat-card"><div class="label">Loss %</div><div class="value alert">${fmt(Math.abs(s.change.changePct), 1)}%</div></div>
      <div class="stat-card"><div class="label">Area</div><div class="value">${fmt(s.area.km2, 1)} km²</div></div>`;
  }

  function renderTemporalPanel(s) {
    document.getElementById("temporal-section").style.display = "";
    const canvas = document.getElementById("ndvi-chart");
    requestAnimationFrame(() => MiniChart.drawNDVILine(canvas, s.ndvi.series, Layers.getCurrentYear()));
    document.getElementById("temporal-stats").innerHTML = `
      <div class="stat-card"><div class="label">Vegetation %</div><div class="value veg">${s.ndvi.vegetationPct}%</div></div>
      <div class="stat-card"><div class="label">Forest Cover %</div><div class="value veg">${s.change.forestPctNow}%</div></div>`;
  }

  /* --------------------------------------------------------- AI analysis */
  const PROC_MESSAGES = [
    "Analyzing selected AOI…", "Processing spatial features…",
    "Calculating temporal change…", "AI analysis complete"
  ];

  function runAIAnalysis() {
    if (!currentFeature || !currentStats) return;
    const section = document.getElementById("ai-section");
    const proc = document.getElementById("ai-processing");
    const result = document.getElementById("ai-result");
    section.style.display = "";
    proc.classList.add("show");
    result.style.display = "none";
    proc.querySelectorAll(".proc-step").forEach(s => s.classList.remove("active", "done"));

    let step = 0;
    const steps = proc.querySelectorAll(".proc-step");
    function advance() {
      if (step > 0) steps[step - 1].classList.replace("active", "done");
      if (step < steps.length) {
        steps[step].classList.add("active");
        step++;
        setTimeout(advance, 520);
      } else {
        proc.classList.remove("show");
        const output = Analysis.analyzeAOI(currentFeature, currentStats);
        document.getElementById("ai-narrative").textContent = output.narrative;
        document.getElementById("ai-findings").innerHTML = output.findings.map(f => `<li>${f}</li>`).join("");
        result.style.display = "";
        UI.toast("AI analysis complete", "veg");
      }
    }
    advance();
  }

  /* ------------------------------------------------------------ events */
  document.addEventListener("aoi:point", (e) => renderPointPanel(e.detail));
  document.addEventListener("aoi:polygon", (e) => renderPolygonPanel(e.detail, false));
  document.addEventListener("aoi:multipolygon", (e) => renderPolygonPanel(e.detail, true));
  document.addEventListener("aoi:cleared", showAOIEmpty);

  document.addEventListener("timeline:year", (e) => {
    if (!currentFeature || currentType === "point") return;
    currentStats = Analysis.calculateAOI(currentFeature, e.detail.year);
    renderPolygonPanel({ feature: currentFeature, stats: currentStats }, currentType === "multipolygon");
  });

  /* --------------------------------------------------------- demo mode */
  async function runDemoMode() {
    UI.toast("Loading demo area…");
    // Turn on the headline layer combination for the demo story
    const state = Layers.getState();
    state.rgb.on = true; state.ndvi.on = true; state.deforestation.on = false;
    document.querySelectorAll("#dataset-chips .chip").forEach(c => c.classList.remove("active"));
    document.querySelector('#dataset-chips .chip[data-dataset="D08"]').classList.add("active");
    await Layers.updateLayers();
    Layers.syncLayerUI();
    Layers.renderLegend();
    await Timeseries.setYearIndex(DEMO_DATA.years.indexOf(2021));
    DrawingTool.loadDemoAOI();
    setTimeout(async () => {
      await Timeseries.setYearIndex(DEMO_DATA.years.indexOf(2025));
      state.deforestation.on = true;
      await Layers.updateLayers();
      Layers.syncLayerUI();
      Layers.renderLegend();
      UI.toast("Demo area loaded — try Play, draw a new shape, or Analyze This Area", "veg");
    }, 900);
  }

  /* --------------------------------------------------------------- boot */
  function boot() {
    if (!document.getElementById("map") || !document.getElementById("geo-lab")) return;
    const map = MapCore.init();
    if (!map) return;

    Layers.init();
    DrawingTool.init(map);
    Timeseries.init();
    Compare.init();
    Upload.init(map);
    UI.initMobileDrawers();
    MapCore.enableInspection(() => Layers.getCurrentYear());

    document.getElementById("btn-reset-view").addEventListener("click", MapCore.resetView);
    document.getElementById("btn-analyze").addEventListener("click", runAIAnalysis);
    document.getElementById("btn-demo-mode").addEventListener("click", runDemoMode);

    document.getElementById("search-go").addEventListener("click", () => {
      const v = document.getElementById("search-input").value.trim();
      if (v) MapCore.searchLocation(v);
    });
    document.getElementById("search-input").addEventListener("keydown", (e) => {
      if (e.key === "Enter") document.getElementById("search-go").click();
    });

    UI.toast("Geospatial Intelligence Lab ready — running on synthetic demo data");
    window.__geoLabMap = map;
    setTimeout(() => map.invalidateSize(true), 350);
  }

  document.addEventListener("DOMContentLoaded", boot);
})();

/* ==========================================================================
   Geospatial Lab — homepage nav sync (geo-lab-init)
   ========================================================================== */
(() => {
  "use strict";

  const section = document.getElementById("geo-lab");
  if (!section) return;

  const nav = section.querySelector(".geo-lab-dataset-nav");
  const chips = document.getElementById("dataset-chips");

  function syncNavFromChips() {
    if (!nav || !chips) return;
    const active = chips.querySelector(".chip.active");
    const id = active?.dataset?.dataset;
    nav.querySelectorAll(".ml-play-tab").forEach((tab) => {
      tab.classList.toggle("is-active", tab.dataset.geoDataset === id);
    });
  }

  if (nav && chips) {
    nav.addEventListener("click", (e) => {
      const tab = e.target.closest("[data-geo-dataset]");
      if (!tab) return;
      const id = tab.dataset.geoDataset;
      const chip = chips.querySelector(`.chip[data-dataset="${id}"]`);
      if (chip) chip.click();
      syncNavFromChips();
    });

    chips.addEventListener("click", (e) => {
      if (e.target.closest(".chip")) {
        setTimeout(syncNavFromChips, 0);
      }
    });
  }

  function fixMapSize() {
    if (window.__geoLabMap) window.__geoLabMap.invalidateSize(true);
  }

  if ("IntersectionObserver" in window) {
    new IntersectionObserver((entries) => {
      if (entries.some((entry) => entry.isIntersecting)) fixMapSize();
    }, { threshold: 0.06 }).observe(section);
  }

  window.addEventListener("resize", fixMapSize);
})();

