function hexToRgb(hex){ const h = hex.replace('#',''); return [parseInt(h.substring(0,2),16), parseInt(h.substring(2,4),16), parseInt(h.substring(4,6),16)]; }
function rgba(hex, a){ const [r,g,b] = hexToRgb(hex.replace('#','')); return `rgba(${r},${g},${b},${a})`; }
function lerpColor(hexA, hexB, t){
  const a = hexToRgb(hexA.replace('#','')), b = hexToRgb(hexB.replace('#',''));
  const r = Math.round(a[0]+(b[0]-a[0])*t), g = Math.round(a[1]+(b[1]-a[1])*t), bl = Math.round(a[2]+(b[2]-a[2])*t);
  return `rgb(${r},${g},${bl})`;
}
function gradFill(context, colorTop, colorBottom){
  const chart = context.chart; const {ctx, chartArea} = chart;
  if(!chartArea) return colorTop;
  const g = ctx.createLinearGradient(0, chartArea.top, 0, chartArea.bottom);
  g.addColorStop(0, colorTop); g.addColorStop(1, colorBottom);
  return g;
}
function animateCount(el, target, opts){
  opts = opts || {};
  const dur = 850, start = performance.now();
  const isFloat = opts.decimals > 0;
  function step(now){
    const p = Math.min(1, (now-start)/dur);
    const eased = 1 - Math.pow(1-p, 3);
    const val = target*eased;
    el.textContent = (opts.prefix||'') + (isFloat ? val.toFixed(opts.decimals) : fmtNum(val)) + (opts.suffix||'');
    if(p<1) requestAnimationFrame(step);
    else el.textContent = (opts.prefix||'') + (isFloat ? target.toFixed(opts.decimals) : fmtNum(target)) + (opts.suffix||'');
  }
  requestAnimationFrame(step);
}
function animateRing(el, valEl, pct, suffix){
  const dur = 1000, start = performance.now();
  function step(now){
    const p = Math.min(1, (now-start)/dur);
    const eased = 1 - Math.pow(1-p,3);
    const v = pct*eased;
    el.style.setProperty('--p', v.toFixed(1));
    if(valEl) valEl.textContent = Math.round(v) + (suffix||'%');
    if(p<1) requestAnimationFrame(step);
    else { el.style.setProperty('--p', pct); if(valEl) valEl.textContent = Math.round(pct)+(suffix||'%'); }
  }
  requestAnimationFrame(step);
}
