/* ============================================================
   SQUARIFIED TREEMAP
   ============================================================ */
function computeTreemap(items, x, y, w, h){
  const total = items.reduce((s,i)=>s+i.value, 0);
  const data = items.map(i => ({...i, area: i.value/total * w * h}));
  const result = [];
  function worst(row, length){
    const sum = row.reduce((a,b)=>a+b.area,0);
    const maxA = Math.max(...row.map(r=>r.area)), minA = Math.min(...row.map(r=>r.area));
    return Math.max((length*length*maxA)/(sum*sum), (sum*sum)/(length*length*minA));
  }
  function layoutRow(row, x, y, w, h, horizontal){
    const sum = row.reduce((a,b)=>a+b.area,0);
    let offset = 0;
    row.forEach(item=>{
      if(horizontal){ const rw = sum ? (item.area/sum)*w : 0; result.push({...item, x:x+offset, y:y, w:rw, h:h}); offset += rw; }
      else { const rh = sum ? (item.area/sum)*h : 0; result.push({...item, x:x, y:y+offset, w:w, h:rh}); offset += rh; }
    });
  }
  let remaining = [...data].sort((a,b)=>b.area-a.area);
  let cx=x, cy=y, cw=w, ch=h;
  while(remaining.length){
    const horizontal = cw >= ch;
    const length = horizontal ? ch : cw;
    let row = [remaining[0]]; remaining = remaining.slice(1);
    while(remaining.length){
      const testRow = [...row, remaining[0]];
      if(row.length===0 || worst(testRow, length) <= worst(row, length)){ row = testRow; remaining = remaining.slice(1); }
      else break;
    }
    const rowSum = row.reduce((a,b)=>a+b.area,0);
    if(horizontal){ const rowH = ch ? rowSum/cw : 0; layoutRow(row, cx, cy, cw, rowH, true); cy += rowH; ch -= rowH; }
    else { const rowW = cw ? rowSum/ch : 0; layoutRow(row, cx, cy, rowW, ch, false); cx += rowW; cw -= rowW; }
  }
  return result;
}

