const floatTip = document.getElementById('floatTip');
function showFloatTip(html, evt){
  floatTip.innerHTML = html;
  floatTip.classList.add('show');
  moveFloatTip(evt);
}
function moveFloatTip(evt){
  const x = evt.clientX, y = evt.clientY;
  const w = floatTip.offsetWidth || 190, h = floatTip.offsetHeight || 80;
  let left = x + 16, top = y - h - 12;
  if(left + w > window.innerWidth - 12) left = x - w - 16;
  if(top < 8) top = y + 16;
  floatTip.style.left = left+'px'; floatTip.style.top = top+'px';
}
function hideFloatTip(){ floatTip.classList.remove('show'); }

/* ============================================================
   SVG FUNNEL FLOW
   ============================================================ */
const FUNNEL_PALETTE = ['#F58220','#ff9a4d','#6b7399','#464f79','#cfa86e','#e06a10'];
function buildFunnelSVG(stages){
  const W = 900, padTop = 10, padBottom = 10, gap = 8;
  const n = stages.length;
  const rowH = (340 - padTop - padBottom - gap*(n-1)) / n;
  const maxW = 620, minW = 140;
  const maxCount = stages[0].count;
  function widthFor(c){ return minW + (maxW-minW) * Math.sqrt(c/maxCount); }
  let svg = `<svg viewBox="0 0 ${W} 340" xmlns="http://www.w3.org/2000/svg">`;
  svg += `<defs>`;
  stages.forEach((st,i)=>{
    const c1 = FUNNEL_PALETTE[i % FUNNEL_PALETTE.length];
    svg += `<linearGradient id="fnGrad${i}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${c1}" stop-opacity="0.98"/>
      <stop offset="100%" stop-color="${c1}" stop-opacity="0.72"/>
    </linearGradient>`;
  });
  svg += `</defs>`;

  stages.forEach((st,i)=>{
    const y = padTop + i*(rowH+gap);
    const topW = widthFor(st.count);
    const nextCount = i < n-1 ? stages[i+1].count : st.count*0.86;
    const botW = widthFor(nextCount);
    const topX = (W - topW)/2, botX = (W - botW)/2;
    const points = `${topX},${y} ${topX+topW},${y} ${botX+botW},${y+rowH} ${botX},${y+rowH}`;
    const prev = i>0 ? stages[i-1].count : null;
    const convFromPrev = prev ? (st.count/prev*100) : 100;
    const dropoff = 100-convFromPrev;
    svg += `<polygon class="fn-seg" data-i="${i}" points="${points}" fill="url(#fnGrad${i})" stroke="rgba(8,11,18,0.5)" stroke-width="1"/>`;
    svg += `<text class="fn-label-name" x="${W/2}" y="${y+rowH/2-6}" text-anchor="middle">${st.name}</text>`;
    svg += `<text class="fn-label-count" x="${W/2}" y="${y+rowH/2+12}" text-anchor="middle">${fmtNum(st.count)} users</text>`;
    if(i>0){
      const annoColor = convFromPrev>=60 ? '#34D399' : (convFromPrev>=35 ? '#FBBF24' : '#FB7185');
      svg += `<text class="fn-annot" x="${topX+topW+18}" y="${y+rowH/2-4}" fill="${annoColor}">▲ ${convFromPrev.toFixed(0)}% conv</text>`;
      svg += `<text class="fn-annot" x="${topX+topW+18}" y="${y+rowH/2+13}" fill="#8B95A7">▼ ${dropoff.toFixed(0)}% drop-off</text>`;
    }
  });
  svg += `</svg>`;
  return svg;
}

