/* ==========================================================================
   Scroll reveal animations — homepage + inner pages
   ========================================================================== */
/* Viewport scroll reveals only — no smooth anchor hijacking (multi-page site). */
(() => {
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  if (reduceMotion || !('IntersectionObserver' in window)) return;

  const skipClosest = '.hero-lab-section, .cvp-hero, .cvp-lab-section, .offices-globe-section, .offices-locations-section, #offices, .cv-showcase-section, #cv-showcase, .geo-lab-section, .ai-sim-section, #floatingHeader, #mobileNavMenu, #aiChatbotWidget, .marquee-container, .owl-item, .ai-tools-connections-svg, .ai-tool-node-card';

  const mark = (el, variant, delay) => {
    if (!el || el.dataset.srInit) return;
    if (el.closest(skipClosest)) return;
    if (el.classList.contains('hidden')) return;
    if (el.closest('.sticky')) {
      variant = 'sr-in';
    }
    el.dataset.srInit = '1';
    el.classList.add('sr-reveal', variant);
    if (delay) el.style.setProperty('--sr-delay', `${delay}ms`);
  };

  const stagger = (nodeList, variant, step) => {
    const items = Array.from(nodeList);
    items.forEach((el, i) => mark(el, variant, Math.min(i * step, 280)));
  };

  document.querySelectorAll('section:not(.hero-lab-section) .text-center.max-w-3xl, section:not(.hero-lab-section) .text-center.max-w-4xl').forEach((el) => {
    mark(el, 'sr-up');
  });

  document.querySelectorAll('#techstack .max-w-7xl.text-center, #testimonials .flex.flex-col.md\\:flex-row, #blog .flex.flex-col.md\\:flex-row').forEach((el) => {
    mark(el, 'sr-up');
  });

  mark(document.querySelector('.consult-stage-inner'), 'sr-left');
  mark(document.querySelector('.consult-form-card'), 'sr-right');
  mark(document.querySelector('#services .flex-1.ds-clip'), 'sr-right');
  mark(document.querySelector('.ai-tools-stage-wrapper'), 'sr-in');
  mark(document.querySelector('#testimonialCarousel'), 'sr-in');
  mark(document.querySelector('#blogCarousel'), 'sr-in');
  mark(document.querySelector('footer .max-w-7xl'), 'sr-up');

  document.querySelectorAll('#workflow .lg\\:col-span-5').forEach((el) => mark(el, 'sr-in'));

  stagger(document.querySelectorAll('.bento-card-warm'), 'sr-up', 50);
  stagger(document.querySelectorAll('.svc-grid-card:not(.offices-loc-card)'), 'sr-up', 55);
  stagger(document.querySelectorAll('.faq-accordion-card'), 'sr-up', 45);
  stagger(document.querySelectorAll('.workflow-step-card'), 'sr-up', 80);
  stagger(document.querySelectorAll('.ai-feature-tab-btn'), 'sr-left', 50);
  stagger(document.querySelectorAll('.cvp-card'), 'sr-up', 55);
  stagger(document.querySelectorAll('.cvp-fn'), 'sr-up', 40);
  stagger(document.querySelectorAll('.cvp-step'), 'sr-left', 40);

  document.querySelectorAll('.ai-feature-pane.block').forEach((el) => mark(el, 'sr-in'));

  document.querySelectorAll('section.py-16 .ds-clip:not(.ds-clip-sm)').forEach((el, i) => {
    if (el.closest('#aiChatbotWidget')) return;
    mark(el, 'sr-up', Math.min(i * 55, 220));
  });

  document.querySelectorAll('section:not(.hero-lab-section) img').forEach((img) => {
    if (img.closest('#aiChatbotWidget, #floatingHeader, .ai-tool-node-card, .owl-carousel, footer')) return;
    mark(img, 'sr-img');
  });

  const tidy = (el) => {
    el.classList.remove('sr-reveal', 'sr-up', 'sr-in', 'sr-left', 'sr-right', 'sr-img', 'is-in');
    el.style.removeProperty('--sr-delay');
    delete el.dataset.srInit;
  };

  const io = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      const el = entry.target;
      el.classList.add('is-in');
      io.unobserve(el);

      const onEnd = (event) => {
        if (event.target !== el) return;
        if (event.propertyName !== 'opacity' && event.propertyName !== 'transform') return;
        tidy(el);
        el.removeEventListener('transitionend', onEnd);
      };
      el.addEventListener('transitionend', onEnd);
      window.setTimeout(() => tidy(el), 1100);
    });
  }, {
    root: null,
    rootMargin: '0px 0px -8% 0px',
    threshold: 0.1
  });

  document.querySelectorAll('.sr-reveal').forEach((el) => io.observe(el));
})();

