/* ============================================================================
   CRM Playground — iframe height sync (playgrounds/crm.html)
   ============================================================================ */
(function () {
  var frame = document.getElementById('crmIntelligenceFrame');
  if (!frame) return;

  function measureFrameHeight(doc) {
    var root = doc.getElementById('root');
    if (!root) return 720;

    var card = root.querySelector('[class*="max-w-[1280px]"]');
    var content = root.querySelector('[class*="min-h-[720px]"]');
    var nodes = [content, card, root, doc.documentElement, doc.body];
    var h = 720;

    nodes.forEach(function (el) {
      if (!el) return;
      var rect = el.getBoundingClientRect();
      h = Math.max(h, el.scrollHeight, el.offsetHeight, rect.height);
    });

    return Math.ceil(h + 16);
  }

  function fitFrame() {
    try {
      var doc = frame.contentWindow && frame.contentWindow.document;
      if (!doc || !doc.body) return;

      var root = doc.getElementById('root');
      if (!root || !root.children.length) return;

      var h = measureFrameHeight(doc);
      frame.style.height = h + 'px';

      var stage = frame.closest('.crm-play-stage');
      if (stage) stage.style.minHeight = h + 'px';
    } catch (e) { /* ignore */ }
  }

  function watchFrame() {
    fitFrame();

    try {
      var doc = frame.contentWindow.document;
      var root = doc.getElementById('root');
      if (!root) return;

      if (window.ResizeObserver) {
        new ResizeObserver(fitFrame).observe(root);
        var card = root.querySelector('[class*="max-w-[1280px]"]');
        if (card) new ResizeObserver(fitFrame).observe(card);
      }
      if (window.MutationObserver) {
        new MutationObserver(fitFrame).observe(root, {
          childList: true,
          subtree: true,
          attributes: true
        });
      }
    } catch (e) { /* ignore */ }
  }

  function scheduleFits() {
    [0, 120, 350, 700, 1200, 2000, 3500, 5000].forEach(function (ms) {
      setTimeout(fitFrame, ms);
    });
  }

  frame.addEventListener('load', function () {
    watchFrame();
    scheduleFits();

    var tries = 0;
    var poll = setInterval(function () {
      fitFrame();
      tries += 1;
      if (tries >= 40) clearInterval(poll);
    }, 250);
  });

  window.addEventListener('resize', fitFrame);
})();


