(function () {
  var root = document.getElementById('cvpLab');
  if (!root) return;

  var boxesEl = document.getElementById('cvpLabBoxes');
  var scanEl = document.getElementById('cvpLabScan');
  var runBtn = document.getElementById('cvpLabRun');
  var hitEl = document.getElementById('cvpLabHit');
  var statusEl = document.getElementById('cvpLabStatus');
  var countEl = document.getElementById('cvpLabCount');
  var metaEl = document.getElementById('cvpLabMeta');
  var photoEl = document.getElementById('cvpLabPhoto');
  var tools = root.querySelectorAll('.cvp-lab-tool');
  var inds = document.querySelectorAll('.cvp-lab-ind');
  var indCopy = document.getElementById('cvpLabIndCopy');
  var mode = 'object';
  var timer = null;
  var base = window.DS_ASSET_BASE || 'asset/';

  var modes = {
    face: {
      cap: 'Use case 01 — Recognition',
      title: 'Facial recognition',
      copy: 'To identify people by their faces facial recognition is used in a wide range of applications, such as security, marketing, and social media.',
      meta: 'CAM 02\nRGB · FACE ID\nFRAME 018',
      img: base + 'cv-lab-faces.jpg',
      boxes: [
        { l: 6, t: 26, w: 20, h: 42, label: 'PERSON_A 0.97', conf: '97%' },
        { l: 28, t: 36, w: 22, h: 48, label: 'PERSON_B 0.94', conf: '94%' },
        { l: 44, t: 10, w: 20, h: 44, label: 'PERSON_C 0.96', conf: '96%' },
        { l: 64, t: 16, w: 22, h: 42, label: 'PERSON_D 0.91', conf: '91%' }
      ]
    },
    object: {
      cap: 'Use case 02 — Detection',
      title: 'Object detection',
      copy: 'A wide range of applications uses object detection to identify objects in images or videos, such as self-driving cars, retail, and manufacturing.',
      meta: 'CAM 01\nRGB · DETECT\nFRAME 042',
      img: base + 'cv-lab-traffic.jpg',
      boxes: [
        { l: 28, t: 46, w: 16, h: 16, label: 'TAXI 0.94', conf: '94%' },
        { l: 45, t: 50, w: 8, h: 22, label: 'PERSON 0.91', conf: '91%' },
        { l: 40, t: 16, w: 10, h: 18, label: 'SIGNAL 0.88', conf: '88%' },
        { l: 62, t: 48, w: 20, h: 18, label: 'SUV 0.86', conf: '86%' }
      ]
    },
    scene: {
      cap: 'Use case 03 — Scene',
      title: 'Scene understanding',
      copy: 'To understand the context of a scene. A wide range of applications employs scene understanding, such as robotics, navigation, and augmented reality.',
      meta: 'CAM 03\nRGB · SCENE\nFRAME 074',
      img: base + 'cv-lab-warehouse.jpg',
      boxes: [
        { l: 4, t: 48, w: 46, h: 40, label: 'BIN AISLE', conf: 'inventory' },
        { l: 50, t: 28, w: 44, h: 50, label: 'SHELF GRID', conf: 'layout' },
        { l: 18, t: 4, w: 58, h: 22, label: 'CEILING / LIGHT', conf: 'context' }
      ]
    }
  };

  var industries = {
    health: 'Healthcare — Computer vision can be employed to diagnose diseases, track patient progress, and perform surgery.',
    mfg: 'Manufacturing — Support in niche areas of industry such as product inspection, identifying defects, and guide robots.',
    retail: 'Retail — Computer vision can be used to track inventory, detect fraud, and personalize shopping experiences.',
    transport: 'Transportation — Computer vision can be used to control self-driving cars, monitor traffic, and detect accidents.'
  };

  function setHit(box) {
    if (!hitEl) return;
    if (!box) {
      hitEl.innerHTML = '<span>Select a detection</span><strong>—</strong><em>Confidence</em>';
      return;
    }
    hitEl.innerHTML = '<span>Selected</span><strong>' + box.label + '</strong><em>' + box.conf + '</em>';
  }

  function paintBoxes(show) {
    var data = modes[mode];
    boxesEl.innerHTML = '';
    if (!show) {
      setHit(null);
      countEl.textContent = '0 detections';
      return;
    }
    data.boxes.forEach(function (box, i) {
      var el = document.createElement('button');
      el.type = 'button';
      el.className = 'cvp-lab-box' + (i === 0 ? ' is-on' : '');
      el.style.left = box.l + '%';
      el.style.top = box.t + '%';
      el.style.width = box.w + '%';
      el.style.height = box.h + '%';
      el.innerHTML = '<span>' + box.label + '</span>';
      el.addEventListener('click', function () {
        boxesEl.querySelectorAll('.cvp-lab-box').forEach(function (n) { n.classList.remove('is-on'); });
        el.classList.add('is-on');
        setHit(box);
      });
      boxesEl.appendChild(el);
    });
    countEl.textContent = data.boxes.length + ' detections';
    setHit(data.boxes[0]);
  }

  function runInference() {
    var data = modes[mode];
    if (timer) clearTimeout(timer);
    paintBoxes(false);
    if (scanEl) {
      scanEl.hidden = false;
      scanEl.classList.add('is-active');
    }
    statusEl.textContent = 'Inference running…';
    countEl.textContent = 'scanning';
    timer = setTimeout(function () {
      if (scanEl) {
        scanEl.hidden = true;
        scanEl.classList.remove('is-active');
      }
      paintBoxes(true);
      statusEl.textContent = 'Complete · click a box';
    }, 1100);
  }

  function setMode(next) {
    mode = next;
    var data = modes[mode];
    tools.forEach(function (btn) {
      var on = btn.getAttribute('data-cvp-lab') === mode;
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    document.getElementById('cvpLabCap').textContent = data.cap;
    document.getElementById('cvpLabTitle').textContent = data.title;
    document.getElementById('cvpLabCopy').textContent = data.copy;
    if (metaEl) metaEl.innerHTML = data.meta.replace(/\n/g, '<br>');
    if (photoEl) photoEl.src = data.img;
    runInference();
  }

  tools.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setMode(btn.getAttribute('data-cvp-lab'));
    });
  });

  runBtn.addEventListener('click', runInference);

  inds.forEach(function (btn) {
    btn.addEventListener('click', function () {
      inds.forEach(function (n) { n.classList.remove('is-on'); });
      btn.classList.add('is-on');
      indCopy.textContent = industries[btn.getAttribute('data-cvp-ind')] || '';
    });
  });

  setMode('object');
})();


