(function () {
  var root = document.getElementById('dspHow');
  if (!root) return;

  var steps = Array.prototype.slice.call(root.querySelectorAll('.cvp-step'));
  var pipes = Array.prototype.slice.call(root.querySelectorAll('.cvp-pipe span'));
  var cap = document.getElementById('dspStageCap');
  var title = document.getElementById('dspStageTitle');
  var body = document.getElementById('dspStageBody');
  var media = document.getElementById('dspStageMedia');
  var video = document.getElementById('dspStageVideo');
  var img = document.getElementById('dspStageImg');
  var hud = document.getElementById('dspStageHud');
  var hudRight = document.getElementById('dspStageHudRight');
  var signalTxt = document.getElementById('dspStageSignalTxt');
  var modeEl = document.getElementById('dspStageMode');
  var fxNodes = root.querySelectorAll('.cvp-fx');
  if (!steps.length) return;

  var base = window.DS_ASSET_BASE || 'asset/';
  var data = [
    {
      cap: '01 · Frame',
      title: 'Business Understanding',
      body: 'Collaboration with Business to identify and understand problems and define success metrics.',
      mode: 'FRAME',
      hud: 'DS 01<br>BUSINESS · SCOPE<br>KPI 000',
      hudRight: 'METRICS',
      signal: 'ALIGN · LIVE',
      video: base + 'ds-how-acquire.mp4',
      img: base + 'ds-lab-cx.jpg'
    },
    {
      cap: '02 · Acquire',
      title: 'Data Acquisition',
      body: 'Leverage Data Lake to ingest data: Data Quality Assessment, enrichment, processing.',
      mode: 'ACQUIRE',
      hud: 'DS 01<br>LAKE · INGEST<br>BATCH 012',
      hudRight: 'QUALITY',
      signal: 'INGEST',
      img: base + 'ds-lab-search.jpg'
    },
    {
      cap: '03 · Model',
      title: 'Modeling',
      body: 'A robust analytics layer in the DL allows to exploit Advances Analytics, Machine Learning and Artificial Intelligence to create models from the data.',
      mode: 'MODEL',
      hud: 'DS 01<br>ML · AI<br>EPOCH 042',
      hudRight: 'FIT',
      signal: 'TRAINING',
      img: base + 'ds-lab-model.jpg'
    },
    {
      cap: '04 · Deliver',
      title: 'Deploy',
      body: 'Identify and develop the best tool to deliver the results of the model or analysis: dashboarding tools, data apps, chatbot etc.',
      mode: 'DEPLOY',
      hud: 'DS 01<br>SERVE · LIVE<br>APP 001',
      hudRight: 'SHIP',
      signal: 'LIVE',
      img: base + 'ds-lab-ecom.jpg'
    }
  ];

  function setOn(index) {
    var i = Math.max(0, Math.min(index, data.length - 1));
    var item = data[i];
    steps.forEach(function (el, n) {
      el.classList.toggle('is-on', n === i);
      el.setAttribute('aria-pressed', n === i ? 'true' : 'false');
    });
    pipes.forEach(function (el, n) {
      el.classList.toggle('is-on', n === i);
    });
    fxNodes.forEach(function (el) {
      el.classList.toggle('is-on', el.getAttribute('data-fx') === String(i));
    });
    if (media) media.setAttribute('data-step', String(i));
    if (cap) cap.textContent = item.cap;
    if (title) title.textContent = item.title;
    if (body) body.textContent = item.body;
    if (hud) hud.innerHTML = item.hud;
    if (hudRight) hudRight.textContent = item.hudRight;
    if (signalTxt) signalTxt.textContent = item.signal;
    if (modeEl) modeEl.textContent = item.mode;
    if (item.video && video) {
      if (img) img.hidden = true;
      video.hidden = false;
      if (video.getAttribute('src') !== item.video) video.src = item.video;
      var play = video.play();
      if (play && play.catch) play.catch(function () {});
    } else {
      if (video) {
        video.pause();
        video.hidden = true;
      }
      if (img) {
        img.hidden = false;
        img.src = item.img;
      }
    }
  }

  steps.forEach(function (el, i) {
    el.addEventListener('click', function () { setOn(i); });
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        setOn(i);
      }
    });
  });

  setOn(0);
})();


