/* ==========================================================================
   Product page — Face Filter studio
   ========================================================================== */
(function () {
  var root = document.getElementById('ffStudio');
  if (!root) return;

  var base = window.DS_ASSET_BASE || 'asset/';
  var dropzone = document.getElementById('ffDropzone');
  var dropzoneEmpty = document.getElementById('ffDropzoneEmpty');
  var fileInput = document.getElementById('ffFileInput');
  var sampleBtn = document.getElementById('ffSampleBtn');
  var previewWrap = document.getElementById('ffPreviewWrap');
  var previewImg = document.getElementById('ffPreviewImg');
  var styleBtns = root.querySelectorAll('[data-ff-style]');
  var createBtn = document.getElementById('ffCreateBtn');
  var resultStage = document.getElementById('ffResultStage');
  var resultCanvas = document.getElementById('ffResultCanvas');
  var resultImg = document.getElementById('ffResultImg');
  var resultLoader = document.getElementById('ffResultLoader');
  var resultEmpty = document.getElementById('ffResultEmpty');
  var downloadBtn = document.getElementById('ffDownloadBtn');

  var sourceDataUrl = '';
  var hasImage = false;
  var selectedStyle = '';
  var resultDataUrl = '';
  var busy = false;
  var sampleSrc = base + 'ff-model1.png';
  var FACE_MODEL_URL = 'https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.13/model';
  var faceModelsReady = false;
  var faceModelsLoading = null;
  var cachedFaceMetrics = null;
  var cachedFaceKey = '';
  var cachedFaceNorm = null;
  var overlayDog = null;
  var overlayGlasses = null;
  var overlaysLoading = null;

  function loadOverlayAssets() {
    if (overlayDog && overlayGlasses) return Promise.resolve();
    if (overlaysLoading) return overlaysLoading;
    overlaysLoading = Promise.all([
      fetchToDataUrl(base + 'ff-overlay-dog.png').then(loadImageElement).then(function (img) { overlayDog = img; }),
      fetchToDataUrl(base + 'ff-overlay-glasses.png').then(loadImageElement).then(function (img) { overlayGlasses = img; })
    ]).catch(function () { /* vector fallback used */ });
    return overlaysLoading;
  }

  function loadFaceModels() {
    if (faceModelsReady) return Promise.resolve();
    if (faceModelsLoading) return faceModelsLoading;
    if (typeof faceapi === 'undefined') return Promise.resolve();
    faceModelsLoading = Promise.all([
      faceapi.nets.ssdMobilenetv1.loadFromUri(FACE_MODEL_URL),
      faceapi.nets.tinyFaceDetector.loadFromUri(FACE_MODEL_URL),
      faceapi.nets.faceLandmark68Net.loadFromUri(FACE_MODEL_URL)
    ]).then(function () {
      faceModelsReady = true;
    }).catch(function () {
      faceModelsReady = false;
    }).then(function () {
      return faceModelsReady;
    });
    return faceModelsLoading;
  }

  function fallbackMetrics(w, h) {
    var cx = w * 0.5;
    var eyeY = h * (w >= h ? 0.4 : 0.36);
    var eyeDist = w * 0.28;
    return {
      leftEye: { x: cx - eyeDist * 0.5, y: eyeY },
      rightEye: { x: cx + eyeDist * 0.5, y: eyeY },
      eyeOuterL: { x: cx - eyeDist * 0.72, y: eyeY },
      eyeOuterR: { x: cx + eyeDist * 0.72, y: eyeY },
      nose: { x: cx, y: eyeY + eyeDist * 0.55 },
      noseTop: { x: cx, y: eyeY + eyeDist * 0.25 },
      mouth: { x: cx, y: eyeY + eyeDist * 1.05 },
      browL: { x: cx - eyeDist * 0.55, y: eyeY - eyeDist * 0.28 },
      browR: { x: cx + eyeDist * 0.55, y: eyeY - eyeDist * 0.28 },
      jawL: { x: cx - eyeDist * 0.95, y: eyeY + eyeDist * 1.05 },
      jawR: { x: cx + eyeDist * 0.95, y: eyeY + eyeDist * 1.05 },
      chin: { x: cx, y: eyeY + eyeDist * 1.45 },
      eyeDist: eyeDist,
      faceW: eyeDist * 1.9,
      angle: 0,
      top: eyeY - eyeDist * 0.55
    };
  }

  function normalizeMetrics(m, w, h) {
    function n(p) { return { x: p.x / w, y: p.y / h }; }
    return {
      leftEye: n(m.leftEye),
      rightEye: n(m.rightEye),
      eyeOuterL: n(m.eyeOuterL),
      eyeOuterR: n(m.eyeOuterR),
      nose: n(m.nose),
      noseTop: n(m.noseTop),
      mouth: n(m.mouth),
      browL: n(m.browL),
      browR: n(m.browR),
      jawL: n(m.jawL),
      jawR: n(m.jawR),
      chin: n(m.chin),
      eyeDist: m.eyeDist / w,
      faceW: m.faceW / w,
      angle: m.angle,
      top: m.top / h
    };
  }

  function denormalizeMetrics(nm, w, h) {
    function d(p) { return { x: p.x * w, y: p.y * h }; }
    return {
      leftEye: d(nm.leftEye),
      rightEye: d(nm.rightEye),
      eyeOuterL: d(nm.eyeOuterL),
      eyeOuterR: d(nm.eyeOuterR),
      nose: d(nm.nose),
      noseTop: d(nm.noseTop),
      mouth: d(nm.mouth),
      browL: d(nm.browL),
      browR: d(nm.browR),
      jawL: d(nm.jawL),
      jawR: d(nm.jawR),
      chin: d(nm.chin),
      eyeDist: nm.eyeDist * w,
      faceW: nm.faceW * w,
      angle: nm.angle,
      top: nm.top * h
    };
  }

  function prefetchFaceMetrics(dataUrl) {
    if (!dataUrl) return Promise.resolve();
    return loadFaceModels().then(function () {
      return loadImageElement(dataUrl);
    }).then(function (img) {
      var w = img.naturalWidth;
      var h = img.naturalHeight;
      if (!w || !h) return;
      return detectFaceMetrics(img, w, h);
    }).catch(function () { /* optional */ });
  }

  function landmarksToMetrics(landmarks) {
    var p = landmarks.positions;
    function pt(i) { return { x: p[i].x, y: p[i].y }; }
    function avg(indices) {
      var sx = 0;
      var sy = 0;
      indices.forEach(function (i) {
        sx += p[i].x;
        sy += p[i].y;
      });
      var n = indices.length;
      return { x: sx / n, y: sy / n };
    }
    function dist(a, b) {
      return Math.hypot(a.x - b.x, a.y - b.y);
    }
    var leftEye = avg([36, 37, 38, 39, 40, 41]);
    var rightEye = avg([42, 43, 44, 45, 46, 47]);
    var nose = pt(33);
    var noseTop = pt(27);
    var mouth = avg([48, 51, 54, 57, 62, 66]);
    var browL = pt(17);
    var browR = pt(26);
    var jawL = pt(0);
    var jawR = pt(16);
    var chin = pt(8);
    var eyeDist = dist(leftEye, rightEye);
    return {
      leftEye: leftEye,
      rightEye: rightEye,
      eyeOuterL: pt(36),
      eyeOuterR: pt(45),
      nose: nose,
      noseTop: noseTop,
      mouth: mouth,
      browL: browL,
      browR: browR,
      jawL: jawL,
      jawR: jawR,
      chin: chin,
      eyeDist: eyeDist,
      faceW: dist(jawL, jawR),
      angle: Math.atan2(rightEye.y - leftEye.y, rightEye.x - leftEye.x),
      top: Math.min(browL.y, browR.y) - eyeDist * 0.55
    };
  }

  function detectOnCanvas(source, w, h) {
    var canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    canvas.getContext('2d').drawImage(source, 0, 0, w, h);
    var ssd = new faceapi.SsdMobilenetv1Options({ minConfidence: 0.42 });
    var tiny = new faceapi.TinyFaceDetectorOptions({ inputSize: 416, scoreThreshold: 0.28 });
    return faceapi.detectSingleFace(canvas, ssd).withFaceLandmarks().then(function (result) {
      if (result && result.landmarks) return landmarksToMetrics(result.landmarks);
      return faceapi.detectSingleFace(canvas, tiny).withFaceLandmarks().then(function (result2) {
        if (result2 && result2.landmarks) return landmarksToMetrics(result2.landmarks);
        return null;
      });
    });
  }

  function detectFaceMetrics(source, w, h) {
    if (cachedFaceNorm && cachedFaceKey === (sourceDataUrl || '').slice(0, 120)) {
      return Promise.resolve(denormalizeMetrics(cachedFaceNorm, w, h));
    }
    return loadFaceModels().then(function () {
      if (typeof faceapi === 'undefined' || !faceModelsReady) {
        return fallbackMetrics(w, h);
      }
      return detectOnCanvas(source, w, h).then(function (metrics) {
        if (!metrics) return fallbackMetrics(w, h);
        cachedFaceNorm = normalizeMetrics(metrics, w, h);
        cachedFaceKey = (sourceDataUrl || '').slice(0, 120);
        return metrics;
      }).catch(function () { return fallbackMetrics(w, h); });
    });
  }

  function buildLensPreviews(dataUrl) {
    if (!dataUrl) return Promise.resolve();
    return loadFaceModels().then(function () {
      return loadImageElement(dataUrl);
    }).then(function (img) {
      var pw = 118;
      var ph = 157;
      var scale = Math.min(pw / img.naturalWidth, ph / img.naturalHeight);
      var dw = Math.max(1, Math.round(img.naturalWidth * scale));
      var dh = Math.max(1, Math.round(img.naturalHeight * scale));
      return detectFaceMetrics(img, dw, dh).then(function (metrics) {
        styleBtns.forEach(function (btn) {
          var lensId = btn.getAttribute('data-ff-style');
          var preview = btn.querySelector('.ff-lens-preview');
          var thumb = btn.querySelector('.ff-lens-thumb');
          if (!preview || !thumb || !lensId) return;
          var c = document.createElement('canvas');
          c.width = pw;
          c.height = ph;
          var ctx = c.getContext('2d');
          if (!ctx) return;
          ctx.fillStyle = '#0f152f';
          ctx.fillRect(0, 0, pw, ph);
          var ox = (pw - dw) / 2;
          var oy = (ph - dh) / 2;
          ctx.save();
          ctx.translate(ox, oy);
          applyLens(ctx, img, dw, dh, lensId, metrics);
          ctx.restore();
          thumb.src = c.toDataURL('image/jpeg', 0.84);
          preview.classList.add('has-thumb');
        });
      });
    }).catch(function () { /* previews optional */ });
  }

  function updateCreateBtn() {
    if (!createBtn) return;
    createBtn.disabled = !(hasImage && selectedStyle && !busy);
  }

  function setStyle(styleId) {
    selectedStyle = styleId;
    styleBtns.forEach(function (btn) {
      var on = btn.getAttribute('data-ff-style') === styleId;
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    updateCreateBtn();
  }

  function showPreview(dataUrl) {
    if (!previewWrap || !previewImg) return;
    previewImg.src = dataUrl;
    previewWrap.hidden = false;
    if (dropzoneEmpty) dropzoneEmpty.hidden = true;
    if (dropzone) dropzone.classList.add('has-image');
  }

  function blobToDataUrl(blob) {
    return new Promise(function (resolve, reject) {
      var reader = new FileReader();
      reader.onload = function () { resolve(reader.result); };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  }

  function fetchToDataUrl(url) {
    return fetch(url)
      .then(function (res) { return res.blob(); })
      .then(blobToDataUrl)
      .catch(function () {
        return new Promise(function (resolve, reject) {
          var xhr = new XMLHttpRequest();
          xhr.open('GET', url, true);
          xhr.responseType = 'blob';
          xhr.onload = function () {
            if (xhr.status >= 400) {
              reject(new Error('Asset not found'));
              return;
            }
            blobToDataUrl(xhr.response).then(resolve).catch(reject);
          };
          xhr.onerror = function () { reject(new Error('Asset not found')); };
          xhr.send();
        });
      });
  }

  function loadFromDataUrl(dataUrl) {
    sourceDataUrl = dataUrl;
    cachedFaceMetrics = null;
    cachedFaceKey = '';
    cachedFaceNorm = null;
    return new Promise(function (resolve, reject) {
      if (!previewImg) {
        reject(new Error('Preview missing'));
        return;
      }
      previewImg.onload = function () {
        if (previewImg.src !== dataUrl) return;
        hasImage = true;
        showPreview(dataUrl);
        updateCreateBtn();
        prefetchFaceMetrics(dataUrl);
        resolve();
      };
      previewImg.onerror = function () {
        hasImage = false;
        sourceDataUrl = '';
        updateCreateBtn();
        reject(new Error('Image failed to load'));
      };
      previewImg.src = dataUrl;
    });
  }

  function handleFile(file) {
    if (!file || !file.type || file.type.indexOf('image/') !== 0) return;
    blobToDataUrl(file).then(loadFromDataUrl).catch(function () {
      hasImage = false;
      sourceDataUrl = '';
      updateCreateBtn();
    });
  }

  function loadImageElement(dataUrl) {
    return new Promise(function (resolve, reject) {
      var img = new Image();
      img.onload = function () { resolve(img); };
      img.onerror = reject;
      img.src = dataUrl;
    });
  }

  function drawScaled(ctx, source, w, h) {
    ctx.clearRect(0, 0, w, h);
    ctx.drawImage(source, 0, 0, w, h);
  }

  function drawWithFilter(ctx, img, w, h, filter) {
    ctx.save();
    try {
      ctx.filter = filter || 'none';
      drawScaled(ctx, img, w, h);
    } catch (e) {
      ctx.filter = 'none';
      drawScaled(ctx, img, w, h);
    }
    ctx.filter = 'none';
    ctx.restore();
  }

  function posterize(ctx, w, h, levels) {
    try {
      var data = ctx.getImageData(0, 0, w, h);
      var px = data.data;
      var step = 255 / Math.max(2, levels);
      for (var i = 0; i < px.length; i += 4) {
        px[i] = Math.round(px[i] / step) * step;
        px[i + 1] = Math.round(px[i + 1] / step) * step;
        px[i + 2] = Math.round(px[i + 2] / step) * step;
      }
      ctx.putImageData(data, 0, 0);
    } catch (e) { /* skip if canvas blocked */ }
  }

  function drawCartoonEdges(ctx, w, h) {
    try {
      var src = ctx.getImageData(0, 0, w, h);
    var s = src.data;
    var out = ctx.createImageData(w, h);
    var d = out.data;
    for (var y = 1; y < h - 1; y++) {
      for (var x = 1; x < w - 1; x++) {
        var i = (y * w + x) * 4;
        var iR = ((y - 1) * w + x) * 4;
        var iD = (y * w + (x - 1)) * 4;
        var lum = s[i] * 0.299 + s[i + 1] * 0.587 + s[i + 2] * 0.114;
        var lumR = s[iR] * 0.299 + s[iR + 1] * 0.587 + s[iR + 2] * 0.114;
        var lumD = s[iD] * 0.299 + s[iD + 1] * 0.587 + s[iD + 2] * 0.114;
        var edge = Math.abs(lum - lumR) + Math.abs(lum - lumD);
        var v = edge > 28 ? 20 : 0;
        d[i] = v;
        d[i + 1] = v;
        d[i + 2] = v;
        d[i + 3] = edge > 28 ? 180 : 0;
      }
    }
    ctx.save();
    ctx.globalCompositeOperation = 'multiply';
    ctx.putImageData(out, 0, 0);
    ctx.restore();
    } catch (e) { /* skip if canvas blocked */ }
  }

  function sampleBilinear(src, w, h, x, y) {
    var x0 = Math.max(0, Math.min(w - 1, Math.floor(x)));
    var y0 = Math.max(0, Math.min(h - 1, Math.floor(y)));
    var x1 = Math.min(w - 1, x0 + 1);
    var y1 = Math.min(h - 1, y0 + 1);
    var tx = x - x0;
    var ty = y - y0;
    function pix(px, py) {
      var i = (py * w + px) * 4;
      return [src[i], src[i + 1], src[i + 2], src[i + 3]];
    }
    var c00 = pix(x0, y0);
    var c10 = pix(x1, y0);
    var c01 = pix(x0, y1);
    var c11 = pix(x1, y1);
    var out = [];
    for (var c = 0; c < 4; c++) {
      out[c] = Math.round(
        c00[c] * (1 - tx) * (1 - ty) +
        c10[c] * tx * (1 - ty) +
        c01[c] * (1 - tx) * ty +
        c11[c] * tx * ty
      );
    }
    return out;
  }

  function samplePixel(src, w, h, x, y) {
    var sx = Math.max(0, Math.min(w - 1, x));
    var sy = Math.max(0, Math.min(h - 1, y));
    var i = (sy * w + sx) * 4;
    return [src[i], src[i + 1], src[i + 2], src[i + 3]];
  }

  function applyBulge(ctx, img, w, h, cx, cy, radius, strength) {
    var cap = 520;
    if (Math.max(w, h) > cap) {
      var scale = cap / Math.max(w, h);
      var sw = Math.max(1, Math.round(w * scale));
      var sh = Math.max(1, Math.round(h * scale));
      var small = document.createElement('canvas');
      small.width = sw;
      small.height = sh;
      var sctx = small.getContext('2d');
      if (!sctx) {
        drawScaled(ctx, img, w, h);
        return;
      }
      sctx.drawImage(img, 0, 0, sw, sh);
      applyBulge(sctx, small, sw, sh, cx * scale, cy * scale, radius * scale, strength);
      drawScaled(ctx, small, w, h);
      return;
    }
    try {
      var temp = document.createElement('canvas');
      temp.width = w;
      temp.height = h;
      var tctx = temp.getContext('2d');
      if (!tctx) {
        drawScaled(ctx, img, w, h);
        return;
      }
      tctx.drawImage(img, 0, 0, w, h);
      var src = tctx.getImageData(0, 0, w, h);
      var dst = ctx.createImageData(w, h);
      var out = dst.data;
      var rad2 = radius * radius;
      for (var y = 0; y < h; y++) {
        for (var x = 0; x < w; x++) {
          var dx = x - cx;
          var dy = y - cy;
          var dist2 = dx * dx + dy * dy;
          var sx = x;
          var sy = y;
          if (dist2 < rad2) {
            var dist = Math.sqrt(dist2);
            var norm = dist / radius;
            var factor = Math.pow(norm, 1 - strength);
            sx = cx + dx * factor;
            sy = cy + dy * factor;
          }
          var c = sampleBilinear(src.data, w, h, sx, sy);
          var o = (y * w + x) * 4;
          out[o] = c[0];
          out[o + 1] = c[1];
          out[o + 2] = c[2];
          out[o + 3] = c[3];
        }
      }
      ctx.putImageData(dst, 0, 0);
    } catch (e) {
      drawScaled(ctx, img, w, h);
    }
  }

  function drawFaceOverlay(ctx, overlay, m, anchorY) {
    if (!overlay || !overlay.naturalWidth) return false;
    var ow = m.faceW * 1.22;
    var oh = overlay.naturalHeight * (ow / overlay.naturalWidth);
    var cx = (m.jawL.x + m.jawR.x) * 0.5;
    ctx.save();
    ctx.translate(cx, m.nose.y);
    ctx.rotate(m.angle);
    ctx.drawImage(overlay, -ow * 0.5, -oh * anchorY, ow, oh);
    ctx.restore();
    return true;
  }

  function drawGlassesOverlay(ctx, overlay, m) {
    if (!overlay || !overlay.naturalWidth) return false;
    var ow = m.eyeDist * 2.45;
    var oh = overlay.naturalHeight * (ow / overlay.naturalWidth);
    var cx = (m.leftEye.x + m.rightEye.x) * 0.5;
    var cy = (m.leftEye.y + m.rightEye.y) * 0.5;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(m.angle);
    ctx.drawImage(overlay, -ow * 0.5, -oh * 0.438, ow, oh);
    ctx.restore();
    return true;
  }

  function drawPuppyEar(ctx, x, y, size, tilt) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(tilt);
    var grad = ctx.createLinearGradient(-size, 0, size, -size * 2);
    grad.addColorStop(0, '#9A6B45');
    grad.addColorStop(0.55, '#7A5235');
    grad.addColorStop(1, '#4E3424');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(0, size * 0.12);
    ctx.bezierCurveTo(-size * 0.95, -size * 0.08, -size * 0.88, -size * 1.62, -size * 0.12, -size * 1.92);
    ctx.bezierCurveTo(size * 0.58, -size * 1.48, size * 0.78, -size * 0.48, 0, size * 0.12);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(196, 149, 106, 0.88)';
    ctx.beginPath();
    ctx.moveTo(0, size * 0.08);
    ctx.bezierCurveTo(-size * 0.42, -size * 0.02, -size * 0.38, -size * 1.05, -size * 0.08, -size * 1.22);
    ctx.bezierCurveTo(size * 0.24, -size * 0.92, size * 0.32, -size * 0.32, 0, size * 0.08);
    ctx.fill();
    ctx.restore();
  }

  function drawPuppyNose(ctx, m) {
    var s = m.eyeDist * 0.24;
    var nx = m.nose.x;
    var ny = m.nose.y + m.eyeDist * 0.02;
    ctx.save();
    ctx.translate(nx, ny);
    ctx.rotate(m.angle);
    ctx.fillStyle = '#141414';
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.42);
    ctx.bezierCurveTo(s * 0.55, -s * 0.38, s * 0.55, s * 0.32, 0, s * 0.42);
    ctx.bezierCurveTo(-s * 0.55, s * 0.32, -s * 0.55, -s * 0.38, 0, -s * 0.42);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    ctx.beginPath();
    ctx.ellipse(-s * 0.12, -s * 0.12, s * 0.08, s * 0.05, -0.35, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.ellipse(-s * 0.13, s * 0.05, s * 0.06, s * 0.08, 0, 0, Math.PI * 2);
    ctx.ellipse(s * 0.13, s * 0.05, s * 0.06, s * 0.08, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#ec4899';
    ctx.beginPath();
    ctx.ellipse(0, s * 0.62, s * 0.2, s * 0.14, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function drawWhiskers(ctx, m) {
    ctx.save();
    ctx.strokeStyle = 'rgba(255,255,255,0.55)';
    ctx.lineWidth = Math.max(1, m.eyeDist * 0.012);
    ctx.lineCap = 'round';
    var baseY = m.nose.y + m.eyeDist * 0.12;
    [[-1, 0.08], [-1, 0.18], [1, 0.08], [1, 0.18]].forEach(function (pair) {
      var dir = pair[0];
      var lift = pair[1];
      ctx.beginPath();
      ctx.moveTo(m.nose.x + dir * m.eyeDist * 0.08, baseY);
      ctx.lineTo(m.nose.x + dir * m.eyeDist * 0.38, baseY - m.eyeDist * lift);
      ctx.stroke();
    });
    ctx.restore();
  }

  function drawStylishGlasses(ctx, m) {
    var r = m.eyeDist * 0.17;
    var lw = Math.max(2, m.eyeDist * 0.024);
    ctx.save();
    ctx.translate((m.leftEye.x + m.rightEye.x) * 0.5, (m.leftEye.y + m.rightEye.y) * 0.5);
    ctx.rotate(m.angle);
    ctx.translate(-(m.leftEye.x + m.rightEye.x) * 0.5, -(m.leftEye.y + m.rightEye.y) * 0.5);
    ctx.strokeStyle = '#111';
    ctx.fillStyle = 'rgba(0,0,0,0.05)';
    ctx.lineWidth = lw;
    ctx.lineCap = 'round';
    [m.leftEye, m.rightEye].forEach(function (eye) {
      ctx.beginPath();
      ctx.arc(eye.x, eye.y, r, 0, Math.PI * 2);
      ctx.stroke();
      ctx.fill();
    });
    ctx.beginPath();
    ctx.moveTo(m.leftEye.x + r, m.leftEye.y);
    ctx.lineTo(m.rightEye.x - r, m.rightEye.y);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(m.leftEye.x - r, m.leftEye.y);
    ctx.lineTo(m.eyeOuterL.x - m.eyeDist * 0.08, m.leftEye.y - m.eyeDist * 0.02);
    ctx.moveTo(m.rightEye.x + r, m.rightEye.y);
    ctx.lineTo(m.eyeOuterR.x + m.eyeDist * 0.08, m.rightEye.y - m.eyeDist * 0.02);
    ctx.stroke();
    ctx.restore();
  }

  function drawDogEarsAndNose(ctx, m) {
    var earSize = m.eyeDist * 0.48;
    var earY = Math.min(m.browL.y, m.browR.y) - m.eyeDist * 0.22;
    drawPuppyEar(ctx, m.browL.x, earY, earSize, -0.48 + m.angle);
    drawPuppyEar(ctx, m.browR.x, earY, earSize, 0.48 + m.angle);
    drawPuppyNose(ctx, m);
    drawWhiskers(ctx, m);
  }

  function drawDollEnhance(ctx, m) {
    ctx.save();
    [m.leftEye, m.rightEye].forEach(function (eye) {
      ctx.globalCompositeOperation = 'screen';
      ctx.fillStyle = 'rgba(255,255,255,0.32)';
      ctx.beginPath();
      ctx.ellipse(eye.x, eye.y - m.eyeDist * 0.02, m.eyeDist * 0.15, m.eyeDist * 0.1, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.55)';
      ctx.beginPath();
      ctx.ellipse(eye.x - m.eyeDist * 0.04, eye.y - m.eyeDist * 0.04, m.eyeDist * 0.035, m.eyeDist * 0.022, 0, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 0.28;
    ctx.fillStyle = '#f472b6';
    ctx.beginPath();
    ctx.ellipse(m.mouth.x, m.mouth.y, m.eyeDist * 0.24, m.eyeDist * 0.09, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 0.16;
    ctx.fillStyle = '#fb7185';
    ctx.beginPath();
    ctx.ellipse(m.jawL.x + m.faceW * 0.18, m.mouth.y + m.eyeDist * 0.08, m.eyeDist * 0.1, m.eyeDist * 0.06, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.ellipse(m.jawR.x - m.faceW * 0.18, m.mouth.y + m.eyeDist * 0.08, m.eyeDist * 0.1, m.eyeDist * 0.06, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function applyImagineLens(ctx, img, w, h) {
    drawWithFilter(ctx, img, w, h, 'saturate(1.7) contrast(1.32) brightness(1.05) blur(0.3px)');
    posterize(ctx, w, h, 5);
    drawCartoonEdges(ctx, w, h);
    ctx.save();
    ctx.globalCompositeOperation = 'soft-light';
    ctx.globalAlpha = 0.22;
    ctx.fillStyle = '#fcd34d';
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
  }

  function applyDollStyle(ctx, img, w, h, m) {
    drawWithFilter(ctx, img, w, h, 'blur(2.2px) saturate(1.48) contrast(0.88) brightness(1.14)');
    ctx.save();
    ctx.globalCompositeOperation = 'soft-light';
    ctx.globalAlpha = 0.35;
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.ellipse((m.jawL.x + m.jawR.x) * 0.5, (m.nose.y + m.chin.y) * 0.5, m.faceW * 0.42, m.eyeDist * 1.1, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    drawDollEnhance(ctx, m);
  }

  function applyDogLens(ctx, img, w, h, m) {
    drawScaled(ctx, img, w, h);
    drawDogEarsAndNose(ctx, m);
  }

  function applyDogGlasses(ctx, img, w, h, m) {
    drawScaled(ctx, img, w, h);
    drawDogEarsAndNose(ctx, m);
    drawStylishGlasses(ctx, m);
  }

  function applyClassic05(ctx, img, w, h, m) {
    applyBulge(ctx, img, w, h, m.nose.x, m.nose.y + m.eyeDist * 0.04, m.eyeDist * 1.05, 0.68);
  }

  function applyA2Beauty(ctx, img, w, h, m) {
    drawWithFilter(ctx, img, w, h, 'blur(1.1px) saturate(1.32) contrast(1.14) brightness(1.1)');
    ctx.save();
    ctx.globalCompositeOperation = 'soft-light';
    ctx.globalAlpha = 0.18;
    ctx.fillStyle = '#F58220';
    ctx.fillRect(0, 0, w, h);
    ctx.globalCompositeOperation = 'source-over';
    [m.leftEye, m.rightEye].forEach(function (eye) {
      ctx.globalAlpha = 0.42;
      var g = ctx.createRadialGradient(eye.x, eye.y, 0, eye.x, eye.y, m.eyeDist * 0.12);
      g.addColorStop(0, 'rgba(255,255,255,0.85)');
      g.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(eye.x, eye.y, m.eyeDist * 0.12, 0, Math.PI * 2);
      ctx.fill();
    });
    var vig = ctx.createRadialGradient(m.nose.x, m.nose.y, m.eyeDist * 0.15, m.nose.x, m.nose.y, m.eyeDist * 1.55);
    vig.addColorStop(0, 'rgba(0,0,0,0)');
    vig.addColorStop(1, 'rgba(15,21,47,0.28)');
    ctx.globalAlpha = 1;
    ctx.fillStyle = vig;
    ctx.fillRect(0, 0, w, h);
    ctx.restore();
  }

  function applyOldYoung(ctx, img, w, h, m) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, 0, w * 0.5, h);
    ctx.clip();
    drawWithFilter(ctx, img, w, h, 'sepia(0.62) saturate(0.58) contrast(1.14) brightness(0.86) grayscale(0.22)');
    ctx.strokeStyle = 'rgba(60,40,20,0.15)';
    ctx.lineWidth = 1;
    for (var ln = 0; ln < 12; ln++) {
      ctx.beginPath();
      ctx.moveTo(m.leftEye.x - m.eyeDist * 0.2, m.leftEye.y + ln * 2);
      ctx.lineTo(m.leftEye.x + m.eyeDist * 0.15, m.leftEye.y + ln * 2 + 4);
      ctx.stroke();
    }
    ctx.restore();

    ctx.save();
    ctx.beginPath();
    ctx.rect(w * 0.5, 0, w * 0.5, h);
    ctx.clip();
    drawWithFilter(ctx, img, w, h, 'brightness(1.16) saturate(1.28) contrast(1.05) blur(0.5px)');
    ctx.restore();

    ctx.save();
    ctx.strokeStyle = 'rgba(255,255,255,0.8)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(w * 0.5, 0);
    ctx.lineTo(w * 0.5, h);
    ctx.stroke();
    ctx.restore();
  }

  function applyBigMouth(ctx, img, w, h, m) {
    drawScaled(ctx, img, w, h);
    var snapshot = document.createElement('canvas');
    snapshot.width = w;
    snapshot.height = h;
    snapshot.getContext('2d').drawImage(ctx.canvas, 0, 0);
    applyBulge(ctx, snapshot, w, h, m.mouth.x, m.mouth.y + m.eyeDist * 0.06, m.eyeDist * 0.72, 0.78);
  }

  function applyLens(ctx, img, w, h, lensId, metrics) {
    var m = metrics || fallbackMetrics(w, h);
    switch (lensId) {
      case 'imagine-lens': applyImagineLens(ctx, img, w, h); break;
      case 'doll-style': applyDollStyle(ctx, img, w, h, m); break;
      case 'dog-lens': applyDogLens(ctx, img, w, h, m); break;
      case 'dog-glasses': applyDogGlasses(ctx, img, w, h, m); break;
      case 'classic-05': applyClassic05(ctx, img, w, h, m); break;
      case 'a2-beauty': applyA2Beauty(ctx, img, w, h, m); break;
      case 'old-young': applyOldYoung(ctx, img, w, h, m); break;
      case 'big-mouth': applyBigMouth(ctx, img, w, h, m); break;
      default: drawScaled(ctx, img, w, h);
    }
  }

  function renderFiltered() {
    if (!resultCanvas || !sourceDataUrl || !selectedStyle) {
      return Promise.reject(new Error('Source not ready'));
    }
    return loadFaceModels().then(function () {
      return loadImageElement(sourceDataUrl);
    }).then(function (img) {
      var max = 900;
      var w = img.naturalWidth;
      var h = img.naturalHeight;
      if (!w || !h) throw new Error('Invalid image dimensions');
      var ratio = Math.min(1, max / Math.max(w, h));
      w = Math.max(1, Math.round(w * ratio));
      h = Math.max(1, Math.round(h * ratio));
      resultCanvas.width = w;
      resultCanvas.height = h;
      var ctx = resultCanvas.getContext('2d');
      if (!ctx) throw new Error('Canvas not supported');
      return detectFaceMetrics(img, w, h).then(function (metrics) {
        try {
          applyLens(ctx, img, w, h, selectedStyle, metrics);
        } catch (e) {
          drawScaled(ctx, img, w, h);
        }
        var dataUrl;
        try {
          dataUrl = resultCanvas.toDataURL('image/jpeg', 0.92);
        } catch (e2) {
          throw new Error('Canvas export blocked');
        }
        if (!dataUrl || dataUrl.indexOf('data:image') !== 0) {
          throw new Error('Empty render output');
        }
        return dataUrl;
      });
    });
  }

  function showResult(dataUrl) {
    resultDataUrl = dataUrl;
    if (resultEmpty) resultEmpty.hidden = true;
    if (resultCanvas) resultCanvas.hidden = true;
    if (resultImg) {
      resultImg.src = dataUrl;
      resultImg.hidden = false;
    }
    if (downloadBtn) downloadBtn.hidden = false;
  }

  function showRenderError() {
    if (resultEmpty) {
      resultEmpty.hidden = false;
      resultEmpty.querySelector('p').textContent = 'Could not apply filter. Try another portrait.';
    }
    if (resultImg) resultImg.hidden = true;
    if (downloadBtn) downloadBtn.hidden = true;
  }

  function setBusy(on) {
    busy = on;
    if (createBtn) createBtn.classList.toggle('is-busy', on);
    if (resultLoader) resultLoader.hidden = !on;
    if (on) {
      if (resultEmpty) resultEmpty.hidden = true;
      if (resultImg) resultImg.hidden = true;
    }
    updateCreateBtn();
  }

  if (dropzone && fileInput) {
    dropzone.addEventListener('click', function () { fileInput.click(); });
    dropzone.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        fileInput.click();
      }
    });
    fileInput.addEventListener('change', function () {
      if (fileInput.files && fileInput.files[0]) handleFile(fileInput.files[0]);
    });
    ['dragenter', 'dragover'].forEach(function (evt) {
      dropzone.addEventListener(evt, function (e) {
        e.preventDefault();
        dropzone.classList.add('is-drag');
      });
    });
    ['dragleave', 'drop'].forEach(function (evt) {
      dropzone.addEventListener(evt, function (e) {
        e.preventDefault();
        dropzone.classList.remove('is-drag');
      });
    });
    dropzone.addEventListener('drop', function (e) {
      var file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
      handleFile(file);
    });
  }

  if (sampleBtn) {
    sampleBtn.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      fetchToDataUrl(sampleSrc).then(loadFromDataUrl).catch(function () {
        window.alert('Could not load sample portrait. Please upload your own.');
      });
    });
  }

  styleBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setStyle(btn.getAttribute('data-ff-style') || '');
    });
  });

  if (createBtn) {
    createBtn.addEventListener('click', function () {
      if (!hasImage || !selectedStyle || busy) return;
      setBusy(true);
      if (resultStage && resultStage.scrollIntoView) {
        resultStage.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
      window.setTimeout(function () {
        renderFiltered()
          .then(showResult)
          .catch(function () { showRenderError(); })
          .then(function () { setBusy(false); });
      }, 1800);
    });
  }

  if (downloadBtn) {
    downloadBtn.addEventListener('click', function () {
      if (!resultDataUrl) return;
      var link = document.createElement('a');
      link.href = resultDataUrl;
      link.download = 'face-filter-' + selectedStyle + '.jpg';
      link.click();
    });
  }

  updateCreateBtn();
  loadFaceModels();
})();

/* ==========================================================================
   Product page — Deep Fake demo
   ========================================================================== */
(function () {
  var root = document.getElementById('dfDemo');
  if (!root) return;

  var base = window.DS_ASSET_BASE || 'asset/';
  var outputs = [
    [base + 'df-output1-1.png', base + 'df-output1-2.png', base + 'df-output1-3.png'],
    [base + 'df-output2-1.png', base + 'df-output2-2.png', base + 'df-output2-3.png']
  ];
  var model = 0;
  var person = 0;
  var modelBtns = root.querySelectorAll('[data-df-model]');
  var personBtns = root.querySelectorAll('[data-df-person]');
  var img = document.getElementById('dfOutputImg');
  var stage = document.getElementById('dfOutputStage');
  var loader = document.getElementById('dfLoader');
  var timer;

  function setActive(btns, attr, val) {
    btns.forEach(function (btn) {
      var on = Number(btn.getAttribute(attr)) === val;
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
  }

  function showOutput() {
    if (!img) return;
    img.src = outputs[model][person];
  }

  function runLoader(cb) {
    if (timer) clearTimeout(timer);
    if (stage) stage.classList.add('is-loading');
    if (loader) loader.hidden = false;
    if (img) img.style.visibility = 'hidden';
    timer = setTimeout(function () {
      if (stage) stage.classList.remove('is-loading');
      if (loader) loader.hidden = true;
      if (img) img.style.visibility = '';
      cb();
    }, 1500);
  }

  modelBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var next = Number(btn.getAttribute('data-df-model'));
      if (next === model) return;
      model = next;
      setActive(modelBtns, 'data-df-model', model);
      runLoader(showOutput);
    });
  });

  personBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var next = Number(btn.getAttribute('data-df-person'));
      if (next === person) return;
      person = next;
      setActive(personBtns, 'data-df-person', person);
      runLoader(showOutput);
    });
  });

  runLoader(showOutput);
})();

/* ==========================================================================
   Product page — Deep Fake studio
   ========================================================================== */
(function () {
  var root = document.getElementById('dfStudio');
  if (!root) return;

  var base = window.DS_ASSET_BASE || 'asset/';
  var personSrc = [base + 'df-person1.png', base + 'df-person2.png', base + 'df-person3.png'];
  var modelSrc = [base + 'df-model1.png', base + 'df-model2.png'];
  var outputs = [
    [base + 'df-output1-1.png', base + 'df-output1-2.png', base + 'df-output1-3.png'],
    [base + 'df-output2-1.png', base + 'df-output2-2.png', base + 'df-output2-3.png']
  ];
  var FACE_MODEL_URL = 'https://cdn.jsdelivr.net/npm/@vladmandic/face-api@1.7.13/model';

  var dropzone = document.getElementById('dfDropzone');
  var dropzoneEmpty = document.getElementById('dfDropzoneEmpty');
  var fileInput = document.getElementById('dfFileInput');
  var previewWrap = document.getElementById('dfPreviewWrap');
  var previewImg = document.getElementById('dfPreviewImg');
  var targetPersonBtns = root.querySelectorAll('[data-df-target-person]');
  var swapBtn = document.getElementById('dfSwapBtn');
  var resultStage = document.getElementById('dfResultStage');
  var resultCanvas = document.getElementById('dfResultCanvas');
  var resultImg = document.getElementById('dfResultImg');
  var resultLoader = document.getElementById('dfResultLoader');
  var resultEmpty = document.getElementById('dfResultEmpty');
  var downloadBtn = document.getElementById('dfDownloadBtn');

  var targetPerson = 0;
  var customSourceUrl = '';
  var resultDataUrl = '';
  var swapTimer = null;
  var busy = false;
  var faceModelsReady = false;
  var faceModelsLoading = null;

  function fetchToDataUrl(url) {
    return fetch(url).then(function (r) {
      if (!r.ok) throw new Error('fetch failed');
      return r.blob();
    }).then(function (blob) {
      return new Promise(function (resolve, reject) {
        var reader = new FileReader();
        reader.onload = function () { resolve(reader.result); };
        reader.onerror = reject;
        reader.readAsDataURL(blob);
      });
    });
  }

  function loadImageElement(src) {
    return new Promise(function (resolve, reject) {
      var img = new Image();
      img.onload = function () {
        if (img.naturalWidth && img.naturalHeight) resolve(img);
        else reject(new Error('empty image'));
      };
      img.onerror = function () { reject(new Error('image load failed')); };
      img.src = src;
    });
  }

  function blobToDataUrl(blob) {
    return new Promise(function (resolve, reject) {
      var reader = new FileReader();
      reader.onload = function () { resolve(reader.result); };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  }

  var assetDataUrls = {};

  function resolveUrl(relative) {
    try {
      return new URL(relative, window.location.href).href;
    } catch (e) {
      return relative;
    }
  }

  function cacheAssetDataUrl(relative) {
    if (assetDataUrls[relative]) return Promise.resolve(assetDataUrls[relative]);
    var abs = resolveUrl(relative);
    return fetch(abs).then(function (r) {
      if (!r.ok) throw new Error('fetch failed');
      return r.blob();
    }).then(blobToDataUrl).then(function (dataUrl) {
      assetDataUrls[relative] = dataUrl;
      return dataUrl;
    }).catch(function () {
      return new Promise(function (resolve, reject) {
        var img = new Image();
        img.onload = function () {
          var c = document.createElement('canvas');
          c.width = img.naturalWidth;
          c.height = img.naturalHeight;
          c.getContext('2d').drawImage(img, 0, 0);
          try {
            assetDataUrls[relative] = c.toDataURL('image/png');
            resolve(assetDataUrls[relative]);
          } catch (err) {
            assetDataUrls[relative] = abs;
            resolve(abs);
          }
        };
        img.onerror = function () { reject(new Error('asset load failed')); };
        img.src = abs;
      });
    });
  }

  function loadImageFromSrc(src) {
    if (!src) return Promise.reject(new Error('missing src'));
    if (src.indexOf('data:') === 0 || src.indexOf('blob:') === 0) {
      return loadImageElement(src);
    }
    if (assetDataUrls[src]) return loadImageElement(assetDataUrls[src]);
    return cacheAssetDataUrl(src).then(loadImageElement);
  }

  function getTargetImage(idx) {
    var modelUrl = getModelTarget(idx);
    if (assetDataUrls[modelUrl]) {
      return loadImageElement(assetDataUrls[modelUrl]);
    }
    return cacheAssetDataUrl(modelUrl).then(loadImageElement).catch(function () {
      return cacheAssetDataUrl(modelSrc[0]).then(loadImageElement);
    });
  }

  function getSourceImage() {
    if (!customSourceUrl) return Promise.reject(new Error('no upload'));
    return loadImageElement(customSourceUrl);
  }

  function withTimeout(promise, ms) {
    return Promise.race([
      promise,
      new Promise(function (_, reject) {
        setTimeout(function () { reject(new Error('timeout')); }, ms);
      })
    ]);
  }

  function loadFaceModels() {
    if (faceModelsReady) return Promise.resolve(true);
    if (faceModelsLoading) return faceModelsLoading;
    if (typeof faceapi === 'undefined') return Promise.resolve(false);
    faceModelsLoading = withTimeout(
      Promise.all([
        faceapi.nets.ssdMobilenetv1.loadFromUri(FACE_MODEL_URL),
        faceapi.nets.tinyFaceDetector.loadFromUri(FACE_MODEL_URL),
        faceapi.nets.faceLandmark68Net.loadFromUri(FACE_MODEL_URL)
      ]).then(function () {
        faceModelsReady = true;
        return true;
      }),
      6000
    ).catch(function () {
      faceModelsReady = false;
      return false;
    });
    return faceModelsLoading;
  }

  function setActive(btns, attr, val) {
    btns.forEach(function (btn) {
      var on = Number(btn.getAttribute(attr)) === val;
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
  }

  function setBusy(on) {
    busy = on;
    updateSwapBtn();
    if (resultLoader) resultLoader.hidden = !on;
    if (on) {
      if (resultEmpty) resultEmpty.hidden = true;
      if (resultImg) resultImg.hidden = true;
      if (resultCanvas) resultCanvas.hidden = true;
    }
  }

  function fallbackMetrics(w, h) {
    var cx = w * 0.5;
    var eyeY = h * (w >= h ? 0.4 : 0.36);
    var eyeDist = w * 0.28;
    return {
      leftEye: { x: cx - eyeDist * 0.5, y: eyeY },
      rightEye: { x: cx + eyeDist * 0.5, y: eyeY },
      jawL: { x: cx - eyeDist * 0.95, y: eyeY + eyeDist * 1.05 },
      jawR: { x: cx + eyeDist * 0.95, y: eyeY + eyeDist * 1.05 },
      chin: { x: cx, y: eyeY + eyeDist * 1.45 },
      browL: { x: cx - eyeDist * 0.55, y: eyeY - eyeDist * 0.28 },
      browR: { x: cx + eyeDist * 0.55, y: eyeY - eyeDist * 0.28 },
      eyeDist: eyeDist,
      faceW: eyeDist * 1.9,
      angle: 0,
      top: eyeY - eyeDist * 0.55,
      bottom: eyeY + eyeDist * 1.45
    };
  }

  function getModelTarget(idx) {
    return modelSrc[idx === 2 ? 1 : 0];
  }

  function getTargetScene(idx) {
    return getModelTarget(idx);
  }

  function stripNearWhiteAlpha(ctx, w, h, threshold, faceCx, faceCy, faceR) {
    var imgData = ctx.getImageData(0, 0, w, h);
    var d = imgData.data;
    var px;
    var py;
    var i;
    for (i = 0; i < d.length; i += 4) {
      px = (i / 4) % w;
      py = Math.floor(i / 4 / w);
      var r = d[i];
      var g = d[i + 1];
      var b = d[i + 2];
      var lum = (r + g + b) / 3;
      var dist = Math.hypot(px - faceCx, py - faceCy);
      var edge = Math.max(0, dist - faceR * 0.72) / Math.max(faceR * 0.55, 1);
      var whiteness = Math.max(0, lum - (threshold - 35)) / 45;
      if (lum > threshold && r > threshold - 18 && g > threshold - 18 && b > threshold - 18 && dist > faceR * 0.62) {
        d[i + 3] = 0;
      } else if (whiteness > 0 || edge > 0) {
        var fade = Math.min(1, whiteness * 0.85 + edge * 0.95);
        d[i + 3] = Math.round(d[i + 3] * (1 - fade));
      }
    }
    ctx.putImageData(imgData, 0, 0);
  }

  function softenAlphaEdges(ctx, w, h) {
    var imgData = ctx.getImageData(0, 0, w, h);
    var src = imgData.data;
    var out = new Uint8ClampedArray(src.length);
    var x;
    var y;
    var i;
    var a;
    for (y = 0; y < h; y++) {
      for (x = 0; x < w; x++) {
        i = (y * w + x) * 4;
        a = 0;
        a += src[i + 3];
        a += x > 0 ? src[i - 1] : src[i + 3];
        a += x < w - 1 ? src[i + 7] : src[i + 3];
        a += y > 0 ? src[i - w * 4 + 3] : src[i + 3];
        a += y < h - 1 ? src[i + w * 4 + 3] : src[i + 3];
        out[i] = src[i];
        out[i + 1] = src[i + 1];
        out[i + 2] = src[i + 2];
        out[i + 3] = Math.round(a / 5);
      }
    }
    ctx.putImageData(new ImageData(out, w, h), 0, 0);
  }

  function extractFacePatch(sourceImg, sm, sFit, sw, sh) {
    var pad = sm.eyeDist * 0.32;
    var cropX = Math.max(0, Math.min(sm.jawL.x, sm.leftEye.x, sm.browL.x) - pad);
    var cropY = Math.max(0, sm.top - pad * 0.35);
    var cropR = Math.min(sFit.w, Math.max(sm.jawR.x, sm.rightEye.x, sm.browR.x) + pad);
    var cropB = Math.min(sFit.h, sm.bottom + pad * 0.45);
    var cropW = Math.max(1, cropR - cropX);
    var cropH = Math.max(1, cropB - cropY);
    var sxNat = cropX * (sw / sFit.w);
    var syNat = cropY * (sh / sFit.h);
    var swNat = cropW * (sw / sFit.w);
    var shNat = cropH * (sh / sFit.h);
    var patch = document.createElement('canvas');
    patch.width = Math.max(1, Math.round(swNat));
    patch.height = Math.max(1, Math.round(shNat));
    var pctx = patch.getContext('2d');
    pctx.drawImage(sourceImg, sxNat, syNat, swNat, shNat, 0, 0, patch.width, patch.height);
    var scaleX = patch.width / cropW;
    var scaleY = patch.height / cropH;
    var faceCx = ((sm.leftEye.x + sm.rightEye.x) * 0.5 - cropX) * scaleX;
    var faceCy = ((sm.leftEye.y + sm.rightEye.y) * 0.5 - cropY) * scaleY;
    var faceR = sm.eyeDist * Math.max(scaleX, scaleY) * 1.05;
    stripNearWhiteAlpha(pctx, patch.width, patch.height, 232, faceCx, faceCy, faceR);
    softenAlphaEdges(pctx, patch.width, patch.height);
    softenAlphaEdges(pctx, patch.width, patch.height);
    return {
      patch: patch,
      cropW: cropW,
      cropH: cropH,
      eyeCenter: {
        x: ((sm.leftEye.x + sm.rightEye.x) * 0.5 - cropX) * scaleX,
        y: ((sm.leftEye.y + sm.rightEye.y) * 0.5 - cropY) * scaleY
      },
      eyeDist: sm.eyeDist * scaleX,
      angle: sm.angle
    };
  }

  function createFeatherMask(w, h, cx, cy, rx, ry, angle) {
    var mask = document.createElement('canvas');
    mask.width = w;
    mask.height = h;
    var mctx = mask.getContext('2d');
    mctx.save();
    mctx.translate(cx, cy);
    mctx.rotate(angle);
    var grad = mctx.createRadialGradient(0, 0, Math.min(rx, ry) * 0.08, 0, 0, Math.max(rx, ry) * 1.08);
    grad.addColorStop(0, 'rgba(255,255,255,1)');
    grad.addColorStop(0.62, 'rgba(255,255,255,0.96)');
    grad.addColorStop(0.8, 'rgba(255,255,255,0.72)');
    grad.addColorStop(0.91, 'rgba(255,255,255,0.32)');
    grad.addColorStop(0.97, 'rgba(255,255,255,0.08)');
    grad.addColorStop(1, 'rgba(255,255,255,0)');
    mctx.fillStyle = grad;
    mctx.beginPath();
    mctx.ellipse(0, 0, rx, ry * 1.02, 0, 0, Math.PI * 2);
    mctx.fill();
    mctx.restore();
    return mask;
  }

  function sampleSkinTone(ctx, cx, cy, radius) {
    var size = Math.max(8, Math.round(radius));
    var x = Math.max(0, Math.min(ctx.canvas.width - size, Math.round(cx - size / 2)));
    var y = Math.max(0, Math.min(ctx.canvas.height - size, Math.round(cy - size / 2)));
    var data = ctx.getImageData(x, y, size, size).data;
    var r = 0;
    var g = 0;
    var b = 0;
    var n = 0;
    var i;
    for (i = 0; i < data.length; i += 4) {
      r += data[i];
      g += data[i + 1];
      b += data[i + 2];
      n++;
    }
    if (!n) return { r: 180, g: 140, b: 120 };
    return { r: r / n, g: g / n, b: b / n };
  }

  function tintFacePatch(patch, tone, amount) {
    var w = patch.width;
    var h = patch.height;
    var tctx = patch.getContext('2d');
    var imgData = tctx.getImageData(0, 0, w, h);
    var d = imgData.data;
    var i;
    var lumTarget = (tone.r + tone.g + tone.b) / 3;
    for (i = 0; i < d.length; i += 4) {
      if (d[i + 3] < 8) continue;
      var lum = (d[i] + d[i + 1] + d[i + 2]) / 3;
      var mix = amount * (0.55 + Math.min(1, lum / 220) * 0.45);
      d[i] = d[i] * (1 - mix) + tone.r * mix;
      d[i + 1] = d[i + 1] * (1 - mix) + tone.g * mix;
      d[i + 2] = d[i + 2] * (1 - mix) + tone.b * mix;
      var lumAfter = (d[i] + d[i + 1] + d[i + 2]) / 3;
      var lumShift = (lumTarget - lumAfter) * 0.12;
      d[i] = Math.max(0, Math.min(255, d[i] + lumShift));
      d[i + 1] = Math.max(0, Math.min(255, d[i + 1] + lumShift));
      d[i + 2] = Math.max(0, Math.min(255, d[i + 2] + lumShift));
    }
    tctx.putImageData(imgData, 0, 0);
  }

  function renderRealisticSwap(sourceImg, targetImg, sm, tm) {
    var tw = targetImg.naturalWidth || targetImg.width;
    var th = targetImg.naturalHeight || targetImg.height;
    var sw = sourceImg.naturalWidth || sourceImg.width;
    var sh = sourceImg.naturalHeight || sourceImg.height;
    if (!tw || !th || !sw || !sh) throw new Error('bad image');

    var tFit = fitSize(tw, th, 1200);
    var sFit = fitSize(sw, sh, 1200);
    var canvas = document.createElement('canvas');
    canvas.width = tFit.w;
    canvas.height = tFit.h;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(targetImg, 0, 0, tFit.w, tFit.h);

    var faceData = extractFacePatch(sourceImg, sm, sFit, sw, sh);
    var facePatch = faceData.patch;
    var scale = tm.eyeDist / Math.max(faceData.eyeDist, 1);
    var tcx = (tm.leftEye.x + tm.rightEye.x) * 0.5;
    var tcy = (tm.leftEye.y + tm.rightEye.y) * 0.5 + tm.eyeDist * 0.04;
    var tAngle = tm.angle;
    var rx = tm.faceW * 0.5;
    var ry = Math.max(tm.bottom - tm.top, tm.eyeDist * 1.65) * 0.52;

    var tone = sampleSkinTone(ctx, tcx, tcy + tm.eyeDist * 0.42, tm.eyeDist * 0.6);
    tintFacePatch(facePatch, tone, 0.28);

    ctx.save();
    ctx.translate(tcx, tcy);
    ctx.rotate(tAngle);
    var skinGrad = ctx.createRadialGradient(0, 0, Math.min(rx, ry) * 0.15, 0, 0, Math.max(rx, ry) * 1.05);
    skinGrad.addColorStop(0, 'rgba(' + Math.round(tone.r) + ',' + Math.round(tone.g) + ',' + Math.round(tone.b) + ',0.88)');
    skinGrad.addColorStop(0.72, 'rgba(' + Math.round(tone.r) + ',' + Math.round(tone.g) + ',' + Math.round(tone.b) + ',0.45)');
    skinGrad.addColorStop(1, 'rgba(' + Math.round(tone.r) + ',' + Math.round(tone.g) + ',' + Math.round(tone.b) + ',0)');
    ctx.fillStyle = skinGrad;
    ctx.beginPath();
    ctx.ellipse(0, 0, rx * 0.94, ry * 0.96, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    var faceLayer = document.createElement('canvas');
    faceLayer.width = tFit.w;
    faceLayer.height = tFit.h;
    var fctx = faceLayer.getContext('2d');
    fctx.save();
    fctx.translate(tcx, tcy);
    fctx.rotate(tAngle);
    fctx.scale(scale, scale);
    fctx.drawImage(facePatch, -faceData.eyeCenter.x, -faceData.eyeCenter.y);
    fctx.restore();

    var mask = createFeatherMask(tFit.w, tFit.h, tcx, tcy, rx, ry, tAngle);
    fctx.globalCompositeOperation = 'destination-in';
    fctx.drawImage(mask, 0, 0);
    fctx.globalCompositeOperation = 'source-over';

    ctx.save();
    ctx.globalAlpha = 0.94;
    ctx.drawImage(faceLayer, 0, 0);
    ctx.restore();

    ctx.save();
    ctx.globalAlpha = 0.14;
    ctx.globalCompositeOperation = 'soft-light';
    ctx.drawImage(faceLayer, 0, 0);
    ctx.restore();

    ctx.save();
    ctx.globalAlpha = 0.06;
    ctx.globalCompositeOperation = 'multiply';
    ctx.drawImage(faceLayer, 0, 0);
    ctx.restore();

    showSwapResultFromCanvas(canvas);
  }

  function exportCanvas(canvas) {
    try {
      return canvas.toDataURL('image/jpeg', 0.9);
    } catch (e1) {
      try {
        return canvas.toDataURL('image/png');
      } catch (e2) {
        return '';
      }
    }
  }

  function showSwapResultFromCanvas(canvas) {
    var dataUrl = exportCanvas(canvas);
    if (dataUrl) {
      showSwapResult(dataUrl);
      return;
    }
    if (resultCanvas) {
      resultCanvas.width = canvas.width;
      resultCanvas.height = canvas.height;
      resultCanvas.getContext('2d').drawImage(canvas, 0, 0);
      resultCanvas.hidden = false;
      if (resultImg) resultImg.hidden = true;
      if (resultEmpty) resultEmpty.hidden = true;
      if (downloadBtn) downloadBtn.hidden = false;
      try {
        resultDataUrl = resultCanvas.toDataURL('image/png');
      } catch (e) {
        resultDataUrl = '';
      }
    }
  }

  function finishSwap(sourceImg, targetImg) {
    var tw = targetImg.naturalWidth || targetImg.width;
    var th = targetImg.naturalHeight || targetImg.height;
    var sw = sourceImg.naturalWidth || sourceImg.width;
    var sh = sourceImg.naturalHeight || sourceImg.height;
    var tFit = fitSize(tw, th, 1200);
    var sFit = fitSize(sw, sh, 1200);
    renderRealisticSwap(sourceImg, targetImg, fallbackMetrics(sFit.w, sFit.h), fallbackMetrics(tFit.w, tFit.h));
  }

  function finishSwapWithMetrics(sourceImg, targetImg, sm, tm) {
    renderRealisticSwap(sourceImg, targetImg, sm, tm);
  }

  function performSwap() {
    return getSourceImage().then(function (sourceImg) {
      return getTargetImage(targetPerson).then(function (targetImg) {
        var tw = targetImg.naturalWidth || targetImg.width;
        var th = targetImg.naturalHeight || targetImg.height;
        var sw = sourceImg.naturalWidth || sourceImg.width;
        var sh = sourceImg.naturalHeight || sourceImg.height;
        var tFit = fitSize(tw, th, 1200);
        var sFit = fitSize(sw, sh, 1200);
        if (faceModelsReady && typeof faceapi !== 'undefined') {
          return withTimeout(Promise.all([
            detectFaceMetrics(sourceImg, sFit.w, sFit.h),
            detectFaceMetrics(targetImg, tFit.w, tFit.h)
          ]), 6000).then(function (pair) {
            finishSwapWithMetrics(sourceImg, targetImg, pair[0], pair[1]);
          }).catch(function () {
            finishSwap(sourceImg, targetImg);
          });
        }
        finishSwap(sourceImg, targetImg);
      });
    });
  }

  function showSwapError(err) {
    if (resultEmpty) resultEmpty.hidden = false;
    if (resultImg) resultImg.hidden = true;
    if (resultCanvas) resultCanvas.hidden = true;
    if (downloadBtn) downloadBtn.hidden = true;
    resultDataUrl = '';
    var msg = 'Could not process your images. Please upload a clear front-facing portrait and try again.';
    if (err && err.message === 'no upload') {
      msg = 'Please upload a clear portrait first.';
    }
    window.alert(msg);
  }

  function showSwapResult(dataUrl) {
    resultDataUrl = dataUrl;
    if (resultCanvas) resultCanvas.hidden = true;
    if (resultImg) {
      resultImg.src = dataUrl;
      resultImg.hidden = false;
    }
    if (resultEmpty) resultEmpty.hidden = true;
    if (downloadBtn) downloadBtn.hidden = false;
  }

  function updateSwapBtn() {
    if (!swapBtn) return;
    swapBtn.disabled = !customSourceUrl || busy;
  }

  function selectTargetPerson(idx) {
    targetPerson = idx;
    setActive(targetPersonBtns, 'data-df-target-person', targetPerson);
  }

  function handleFile(file) {
    if (!file || !file.type || file.type.indexOf('image/') !== 0) return;
    var reader = new FileReader();
    reader.onload = function () {
      customSourceUrl = reader.result;
      if (previewImg) previewImg.src = customSourceUrl;
      if (previewWrap) previewWrap.hidden = false;
      if (dropzoneEmpty) dropzoneEmpty.hidden = true;
      updateSwapBtn();
      loadFaceModels();
    };
    reader.readAsDataURL(file);
  }

  function runSwap(auto) {
    if (busy) return;
    if (!customSourceUrl) {
      window.alert('Please upload a clear portrait first.');
      return;
    }
    if (swapTimer) clearTimeout(swapTimer);
    setBusy(true);
    updateSwapBtn();
    if (!auto && resultStage && resultStage.scrollIntoView) {
      resultStage.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
    loadFaceModels();
    swapTimer = setTimeout(function () {
      performSwap().catch(showSwapError).finally(function () {
        setBusy(false);
        updateSwapBtn();
      });
    }, auto ? 300 : 600);
  }

  function landmarksToMetrics(landmarks) {
    var p = landmarks.positions;
    function pt(i) { return { x: p[i].x, y: p[i].y }; }
    function avg(indices) {
      var sx = 0;
      var sy = 0;
      indices.forEach(function (i) {
        sx += p[i].x;
        sy += p[i].y;
      });
      var n = indices.length;
      return { x: sx / n, y: sy / n };
    }
    function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }
    var leftEye = avg([36, 37, 38, 39, 40, 41]);
    var rightEye = avg([42, 43, 44, 45, 46, 47]);
    var jawL = pt(0);
    var jawR = pt(16);
    var chin = pt(8);
    var browL = pt(17);
    var browR = pt(26);
    var eyeDist = dist(leftEye, rightEye);
    return {
      leftEye: leftEye,
      rightEye: rightEye,
      jawL: jawL,
      jawR: jawR,
      chin: chin,
      browL: browL,
      browR: browR,
      eyeDist: eyeDist,
      faceW: dist(jawL, jawR),
      angle: Math.atan2(rightEye.y - leftEye.y, rightEye.x - leftEye.x),
      top: Math.min(browL.y, browR.y) - eyeDist * 0.45,
      bottom: chin.y + eyeDist * 0.35
    };
  }

  function detectOnCanvas(source, w, h) {
    var canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    canvas.getContext('2d').drawImage(source, 0, 0, w, h);
    var ssd = new faceapi.SsdMobilenetv1Options({ minConfidence: 0.38 });
    var tiny = new faceapi.TinyFaceDetectorOptions({ inputSize: 416, scoreThreshold: 0.22 });
    return faceapi.detectSingleFace(canvas, ssd).withFaceLandmarks().then(function (result) {
      if (result && result.landmarks) return landmarksToMetrics(result.landmarks);
      return faceapi.detectSingleFace(canvas, tiny).withFaceLandmarks().then(function (result2) {
        if (result2 && result2.landmarks) return landmarksToMetrics(result2.landmarks);
        return null;
      });
    });
  }

  function detectFaceMetrics(img, w, h) {
    if (!faceModelsReady || typeof faceapi === 'undefined') {
      return Promise.resolve(fallbackMetrics(w, h));
    }
    return withTimeout(
      detectOnCanvas(img, w, h).then(function (metrics) {
        return metrics || fallbackMetrics(w, h);
      }),
      4500
    ).catch(function () {
      return fallbackMetrics(w, h);
    });
  }

  function fitSize(w, h, maxDim) {
    if (Math.max(w, h) <= maxDim) return { w: w, h: h };
    var scale = maxDim / Math.max(w, h);
    return { w: Math.round(w * scale), h: Math.round(h * scale) };
  }

  function renderCustomSwap(sourceUrl, targetUrl) {
    customSourceUrl = sourceUrl;
    targetPerson = 0;
    return performSwap();
  }

  if (dropzone && fileInput) {
    dropzone.addEventListener('click', function () { fileInput.click(); });
    dropzone.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        fileInput.click();
      }
    });
    fileInput.addEventListener('change', function () {
      if (fileInput.files && fileInput.files[0]) handleFile(fileInput.files[0]);
    });
    ['dragenter', 'dragover'].forEach(function (evt) {
      dropzone.addEventListener(evt, function (e) {
        e.preventDefault();
        dropzone.classList.add('is-drag');
      });
    });
    ['dragleave', 'drop'].forEach(function (evt) {
      dropzone.addEventListener(evt, function (e) {
        e.preventDefault();
        dropzone.classList.remove('is-drag');
      });
    });
    dropzone.addEventListener('drop', function (e) {
      var file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
      handleFile(file);
    });
  }

  targetPersonBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var next = Number(btn.getAttribute('data-df-target-person'));
      if (next === targetPerson) return;
      selectTargetPerson(next);
    });
  });

  if (swapBtn) swapBtn.addEventListener('click', function () { runSwap(false); });

  if (downloadBtn) {
    downloadBtn.addEventListener('click', function () {
      if (!resultDataUrl) return;
      if (resultDataUrl.indexOf('data:') !== 0 && resultDataUrl.indexOf('blob:') !== 0) {
        fetchToDataUrl(resultDataUrl).then(function (dataUrl) {
          var link = document.createElement('a');
          link.href = dataUrl;
          link.download = 'deep-fake-swap.jpg';
          link.click();
        });
        return;
      }
      var link = document.createElement('a');
      link.href = resultDataUrl;
      link.download = 'deep-fake-swap.jpg';
      link.click();
    });
  }

  loadFaceModels();
  personSrc.concat(modelSrc).forEach(function (url) {
    cacheAssetDataUrl(url).catch(function () { /* preload optional */ });
  });
  updateSwapBtn();
})();

