function idaRenderLabels(listEl, labels) {
  if (!listEl) return;
  listEl.innerHTML = labels.map(function (item) {
    return '<li><span>' + item.name + '</span><span class="ida-label-score">' + item.score + ' %</span></li>';
  }).join('');
}

function idaRenderText(textEl, rows) {
  if (!textEl) return;
  textEl.innerHTML = rows.map(function (cells) {
    return '<div class="ida-text-row">' + cells.map(function (cell) {
      return '<span>| ' + cell + ' |</span>';
    }).join('') + '</div>';
  }).join('');
}

/* ==========================================================================
   Product page — Identity Document Analyzer intro demo
   ========================================================================== */
(function () {
  var root = document.getElementById('idaDemo');
  if (!root) return;

  var base = window.DS_ASSET_BASE || 'asset/';
  var samples = window.IDA_SAMPLES || [];
  var docIndex = 0;
  var docBtns = root.querySelectorAll('[data-ida-doc]');
  var previewImg = document.getElementById('idaPreviewImg');
  var previewStage = document.getElementById('idaPreviewStage');
  var loader = document.getElementById('idaLoader');
  var labelList = document.getElementById('idaLabelList');
  var textList = document.getElementById('idaTextList');
  var labelsToggle = document.getElementById('idaLabelsToggle');
  var textToggle = document.getElementById('idaTextToggle');
  var labelsPanel = document.getElementById('idaLabelsPanel');
  var textPanel = document.getElementById('idaTextPanel');
  var timer;

  function setActiveDoc(idx) {
    docBtns.forEach(function (btn) {
      var on = Number(btn.getAttribute('data-ida-doc')) === idx;
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
  }

  function renderSample(idx) {
    var sample = samples[idx];
    if (!sample) return;
    idaRenderLabels(labelList, sample.labels);
    idaRenderText(textList, sample.textRows);
    if (previewImg) {
      previewImg.src = base + sample.full;
      previewImg.alt = sample.title + ' document preview';
    }
  }

  function runLoader(cb) {
    if (timer) clearTimeout(timer);
    if (previewStage) previewStage.classList.add('is-loading');
    if (loader) loader.hidden = false;
    if (previewImg) previewImg.style.visibility = 'hidden';
    timer = setTimeout(function () {
      if (previewStage) previewStage.classList.remove('is-loading');
      if (loader) loader.hidden = true;
      if (previewImg) previewImg.style.visibility = '';
      cb();
    }, 1200);
  }

  docBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var next = Number(btn.getAttribute('data-ida-doc'));
      if (next === docIndex) return;
      docIndex = next;
      setActiveDoc(docIndex);
      runLoader(function () { renderSample(docIndex); });
    });
  });

  function bindAccordion(toggle, panel) {
    if (!toggle || !panel) return;
    toggle.addEventListener('click', function () {
      var open = toggle.classList.toggle('is-open');
      panel.classList.toggle('is-open', open);
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  }

  bindAccordion(labelsToggle, labelsPanel);
  bindAccordion(textToggle, textPanel);

  runLoader(function () { renderSample(docIndex); });
})();

/* ==========================================================================
   Product page — Identity Document Analyzer studio
   ========================================================================== */
(function () {
  var root = document.getElementById('idaStudio');
  if (!root) return;

  var samples = window.IDA_SAMPLES || [];
  var dropzone = document.getElementById('idaDropzone');
  var dropzoneEmpty = document.getElementById('idaDropzoneEmpty');
  var fileInput = document.getElementById('idaFileInput');
  var previewWrap = document.getElementById('idaPreviewWrap');
  var previewImg = document.getElementById('idaUploadPreview');
  var analyzeBtn = document.getElementById('idaAnalyzeBtn');
  var resultStage = document.getElementById('idaResultStage');
  var studioLoader = document.getElementById('idaStudioLoader');
  var studioEmpty = document.getElementById('idaStudioEmpty');
  var studioOutput = document.getElementById('idaStudioOutput');
  var studioLabels = document.getElementById('idaStudioLabels');
  var studioText = document.getElementById('idaStudioText');

  var hasImage = false;
  var busy = false;

  function updateAnalyzeBtn() {
    if (analyzeBtn) analyzeBtn.disabled = !hasImage || busy;
  }

  function showPreview(dataUrl) {
    hasImage = true;
    if (previewImg) previewImg.src = dataUrl;
    if (previewWrap) previewWrap.hidden = false;
    if (dropzoneEmpty) dropzoneEmpty.hidden = true;
    updateAnalyzeBtn();
  }

  function handleFile(file) {
    if (!file || !file.type || file.type.indexOf('image/') !== 0) return;
    var reader = new FileReader();
    reader.onload = function (ev) {
      showPreview(ev.target.result);
    };
    reader.readAsDataURL(file);
  }

  function runAnalysis() {
    if (!hasImage || busy) return;
    busy = true;
    updateAnalyzeBtn();
    if (studioEmpty) studioEmpty.hidden = true;
    if (studioOutput) studioOutput.hidden = true;
    if (studioLoader) studioLoader.hidden = false;

    var sample = samples[Math.floor(Math.random() * samples.length)] || samples[0];

    setTimeout(function () {
      if (studioLoader) studioLoader.hidden = true;
      if (studioOutput) studioOutput.hidden = false;
      idaRenderLabels(studioLabels, sample.labels);
      idaRenderText(studioText, sample.textRows);
      busy = false;
      updateAnalyzeBtn();
    }, 1800);
  }

  if (dropzone && fileInput) {
    dropzone.addEventListener('click', function () { fileInput.click(); });
    dropzone.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        fileInput.click();
      }
    });
    fileInput.addEventListener('change', function () {
      handleFile(fileInput.files && fileInput.files[0]);
    });
    ['dragenter', 'dragover'].forEach(function (evt) {
      dropzone.addEventListener(evt, function (e) {
        e.preventDefault();
        dropzone.classList.add('is-drag');
      });
    });
    ['dragleave', 'drop'].forEach(function (evt) {
      dropzone.addEventListener(evt, function (e) {
        e.preventDefault();
        dropzone.classList.remove('is-drag');
      });
    });
    dropzone.addEventListener('drop', function (e) {
      var file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
      handleFile(file);
    });
  }

  if (analyzeBtn) analyzeBtn.addEventListener('click', runAnalysis);
  updateAnalyzeBtn();
})();

/* ==========================================================================
   Product page — Traffic Analysis videos (autoplay + loop)
   ========================================================================== */
(function () {
  if (!document.body.classList.contains('ta-page')) return;

  var videos = document.querySelectorAll('.ta-video');
  if (!videos.length) return;

  function ensurePlaying(video) {
    video.muted = true;
    video.loop = true;
    video.setAttribute('playsinline', '');
    var p = video.play();
    if (p && typeof p.catch === 'function') p.catch(function () { /* autoplay blocked */ });
  }

  videos.forEach(function (video) {
    ensurePlaying(video);
    video.addEventListener('ended', function () {
      video.currentTime = 0;
      ensurePlaying(video);
    });
  });

  document.addEventListener('visibilitychange', function () {
    if (!document.hidden) videos.forEach(ensurePlaying);
  });
})();

/* ==========================================================================
   Certification page — filter + lightbox
   ========================================================================== */
(function () {
  if (!document.body.classList.contains('cert-page')) return;

  var filterRoot = document.getElementById('certFilter');
  var grid = document.getElementById('certGrid');
  var countEl = document.getElementById('certGalleryCount');
  var lightbox = document.getElementById('certLightbox');
  var lightboxImg = document.getElementById('certLightboxImg');
  var lightboxTitle = document.getElementById('certLightboxTitle');
  var lightboxClose = document.getElementById('certLightboxClose');
  var lightboxBackdrop = document.getElementById('certLightboxBackdrop');
  var cards = grid ? grid.querySelectorAll('.cert-card') : [];
  var filterBtns = filterRoot ? filterRoot.querySelectorAll('[data-cert-filter]') : [];

  function setFilter(cat) {
    filterBtns.forEach(function (btn) {
      var on = btn.getAttribute('data-cert-filter') === cat;
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    var visible = 0;
    cards.forEach(function (card) {
      var cardCat = card.getAttribute('data-cert-cat');
      var show = cat === 'all' || cardCat === cat;
      card.classList.toggle('is-hidden', !show);
      if (show) visible += 1;
    });
    if (countEl) {
      countEl.textContent = 'Showing ' + visible + ' certification' + (visible === 1 ? '' : 's');
    }
  }

  function openLightbox(title, src) {
    if (!lightbox || !lightboxImg) return;
    lightboxTitle.textContent = title || '';
    lightboxImg.src = src || '';
    lightboxImg.alt = title || 'Certification badge';
    lightbox.hidden = false;
    lightbox.setAttribute('aria-hidden', 'false');
    document.body.style.overflow = 'hidden';
  }

  function closeLightbox() {
    if (!lightbox) return;
    lightbox.hidden = true;
    lightbox.setAttribute('aria-hidden', 'true');
    if (lightboxImg) lightboxImg.src = '';
    document.body.style.overflow = '';
  }

  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setFilter(btn.getAttribute('data-cert-filter'));
    });
  });

  setFilter('all');

  cards.forEach(function (card) {
    card.addEventListener('click', function () {
      openLightbox(card.getAttribute('data-cert-title'), card.getAttribute('data-cert-img'));
    });
  });

  if (lightboxClose) lightboxClose.addEventListener('click', closeLightbox);
  if (lightboxBackdrop) lightboxBackdrop.addEventListener('click', closeLightbox);
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && lightbox && !lightbox.hidden) closeLightbox();
  });
})();

/* ==========================================================================
   Blogs listing page — filter, search, newsletter
   ========================================================================== */
(function () {
  if (!document.body.classList.contains('blog-page')) return;

  var PER_PAGE = 9;
  var filterRoot = document.getElementById('blogFilter');
  var grid = document.getElementById('blogGrid');
  var searchInput = document.getElementById('blogSearch');
  var countEl = document.getElementById('blogListCount');
  var emptyEl = document.getElementById('blogEmpty');
  var paginationEl = document.getElementById('blogPagination');
  var pageNumsEl = document.getElementById('blogPageNums');
  var pagePrev = document.getElementById('blogPagePrev');
  var pageNext = document.getElementById('blogPageNext');
  var cards = grid ? grid.querySelectorAll('.blog-list-card') : [];
  var filterBtns = filterRoot ? filterRoot.querySelectorAll('[data-blog-filter]') : [];
  var activeCat = 'all';
  var currentPage = 1;
  var newsletterForm = document.getElementById('blogNewsletterForm');
  var newsletterMsg = document.getElementById('blogNewsletterMsg');

  function getMatchingCards() {
    var q = searchInput ? searchInput.value.trim().toLowerCase() : '';
    var matching = [];
    cards.forEach(function (card) {
      var cat = card.getAttribute('data-blog-cat');
      var text = (card.getAttribute('data-blog-search') || '') + ' ' + (card.textContent || '');
      text = text.toLowerCase();
      var catOk = activeCat === 'all' || cat === activeCat;
      var searchOk = !q || text.indexOf(q) !== -1;
      if (catOk && searchOk) matching.push(card);
    });
    return matching;
  }

  function renderPageNumbers(totalPages) {
    if (!pageNumsEl) return;
    pageNumsEl.innerHTML = '';
    if (totalPages <= 1) return;

    function addBtn(page) {
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'blog-page-btn' + (page === currentPage ? ' is-on' : '');
      btn.textContent = String(page);
      btn.setAttribute('aria-label', 'Page ' + page);
      if (page === currentPage) btn.setAttribute('aria-current', 'page');
      btn.addEventListener('click', function () {
        goToPage(page);
      });
      pageNumsEl.appendChild(btn);
    }

    function addDots() {
      var span = document.createElement('span');
      span.className = 'blog-page-dots';
      span.textContent = '…';
      span.setAttribute('aria-hidden', 'true');
      pageNumsEl.appendChild(span);
    }

    if (totalPages <= 7) {
      for (var i = 1; i <= totalPages; i++) addBtn(i);
      return;
    }

    addBtn(1);
    if (currentPage > 3) addDots();
    var start = Math.max(2, currentPage - 1);
    var end = Math.min(totalPages - 1, currentPage + 1);
    for (var p = start; p <= end; p++) addBtn(p);
    if (currentPage < totalPages - 2) addDots();
    addBtn(totalPages);
  }

  function goToPage(page) {
    currentPage = page;
    applyFilters(false);
    var listSection = document.getElementById('blog-list');
    if (listSection) {
      listSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }

  function applyFilters(resetPage) {
    if (resetPage !== false) currentPage = 1;

    var matching = getMatchingCards();
    var totalPages = Math.max(1, Math.ceil(matching.length / PER_PAGE));
    if (currentPage > totalPages) currentPage = totalPages;

    cards.forEach(function (card) {
      card.classList.add('is-hidden');
    });

    matching.forEach(function (card, index) {
      var page = Math.floor(index / PER_PAGE) + 1;
      if (page === currentPage) card.classList.remove('is-hidden');
    });

    if (countEl) {
      var from = matching.length ? (currentPage - 1) * PER_PAGE + 1 : 0;
      var to = Math.min(currentPage * PER_PAGE, matching.length);
      countEl.textContent = matching.length
        ? 'Showing ' + from + '–' + to + ' of ' + matching.length + ' article' + (matching.length === 1 ? '' : 's')
        : 'Showing 0 articles';
    }

    if (emptyEl) emptyEl.hidden = matching.length > 0;

    if (paginationEl) {
      paginationEl.hidden = totalPages <= 1;
    }
    if (pagePrev) pagePrev.disabled = currentPage <= 1;
    if (pageNext) pageNext.disabled = currentPage >= totalPages;
    renderPageNumbers(totalPages);
  }

  function setCategory(cat) {
    activeCat = cat || 'all';
    filterBtns.forEach(function (btn) {
      var on = btn.getAttribute('data-blog-filter') === activeCat;
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    applyFilters(true);
  }

  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setCategory(btn.getAttribute('data-blog-filter'));
    });
  });

  if (searchInput) {
    searchInput.addEventListener('input', function () {
      applyFilters(true);
    });
  }

  if (pagePrev) {
    pagePrev.addEventListener('click', function () {
      if (currentPage > 1) goToPage(currentPage - 1);
    });
  }

  if (pageNext) {
    pageNext.addEventListener('click', function () {
      var matching = getMatchingCards();
      var totalPages = Math.max(1, Math.ceil(matching.length / PER_PAGE));
      if (currentPage < totalPages) goToPage(currentPage + 1);
    });
  }

  if (newsletterForm) {
    newsletterForm.addEventListener('submit', function (e) {
      e.preventDefault();
      if (newsletterMsg) {
        newsletterMsg.hidden = false;
      }
      newsletterForm.reset();
    });
  }

  setCategory('all');

  if (window.jQuery && $('#blogInsightsCarousel').length) {
    $('#blogInsightsCarousel').owlCarousel({
      loop: true,
      margin: 20,
      nav: false,
      dots: true,
      dotsContainer: '#blogInsightsDots',
      autoplay: true,
      autoplayTimeout: 6000,
      autoplayHoverPause: true,
      items: 1,
      slideBy: 1,
      center: false,
      stagePadding: 10,
      smartSpeed: 650,
      responsive: {
        0: { items: 1 },
        768: { items: 1 },
        1024: { items: 2.2 }
      }
    });
  }
})();

/* ==========================================================================
   Case Studies listing page — filter & search
   ========================================================================== */
(function () {
  if (!document.body.classList.contains('case-studies-page')) return;

  var filterRoot = document.getElementById('csFilter');
  var grid = document.getElementById('csGrid');
  var searchInput = document.getElementById('csSearch');
  var countEl = document.getElementById('csListCount');
  var emptyEl = document.getElementById('csEmpty');
  var cards = grid ? grid.querySelectorAll('.cs-list-card') : [];
  var filterBtns = filterRoot ? filterRoot.querySelectorAll('[data-cs-filter]') : [];
  var activeCat = 'all';

  function getMatchingCards() {
    var q = searchInput ? searchInput.value.trim().toLowerCase() : '';
    var matching = [];
    cards.forEach(function (card) {
      var cat = card.getAttribute('data-cs-cat');
      var text = (card.getAttribute('data-cs-search') || '') + ' ' + (card.textContent || '');
      text = text.toLowerCase();
      var catOk = activeCat === 'all' || cat === activeCat;
      var searchOk = !q || text.indexOf(q) !== -1;
      if (catOk && searchOk) matching.push(card);
    });
    return matching;
  }

  function applyFilters() {
    var matching = getMatchingCards();

    cards.forEach(function (card) {
      card.classList.add('is-hidden');
    });

    matching.forEach(function (card) {
      card.classList.remove('is-hidden');
    });

    if (countEl) {
      countEl.textContent = matching.length
        ? 'Showing ' + matching.length + ' case stud' + (matching.length === 1 ? 'y' : 'ies')
        : 'Showing 0 case studies';
    }

    if (emptyEl) emptyEl.hidden = matching.length > 0;
  }

  function setCategory(cat) {
    activeCat = cat || 'all';
    filterBtns.forEach(function (btn) {
      var on = btn.getAttribute('data-cs-filter') === activeCat;
      btn.classList.toggle('is-on', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    applyFilters();
  }

  filterBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      setCategory(btn.getAttribute('data-cs-filter'));
    });
  });

  if (searchInput) {
    searchInput.addEventListener('input', applyFilters);
  }

  setCategory('all');
})();

/* ==========================================================================
   Blog detail page — TOC highlight, copy link
   ========================================================================== */
(function () {
  if (!document.body.classList.contains('blog-detail-page') && !document.body.classList.contains('cs-detail-page')) return;

  var tocLinks = document.querySelectorAll('.blog-toc a[href^="#"]');
  var headings = [];

  tocLinks.forEach(function (link) {
    var id = link.getAttribute('href').slice(1);
    var el = document.getElementById(id);
    if (el) headings.push({ el: el, link: link });
  });

  if (headings.length && 'IntersectionObserver' in window) {
    var observer = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (!entry.isIntersecting) return;
          tocLinks.forEach(function (l) {
            l.classList.remove('is-active');
          });
          var match = headings.find(function (h) {
            return h.el === entry.target;
          });
          if (match) match.link.classList.add('is-active');
        });
      },
      { rootMargin: '-20% 0px -60% 0px', threshold: 0 }
    );
    headings.forEach(function (h) {
      observer.observe(h.el);
    });
  }

  document.querySelectorAll('.blog-share-copy').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var url = btn.getAttribute('data-share-url');
      if (!url || !navigator.clipboard) return;
      navigator.clipboard.writeText(url).then(function () {
        btn.classList.add('is-copied');
        setTimeout(function () {
          btn.classList.remove('is-copied');
        }, 2000);
      });
    });
  });
})();

/* ==========================================================================
   Fintech AI Playground — playgrounds/fintech.html
   ========================================================================== */
(() => {
  'use strict';

  const root = document.getElementById('fintech-playground');
  if (!root) return;

  function fitCanvas(canvas) {
    if (!canvas || !canvas.parentElement) return null;
    const rect = canvas.parentElement.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    const w = Math.max(1, Math.round(rect.width));
    const h = Math.max(1, Math.round(rect.height));
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return { ctx, w, h };
  }

  function fmtMoney(n) {
    return '$' + Math.round(n).toLocaleString('en-US');
  }

  function fmtPct(n, d) {
    return Number(n).toFixed(d === undefined ? 1 : d) + '%';
  }

  let activeTab = 'risk';
  const navItems = root.querySelectorAll('.ml-play-tab');
  const panels = root.querySelectorAll('.ml-play-pane');

  function onTabSwitch(tab) {
    if (tab === 'risk') drawRiskGauge();
    if (tab === 'portfolio') drawPortfolio();
  }

  navItems.forEach(function (btn) {
    btn.addEventListener('click', function () {
      const tab = btn.dataset.tab;
      if (tab === activeTab) return;
      activeTab = tab;
      navItems.forEach(function (b) {
        const on = b === btn;
        b.classList.toggle('is-active', on);
        b.setAttribute('aria-selected', on ? 'true' : 'false');
      });
      panels.forEach(function (p) {
        const on = p.dataset.panel === tab;
        p.classList.toggle('is-active', on);
        p.hidden = !on;
      });
      btn.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
      requestAnimationFrame(function () { onTabSwitch(tab); });
    });
  });

  /* ---- Risk Scoring ---- */
  const incomeEl = document.getElementById('ft-income');
  const dtiEl = document.getElementById('ft-dti');
  const historyEl = document.getElementById('ft-history');
  const lateEl = document.getElementById('ft-late');

  function computeCreditScore() {
    const income = +incomeEl.value;
    const dti = +dtiEl.value;
    const history = +historyEl.value;
    const late = +lateEl.value;
    let score = 680;
    score += Math.min(80, (income - 30000) / 2500);
    score -= dti * 2.8;
    score += history * 6;
    score -= late * 28;
    return Math.max(300, Math.min(850, Math.round(score)));
  }

  function scoreTier(score) {
    if (score >= 740) return { label: 'Excellent', pd: 0.4, apr: 5.9 };
    if (score >= 670) return { label: 'Good', pd: 1.8, apr: 8.4 };
    if (score >= 580) return { label: 'Fair', pd: 5.2, apr: 14.2 };
    return { label: 'Poor', pd: 12.5, apr: 22.8 };
  }

  function drawRiskGauge() {
    const canvas = document.getElementById('chart-ft-risk');
    const dims = fitCanvas(canvas);
    if (!dims) return;
    const { ctx, w, h } = dims;
    const score = computeCreditScore();
    const tier = scoreTier(score);
    const cx = w / 2;
    const cy = h * 0.72;
    const r = Math.min(w, h) * 0.38;
    const start = Math.PI;
    const end = 2 * Math.PI;

    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = 'rgba(244,241,234,0.04)';
    ctx.fillRect(0, 0, w, h);

    const segments = [
      { from: 300, to: 580, color: '#ff6b6b' },
      { from: 580, to: 670, color: '#F58220' },
      { from: 670, to: 740, color: '#ffc633' },
      { from: 740, to: 850, color: '#1fedae' }
    ];

    segments.forEach(function (seg) {
      const a0 = start + ((seg.from - 300) / 550) * (end - start);
      const a1 = start + ((seg.to - 300) / 550) * (end - start);
      ctx.beginPath();
      ctx.arc(cx, cy, r, a0, a1);
      ctx.strokeStyle = seg.color;
      ctx.lineWidth = 14;
      ctx.lineCap = 'round';
      ctx.stroke();
    });

    const needleAngle = start + ((score - 300) / 550) * (end - start);
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(needleAngle);
    ctx.beginPath();
    ctx.moveTo(-8, 0);
    ctx.lineTo(r - 18, 0);
    ctx.strokeStyle = '#f4f1ea';
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, 0, 8, 0, Math.PI * 2);
    ctx.fillStyle = '#F58220';
    ctx.fill();
    ctx.restore();

    ctx.font = '700 42px Urbanist, sans-serif';
    ctx.fillStyle = '#f4f1ea';
    ctx.textAlign = 'center';
    ctx.fillText(String(score), cx, cy - r * 0.35);
    ctx.font = '600 11px "JetBrains Mono", monospace';
    ctx.fillStyle = 'rgba(244,241,234,0.45)';
    ctx.fillText('CREDIT SCORE', cx, cy - r * 0.35 + 22);

    document.getElementById('m-ft-score').textContent = String(score);
    document.getElementById('m-ft-tier').textContent = tier.label;
    document.getElementById('m-ft-pd').textContent = fmtPct(tier.pd);
    document.getElementById('m-ft-apr').textContent = fmtPct(tier.apr);
    document.getElementById('hud-ft-risk').innerHTML =
      'Score = f(income, DTI, history) <span class="dim">|</span> <span class="is-accent2">Tier: ' + tier.label + '</span>';
  }

  function updateRiskLabels() {
    document.getElementById('val-ft-income').textContent = fmtMoney(+incomeEl.value);
    document.getElementById('val-ft-dti').textContent = dtiEl.value + '%';
    document.getElementById('val-ft-history').textContent = historyEl.value;
    document.getElementById('val-ft-late').textContent = lateEl.value;
    drawRiskGauge();
  }

  [incomeEl, dtiEl, historyEl, lateEl].forEach(function (el) {
    el.addEventListener('input', updateRiskLabels);
  });

  /* ---- Fraud Monitor ---- */
  const PROFILE_LABELS = ['Conservative', 'Balanced', 'Aggressive'];
  const REBAL_LABELS = ['Weekly', 'Monthly', 'Quarterly'];
  const VOL_LABELS = ['Low', 'Medium', 'High'];
  const MERCHANTS = ['Amazon', 'Uber Eats', 'Wire Transfer', 'Crypto Exchange', 'Best Buy', 'Shell Gas', 'Apple Store', 'Booking.com', 'Unknown Merchant', 'ATM Withdrawal'];
  const LOCATIONS = ['London, UK', 'Mumbai, IN', 'New York, US', 'Lagos, NG', 'Dubai, AE', 'Singapore, SG'];

  let fraudTxns = [];

  function mulberry32(seed) {
    return function () {
      seed |= 0;
      seed = (seed + 0x6d2b79f5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function genFraudBatch() {
    const rng = mulberry32(Date.now() & 0xffffffff);
    fraudTxns = [];
    for (let i = 0; i < 12; i++) {
      const amount = Math.round((rng() * 4800 + 12) * 100) / 100;
      const merchant = MERCHANTS[Math.floor(rng() * MERCHANTS.length)];
      const location = LOCATIONS[Math.floor(rng() * LOCATIONS.length)];
      let risk = rng() * 35 + 8;
      if (merchant === 'Wire Transfer' || merchant === 'Crypto Exchange') risk += rng() * 40;
      if (merchant === 'Unknown Merchant') risk += rng() * 30;
      if (amount > 3000) risk += 15;
      fraudTxns.push({
        id: 'TXN-' + Math.floor(rng() * 900000 + 100000),
        merchant: merchant,
        location: location,
        amount: amount,
        risk: Math.min(99, Math.round(risk))
      });
    }
    renderFraudFeed();
  }

  function renderFraudFeed() {
    const thresh = +document.getElementById('ft-fraud-thresh').value;
    const feed = document.getElementById('ft-fraud-feed');
    feed.innerHTML = '';
    let flagged = 0;
    let totalRisk = 0;
    let saved = 0;

    fraudTxns.forEach(function (txn) {
      totalRisk += txn.risk;
      const isFlagged = txn.risk >= thresh;
      if (isFlagged) {
        flagged++;
        saved += txn.amount * 0.85;
      }
      const row = document.createElement('div');
      row.className = 'ip-play-feed-row' + (isFlagged ? ' is-flagged' : txn.risk >= thresh - 12 ? ' is-warn' : '');
      row.setAttribute('role', 'listitem');
      const chipClass = txn.risk >= thresh ? 'is-high' : txn.risk >= thresh - 15 ? 'is-mid' : 'is-low';
      row.innerHTML =
        '<div class="ip-play-feed-main"><strong>' + txn.merchant + '</strong><span>' + txn.id + ' · ' + txn.location + '</span></div>' +
        '<span class="ip-play-feed-amt">' + fmtMoney(txn.amount) + '</span>' +
        '<span class="ip-play-chip ' + chipClass + '">' + txn.risk + '% risk</span>';
      feed.appendChild(row);
    });

    const avg = fraudTxns.length ? Math.round(totalRisk / fraudTxns.length) : 0;
    document.getElementById('m-ft-fraud-total').textContent = String(fraudTxns.length);
    document.getElementById('m-ft-fraud-flagged').textContent = flagged + ' / ' + fraudTxns.length;
    document.getElementById('m-ft-fraud-avg').textContent = avg + '%';
    document.getElementById('m-ft-fraud-saved').textContent = fmtMoney(saved);
    document.getElementById('hud-ft-fraud').innerHTML =
      'Monitoring <span class="dim">|</span> <span class="is-accent2">' + flagged + ' flagged</span>';
  }

  document.getElementById('ft-fraud-thresh').addEventListener('input', function () {
    document.getElementById('val-ft-fraud-thresh').textContent = this.value + '%';
    renderFraudFeed();
  });
  document.getElementById('ft-fraud-vel').addEventListener('input', function () {
    document.getElementById('val-ft-fraud-vel').textContent = this.value;
  });
  document.getElementById('ft-fraud-refresh').addEventListener('click', genFraudBatch);
  document.getElementById('ft-fraud-scan').addEventListener('click', renderFraudFeed);

  /* ---- Portfolio ---- */
  const profileEl = document.getElementById('ft-profile');
  const rebalEl = document.getElementById('ft-rebal');
  const volEl = document.getElementById('ft-vol');
  let portfolioSeed = 42;

  function simulatePortfolio() {
    const profile = +profileEl.value;
    const vol = +volEl.value;
    const equityPct = [35, 60, 85][profile];
    const volMult = [0.6, 1, 1.45][vol];
    const rng = mulberry32(portfolioSeed);
    const days = 60;
    const values = [100000];
    const bench = [100000];
    let maxVal = 100000;
    let maxDd = 0;

    for (let d = 1; d <= days; d++) {
      const ret = (rng() - 0.48) * 0.018 * volMult * (equityPct / 60);
      const bRet = (rng() - 0.49) * 0.012;
      const next = values[d - 1] * (1 + ret);
      values.push(next);
      bench.push(bench[d - 1] * (1 + bRet));
      maxVal = Math.max(maxVal, next);
      maxDd = Math.max(maxDd, (maxVal - next) / maxVal);
    }

    const totalRet = ((values[values.length - 1] - values[0]) / values[0]) * 100;
    const dailyRets = [];
    for (let i = 1; i < values.length; i++) {
      dailyRets.push((values[i] - values[i - 1]) / values[i - 1]);
    }
    const mean = dailyRets.reduce(function (a, b) { return a + b; }, 0) / dailyRets.length;
    const variance = dailyRets.reduce(function (a, b) { return a + Math.pow(b - mean, 2); }, 0) / dailyRets.length;
    const sharpe = variance > 0 ? ((mean / Math.sqrt(variance)) * Math.sqrt(252)).toFixed(2) : '0.00';

    return { values: values, bench: bench, totalRet: totalRet, sharpe: sharpe, maxDd: maxDd * 100, equityPct: equityPct };
  }

  function drawPortfolio() {
    const canvas = document.getElementById('chart-ft-portfolio');
    const dims = fitCanvas(canvas);
    if (!dims) return;
    const { ctx, w, h } = dims;
    const sim = simulatePortfolio();
    const pad = { l: 48, r: 16, t: 20, b: 32 };
    const vals = sim.values;
    const bench = sim.bench;
    const minV = Math.min.apply(null, vals.concat(bench)) * 0.998;
    const maxV = Math.max.apply(null, vals.concat(bench)) * 1.002;

    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = 'rgba(244,241,234,0.03)';
    ctx.fillRect(0, 0, w, h);

    function toX(i) {
      return pad.l + (i / (vals.length - 1)) * (w - pad.l - pad.r);
    }
    function toY(v) {
      return h - pad.b - ((v - minV) / (maxV - minV)) * (h - pad.t - pad.b);
    }

    ctx.strokeStyle = 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = pad.t + (i / 4) * (h - pad.t - pad.b);
      ctx.beginPath();
      ctx.moveTo(pad.l, y);
      ctx.lineTo(w - pad.r, y);
      ctx.stroke();
    }

    ctx.beginPath();
    bench.forEach(function (v, i) {
      const x = toX(i);
      const y = toY(v);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.strokeStyle = '#b25bff';
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.beginPath();
    vals.forEach(function (v, i) {
      const x = toX(i);
      const y = toY(v);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.strokeStyle = '#22f2ff';
    ctx.lineWidth = 2.5;
    ctx.stroke();

    const profileName = PROFILE_LABELS[+profileEl.value];
    document.getElementById('val-ft-profile').textContent = profileName;
    document.getElementById('val-ft-rebal').textContent = REBAL_LABELS[+rebalEl.value];
    document.getElementById('val-ft-vol').textContent = VOL_LABELS[+volEl.value];
    document.getElementById('m-ft-ret').textContent = (sim.totalRet >= 0 ? '+' : '') + fmtPct(sim.totalRet);
    document.getElementById('m-ft-sharpe').textContent = sim.sharpe;
    document.getElementById('m-ft-dd').textContent = fmtPct(sim.maxDd);
    document.getElementById('m-ft-equity').textContent = sim.equityPct + '%';
    document.getElementById('hud-ft-portfolio').innerHTML =
      '60-day simulation <span class="dim">|</span> <span class="is-accent2">' + profileName + ' profile</span>';
  }

  [profileEl, rebalEl, volEl].forEach(function (el) {
    el.addEventListener('input', drawPortfolio);
  });

  window.addEventListener('resize', function () {
    if (activeTab === 'risk') drawRiskGauge();
    if (activeTab === 'portfolio') drawPortfolio();
  });

  updateRiskLabels();
  genFraudBatch();
})();

/* ==========================================================================
   Healthcare AI Playground — playgrounds/healthcare.html
   ========================================================================== */
(() => {
  'use strict';

  const root = document.getElementById('healthcare-playground');
  if (!root) return;

  function fitCanvas(canvas) {
    if (!canvas || !canvas.parentElement) return null;
    const rect = canvas.parentElement.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    const w = Math.max(1, Math.round(rect.width));
    const h = Math.max(1, Math.round(rect.height));
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return { ctx, w, h };
  }

  let activeTab = 'triage';
  const navItems = root.querySelectorAll('.ml-play-tab');
  const panels = root.querySelectorAll('.ml-play-pane');

  navItems.forEach(function (btn) {
    btn.addEventListener('click', function () {
      const tab = btn.dataset.tab;
      if (tab === activeTab) return;
      activeTab = tab;
      navItems.forEach(function (b) {
        const on = b === btn;
        b.classList.toggle('is-active', on);
        b.setAttribute('aria-selected', on ? 'true' : 'false');
      });
      panels.forEach(function (p) {
        const on = p.dataset.panel === tab;
        p.classList.toggle('is-active', on);
        p.hidden = !on;
      });
      btn.scrollIntoView({ inline: 'center', block: 'nearest', behavior: 'smooth' });
      if (tab === 'imaging') requestAnimationFrame(drawImaging);
    });
  });

  /* ---- Clinical Triage ---- */
  const ESI_INFO = {
    1: { desc: 'Immediate — life-threatening. Resuscitation required.', wait: 'Immediate', resource: 'Full trauma team', priority: 'Critical' },
    2: { desc: 'Emergent — high risk. Should not wait.', wait: '< 10 min', resource: 'Physician + monitoring', priority: 'High' },
    3: { desc: 'Urgent — stable but needs multiple resources.', wait: '10–30 min', resource: 'Labs + imaging', priority: 'Moderate' },
    4: { desc: 'Less urgent — one resource expected.', wait: '30–60 min', resource: 'Single diagnostic', priority: 'Standard' },
    5: { desc: 'Non-urgent — may be fast-tracked or referred.', wait: '60+ min', resource: 'Clinic referral', priority: 'Low' }
  };

  function computeTriage() {
    const symptoms = [];
    root.querySelectorAll('#hc-symptoms input:checked').forEach(function (cb) {
      symptoms.push(cb.value);
    });
    const age = +document.getElementById('hc-age').value;
    const hr = +document.getElementById('hc-hr').value;
    const spo2 = +document.getElementById('hc-spo2').value;
    const pain = +document.getElementById('hc-pain').value;

    let urgency = 20;
    if (symptoms.indexOf('consciousness') >= 0) urgency += 45;
    if (symptoms.indexOf('bleeding') >= 0) urgency += 40;
    if (symptoms.indexOf('chest-pain') >= 0) urgency += 30;
    if (symptoms.indexOf('breathing') >= 0) urgency += 28;
    if (symptoms.indexOf('fever') >= 0) urgency += 12;
    if (symptoms.indexOf('abd-pain') >= 0) urgency += 10;
    if (spo2 < 92) urgency += 35;
    else if (spo2 < 95) urgency += 18;
    if (hr > 120) urgency += 22;
    else if (hr > 100) urgency += 10;
    if (pain >= 8) urgency += 15;
    if (age >= 65) urgency += 8;

    let esi = 5;
    if (urgency >= 75) esi = 1;
    else if (urgency >= 55) esi = 2;
    else if (urgency >= 38) esi = 3;
    else if (urgency >= 22) esi = 4;

    const info = ESI_INFO[esi];
    const card = document.getElementById('hc-esi-card');
    card.className = 'ip-play-esi-card is-esi-' + esi;
    document.getElementById('hc-esi-num').textContent = String(esi);
    document.getElementById('hc-esi-desc').textContent = info.desc;
    document.getElementById('hud-hc-esi').textContent = 'ESI ' + esi + ' — ' + info.priority;
    document.getElementById('hc-esi-meta').innerHTML =
      '<li>Wait time: ' + info.wait + '</li><li>Resources: ' + info.resource + '</li><li>Symptoms flagged: ' + symptoms.length + '</li>';
    document.getElementById('m-hc-urgency').textContent = urgency + '/100';
    document.getElementById('m-hc-wait').textContent = info.wait;
    document.getElementById('m-hc-resource').textContent = info.resource;
    document.getElementById('m-hc-priority').textContent = info.priority;
  }

  ['hc-age', 'hc-hr', 'hc-spo2', 'hc-pain'].forEach(function (id) {
    const el = document.getElementById(id);
    el.addEventListener('input', function () {
      const labelMap = { 'hc-age': 'val-hc-age', 'hc-hr': 'val-hc-hr', 'hc-spo2': 'val-hc-spo2', 'hc-pain': 'val-hc-pain' };
      document.getElementById(labelMap[id]).textContent = this.value;
      computeTriage();
    });
  });
  root.querySelectorAll('#hc-symptoms input').forEach(function (cb) {
    cb.addEventListener('change', computeTriage);
  });

  /* ---- Diagnostic Assist ---- */
  const DX_RULES = {
    chest: {
      pain: [{ name: 'Unstable Angina', conf: 0.74 }, { name: 'Acute Coronary Syndrome', conf: 0.61 }, { name: 'Costochondritis', conf: 0.38 }],
      fatigue: [{ name: 'Heart Failure', conf: 0.58 }, { name: 'Anaemia', conf: 0.42 }],
      default: [{ name: 'Hypertensive Crisis', conf: 0.45 }, { name: 'Anxiety Disorder', conf: 0.32 }]
    },
    respiratory: {
      pain: [{ name: 'Pulmonary Embolism', conf: 0.68 }, { name: 'Pneumothorax', conf: 0.52 }],
      fever: [{ name: 'Community-Acquired Pneumonia', conf: 0.71 }, { name: 'COVID-19', conf: 0.55 }],
      default: [{ name: 'Asthma Exacerbation', conf: 0.48 }, { name: 'COPD Flare', conf: 0.41 }]
    },
    neuro: {
      dizziness: [{ name: 'Vertigo (BPPV)', conf: 0.66 }, { name: 'Migraine', conf: 0.54 }],
      pain: [{ name: 'Tension Headache', conf: 0.62 }, { name: 'Subarachnoid Haemorrhage', conf: 0.28 }],
      default: [{ name: 'Transient Ischaemic Attack', conf: 0.35 }, { name: 'Viral Meningitis', conf: 0.22 }]
    },
    gi: {
      pain: [{ name: 'Acute Appendicitis', conf: 0.63 }, { name: 'Gastroenteritis', conf: 0.51 }],
      nausea: [{ name: 'Peptic Ulcer Disease', conf: 0.55 }, { name: 'Gastritis', conf: 0.47 }],
      fever: [{ name: 'Cholecystitis', conf: 0.58 }, { name: 'Hepatitis', conf: 0.36 }],
      default: [{ name: 'IBS Flare', conf: 0.4 }, { name: 'Constipation', conf: 0.28 }]
    }
  };

  function runDiagnostic() {
    const region = document.getElementById('hc-region').value;
    const selected = [];
    root.querySelectorAll('#hc-dx-symptoms input:checked').forEach(function (cb) {
      selected.push(cb.value);
    });
    const rules = DX_RULES[region] || DX_RULES.chest;
    const merged = {};
    selected.forEach(function (sym) {
      (rules[sym] || []).forEach(function (dx) {
        if (!merged[dx.name] || merged[dx.name] < dx.conf) merged[dx.name] = dx.conf;
      });
    });
    if (!Object.keys(merged).length) {
      (rules.default || []).forEach(function (dx) {
        merged[dx.name] = dx.conf;
      });
    }
    const ranked = Object.keys(merged).map(function (name) {
      return { name: name, conf: merged[name] };
    }).sort(function (a, b) { return b.conf - a.conf; }).slice(0, 5);

    const container = document.getElementById('hc-differentials');
    container.innerHTML = '';
    ranked.forEach(function (dx) {
      const row = document.createElement('div');
      row.className = 'ip-play-dx-row';
      row.innerHTML =
        '<div class="ip-play-dx-row-head">' + dx.name + '<span>' + Math.round(dx.conf * 100) + '%</span></div>' +
        '<div class="ip-play-dx-bar"><i style="width:' + Math.round(dx.conf * 100) + '%"></i></div>';
      container.appendChild(row);
    });

    const top = ranked[0];
    const topConf = top ? Math.round(top.conf * 100) + '%' : '—';
    document.getElementById('hud-hc-top').textContent = top ? top.name + ' (' + topConf + ')' : '—';
    document.getElementById('m-hc-dx-conf').textContent = topConf;
    document.getElementById('m-hc-dx-count').textContent = String(ranked.length);
    document.getElementById('m-hc-dx-flag').textContent = top && top.conf >= 0.65 ? 'Physician review' : 'Routine';
    document.getElementById('m-hc-dx-time').textContent = (120 + ranked.length * 18) + ' ms';
  }

  document.getElementById('hc-region').addEventListener('change', runDiagnostic);
  root.querySelectorAll('#hc-dx-symptoms input').forEach(function (cb) {
    cb.addEventListener('change', runDiagnostic);
  });
  document.getElementById('hc-dx-run').addEventListener('click', runDiagnostic);

  /* ---- Medical Imaging ---- */
  let imgSeed = 77;
  let imgFindings = [];

  function mulberry32(seed) {
    return function () {
      seed |= 0;
      seed = (seed + 0x6d2b79f5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function genImagingFindings() {
    const rng = mulberry32(imgSeed);
    imgFindings = [];
    const count = rng() > 0.35 ? 1 + Math.floor(rng() * 2) : 0;
    for (let i = 0; i < count; i++) {
      imgFindings.push({
        x: 0.28 + rng() * 0.44,
        y: 0.22 + rng() * 0.38,
        r: 0.06 + rng() * 0.05,
        conf: 0.55 + rng() * 0.4
      });
    }
  }

  function drawImaging() {
    const canvas = document.getElementById('chart-hc-imaging');
    const dims = fitCanvas(canvas);
    if (!dims) return;
    const { ctx, w, h } = dims;
    const sens = +document.getElementById('hc-img-sens').value / 100;
    const showHeat = document.getElementById('hc-img-heatmap').checked;
    const showBoxes = document.getElementById('hc-img-boxes').checked;
    const rng = mulberry32(imgSeed + 1);

    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#0a0c14';
    ctx.fillRect(0, 0, w, h);

    const cx = w * 0.5;
    const cy = h * 0.48;
    const rx = w * 0.32;
    const ry = h * 0.38;

    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(rx, ry);
    ctx.beginPath();
    ctx.ellipse(0, 0, 1, 1.15, 0, 0, Math.PI * 2);
    ctx.fillStyle = '#1a2030';
    ctx.fill();
    ctx.restore();

    for (let i = 0; i < 8000; i++) {
      const px = rng() * w;
      const py = rng() * h;
      const dx = (px - cx) / rx;
      const dy = (py - cy) / ry;
      if (dx * dx + dy * dy < 1.1) {
        const g = 40 + Math.floor(rng() * 90);
        ctx.fillStyle = 'rgb(' + g + ',' + g + ',' + (g + 15) + ')';
        ctx.fillRect(px, py, 1.2, 1.2);
      }
    }

    ctx.strokeStyle = 'rgba(244,241,234,0.15)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(cx, cy - ry);
    ctx.lineTo(cx, cy + ry);
    ctx.stroke();

    let visible = 0;
    let maxConf = 0;
    imgFindings.forEach(function (f) {
      if (f.conf < sens) return;
      visible++;
      maxConf = Math.max(maxConf, f.conf);
      const fx = f.x * w;
      const fy = f.y * h;
      const fr = f.r * Math.min(w, h);

      if (showHeat) {
        const grad = ctx.createRadialGradient(fx, fy, 0, fx, fy, fr * 1.8);
        grad.addColorStop(0, 'rgba(255,122,61,' + (f.conf * 0.55) + ')');
        grad.addColorStop(1, 'rgba(255,122,61,0)');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(fx, fy, fr * 1.8, 0, Math.PI * 2);
        ctx.fill();
      }

      if (showBoxes) {
        ctx.strokeStyle = '#ff7a3d';
        ctx.lineWidth = 2;
        ctx.strokeRect(fx - fr, fy - fr, fr * 2, fr * 2);
        ctx.font = '600 10px "JetBrains Mono", monospace';
        ctx.fillStyle = '#ff7a3d';
        ctx.fillText(Math.round(f.conf * 100) + '%', fx - fr + 4, fy - fr - 4);
      }
    });

    document.getElementById('hud-hc-findings').textContent = visible + ' finding' + (visible !== 1 ? 's' : '');
    document.getElementById('m-hc-img-findings').textContent = String(visible);
    document.getElementById('m-hc-img-conf').textContent = visible ? Math.round(maxConf * 100) + '%' : '—';
    document.getElementById('m-hc-img-time').textContent = '842 ms';
    document.getElementById('m-hc-img-status').textContent = visible ? 'Pending review' : 'Clear';
  }

  document.getElementById('hc-img-sens').addEventListener('input', function () {
    document.getElementById('val-hc-img-sens').textContent = this.value + '%';
    drawImaging();
  });
  document.getElementById('hc-img-heatmap').addEventListener('change', drawImaging);
  document.getElementById('hc-img-boxes').addEventListener('change', drawImaging);
  document.getElementById('hc-img-reset').addEventListener('click', function () {
    imgSeed = (Date.now() & 0xffff) + Math.floor(Math.random() * 1000);
    genImagingFindings();
    drawImaging();
  });

  window.addEventListener('resize', function () {
    if (activeTab === 'imaging') drawImaging();
  });

  computeTriage();
  runDiagnostic();
  genImagingFindings();
  drawImaging();
})();
